}

func (s *Sample) Terminal() bool {
	switch s.Status {
	case SampleStatusReceived, SampleStatusCancelled, SampleStatusExpired, SampleStatusUnserviceable:
		return true
	}
	return false
}

func (s *Sample) RequiresCooled() bool {
	return s.TemperatureMaxC < 8
}

type RouteMode string

const (
