// Package domain holds the persistent entity model for the lab sample network.
package domain

import "time"

type Role string

const (
	RoleAdministrator        Role = "administrator"
	RoleDispatcher           Role = "dispatcher"
	RoleRequester            Role = "requester"
	RoleCollectionProfession Role = "collection_professional"
	RoleDeliveryPartner      Role = "delivery_partner"
	RoleNodeHandler          Role = "node_handler"
	RoleLaboratoryTeam       Role = "laboratory_team"
)

// AllRoles lists every role the system recognises.
var AllRoles = []Role{
	RoleAdministrator,
	RoleDispatcher,
	RoleRequester,
	RoleCollectionProfession,
	RoleDeliveryPartner,
	RoleNodeHandler,
	RoleLaboratoryTeam,
}

func ValidRole(r Role) bool {
	for _, c := range AllRoles {
		if c == r {
			return true
		}
	}
	return false
}

type LocationFunction string

const (
	FunctionCollectionPoint LocationFunction = "collection_point"
	FunctionTransferPoint   LocationFunction = "transfer_point"
	FunctionHub             LocationFunction = "hub"
	FunctionLaboratory      LocationFunction = "laboratory"
)

func ValidLocationFunction(f LocationFunction) bool {
	switch f {
	case FunctionCollectionPoint, FunctionTransferPoint, FunctionHub, FunctionLaboratory:
		return true
	}
	return false
}

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

// User is an account with zero or more roles and an explicitly selected active role.
type User struct {
	UserID             string          `json:"userId"`
	Username           string          `json:"username"`
	PasswordHash       string          `json:"passwordHash"`
	Email              string          `json:"email,omitempty"`
	FullName           string          `json:"fullName,omitempty"`
	Phone              string          `json:"phone,omitempty"`
	Roles              []Role          `json:"roles"`
	Qualifications     []string        `json:"qualifications"`
	Certifications     []Certification `json:"certifications"`
	Active             bool            `json:"active"`
	AssignedLocationID string          `json:"assignedLocationId,omitempty"`
	Available          bool            `json:"available"`
	CapacityUnits      int             `json:"capacityUnits"`
	LatestLocation     *Coordinate     `json:"latestLocation,omitempty"`
	LocationRecordedAt *time.Time      `json:"locationRecordedAt,omitempty"`
	DeclineCount       int             `json:"declineCount"`
	DeclinePenaltyUntil *time.Time     `json:"declinePenaltyUntil,omitempty"`
	LastAssignedAt     *time.Time      `json:"lastAssignedAt,omitempty"`
	TotalAssignments   int             `json:"totalAssignments"`
	CreatedAt          time.Time       `json:"createdAt"`
	UpdatedAt          time.Time       `json:"updatedAt"`
}

func (u *User) HasRole(r Role) bool {
	for _, c := range u.Roles {
		if c == r {
			return true
		}
	}
	return false
}

func (u *User) HasQualification(code string) bool {
	if code == "" {
		return true
	}
	for _, q := range u.Qualifications {
		if q == code {
			return true
		}
	}
	return false
}

// HasActiveCertification reports whether the user holds a matching non-expired certification.
func (u *User) HasActiveCertification(code string, now time.Time) bool {
	if code == "" {
		return true
	}
	for _, c := range u.Certifications {
		if c.Code != code {
			continue
		}
		if !c.Active {
			return false
		}
		if c.ExpiresAt != nil && c.ExpiresAt.Before(now) {
			return false
		}
		return true
	}
	return false
}

type Session struct {
	Token      string    `json:"token"`
	UserID     string    `json:"userId"`
	ActiveRole Role      `json:"activeRole"`
	CreatedAt  time.Time `json:"createdAt"`
	ExpiresAt  time.Time `json:"expiresAt"`
	Revoked    bool      `json:"revoked"`
}

// Capacity tracks configured/reserved units for regular and cooled pools.
type Capacity struct {
	CapacityUnits       int `json:"capacityUnits"`
	ReservedUnits       int `json:"reservedUnits"`
	CooledCapacityUnits int `json:"cooledCapacityUnits"`
	CooledReservedUnits int `json:"cooledReservedUnits"`
}

func (c Capacity) AvailableUnits() int {
	if v := c.CapacityUnits - c.ReservedUnits; v > 0 {
		return v
	}
	return 0
}

func (c Capacity) CooledAvailableUnits() int {
	if v := c.CooledCapacityUnits - c.CooledReservedUnits; v > 0 {
		return v
	}
	return 0
}

type LocationFunctionStates struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

func (s LocationFunctionStates) Has(f LocationFunction) bool {
	switch f {
	case FunctionCollectionPoint:
		return s.CollectionPoint
	case FunctionTransferPoint:
		return s.TransferPoint
	case FunctionHub:
		return s.Hub
	case FunctionLaboratory:
		return s.Laboratory
	}
	return false
}

func (s *LocationFunctionStates) Set(f LocationFunction, v bool) {
	switch f {
	case FunctionCollectionPoint:
		s.CollectionPoint = v
	case FunctionTransferPoint:
		s.TransferPoint = v
	case FunctionHub:
		s.Hub = v
	case FunctionLaboratory:
		s.Laboratory = v
	}
}

// Location is a network node that may provide several functions at once.
type Location struct {
