// Sample statuses.
const (
	SampleStatusRequested     = "requested"
	SampleStatusAssigned      = "assigned"
	SampleStatusCollected     = "collected"
	SampleStatusSealed        = "sealed"
	SampleStatusInTransit     = "in_transit"
	SampleStatusAtNode        = "at_node"
	SampleStatusAtLab         = "at_laboratory"
