action.file_text:
// Package store persists application state in PostgreSQL.
//
// Entities are stored as JSONB documents keyed by their identifier. The core keeps the
// authoritative copy in memory and writes each request's changes through in a single
// transaction, so an ordinary restart reloads exactly the committed state.
package store

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"labdelivery/internal/domain"
)

type Store struct {
	pool *pgxpool.Pool
}

func Open(ctx context.Context, dsn string) (*Store, error) {
	cfg, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		return nil, fmt.Errorf("parse dsn: %w", err)
	}
	cfg.MaxConns = 12
	cfg.MaxConnLifetime = time.Hour
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("connect: %w", err)
	}
	return &Store{pool: pool}, nil
}

func (s *Store) Close() { s.pool.Close() }

func (s *Store) Ping(ctx context.Context) error {
	var one int
	return s.pool.QueryRow(ctx, "SELECT 1").Scan(&one)
}

func (s *Store) Migrate(ctx context.Context) error {
	if _, err := s.pool.Exec(ctx, Schema); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	return nil
}

// Truncate clears every application-owned table, leaving the structure in place.
func (s *Store) Truncate(ctx context.Context) error {
	const stmt = `TRUNCATE users, sessions, locations, connections, sample_types, requests,
	samples, journeys, assignments, handoffs, checkpoints, disruptions,
	serviceability_snapshots, audit_log, realtime_events, idempotency, meta`
	if _, err := s.pool.Exec(ctx, stmt); err != nil {
		return fmt.Errorf("truncate: %w", err)
	}
	return nil
}

// Snapshot is the complete durable state loaded at startup.
type Snapshot struct {
	Meta          map[string]json.RawMessage
	Users         []*domain.User
	Sessions      []*domain.Session
	Locations     []*domain.Location
