func loadDocs[T any](ctx context.Context, s *Store, query string) ([]*T, error) {
	rows, err := s.pool.Query(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*T
	for rows.Next() {
		var raw []byte
		if err := rows.Scan(&raw); err != nil {
			return nil, err
		}
		item := new(T)
		if err := json.Unmarshal(raw, item); err != nil {
			return nil, err
		}
		out = append(out, item)
	}
	return out, rows.Err()
}

func (s *Store) Load(ctx context.Context) (*Snapshot, error) {
	snap := &Snapshot{Meta: map[string]json.RawMessage{}}

	rows, err := s.pool.Query(ctx, "SELECT key, value FROM meta")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var k string
		var v []byte
		if err := rows.Scan(&k, &v); err != nil {
			rows.Close()
