	if snap.Sessions, err = loadDocs[domain.Session](ctx, s, "SELECT doc FROM sessions WHERE expires_at > now()"); err != nil {
		return nil, err
	}
	if snap.Locations, err = loadDocs[domain.Location](ctx, s, "SELECT doc FROM locations"); err != nil {
		return nil, err
	}
	if snap.Connections, err = loadDocs[domain.Connection](ctx, s, "SELECT doc FROM connections"); err != nil {
		return nil, err
	}
	if snap.SampleTypes, err = loadDocs[domain.SampleType](ctx, s, "SELECT doc FROM sample_types"); err != nil {
		return nil, err
	}
	if snap.Requests, err = loadDocs[domain.Request](ctx, s, "SELECT doc FROM requests"); err != nil {
		return nil, err
	}
	if snap.Samples, err = loadDocs[domain.Sample](ctx, s, "SELECT doc FROM samples"); err != nil {
		return nil, err
	}
	if snap.Journeys, err = loadDocs[domain.Journey](ctx, s, "SELECT doc FROM journeys"); err != nil {
		return nil, err
	}
	if snap.Assignments, err = loadDocs[domain.Assignment](ctx, s, "SELECT doc FROM assignments"); err != nil {
		return nil, err
	}
	if snap.Handoffs, err = loadDocs[domain.Handoff](ctx, s, "SELECT doc FROM handoffs"); err != nil {
		return nil, err
	}
	if snap.Checkpoints, err = loadDocs[domain.Checkpoint](ctx, s, "SELECT doc FROM checkpoints"); err != nil {
		return nil, err
	}
	if snap.Disruptions, err = loadDocs[domain.Disruption](ctx, s, "SELECT doc FROM disruptions"); err != nil {
		return nil, err
	}
	if snap.Snapshots, err = loadDocs[domain.ServiceabilitySnapshot](ctx, s, "SELECT doc FROM serviceability_snapshots ORDER BY version"); err != nil {
		return nil, err
	}

	if err := s.pool.QueryRow(ctx, "SELECT COALESCE(MAX(event_id),0) FROM audit_log").Scan(&snap.MaxAuditID); err != nil {
		return nil, err
