	}
	if snap.Checkpoints, err = loadDocs[domain.Checkpoint](ctx, s, "SELECT doc FROM checkpoints"); err != nil {
		return nil, err
	}
	if snap.Disruptions, err = loadDocs[domain.Disruption](ctx, s, "SELECT doc FROM disruptions"); err != nil {
		return nil, err
	}
	if snap.Snapshots, err = loadDocs[domain.ServiceabilitySnapshot](ctx, s, "SELECT doc FROM serviceability_snapshots ORDER BY version"); err != nil {
		return nil, err
	}

	if err := s.pool.QueryRow(ctx, "SELECT COALESCE(MAX(event_id),0) FROM audit_log").Scan(&snap.MaxAuditID); err != nil {
