// Package core implements the domain logic of the lab sample pickup and delivery network.
//
// The authoritative state is kept in memory behind a single mutex. Every mutating
// operation builds one changeset which is committed to PostgreSQL before the response is
// returned, so a restart reloads exactly the state that was acknowledged to clients.
package core

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"sync"
	"time"

	"labdelivery/internal/domain"
	"labdelivery/internal/store"
)

// Config carries tunables used by the engine.
type Config struct {
	SessionTTL      time.Duration
	OfferTimeout    time.Duration
	NoWorkerGrace   time.Duration
	StaleAfter      time.Duration
	DeclinePenalty  time.Duration
	AverageSpeedKmh float64
	MaxCoverageKm   float64
}

// DefaultConfig returns the production defaults.
func DefaultConfig() Config {
	return Config{
		SessionTTL:      12 * time.Hour,
		OfferTimeout:    90 * time.Second,
		NoWorkerGrace:   60 * time.Second,
		StaleAfter:      5 * time.Minute,
		DeclinePenalty:  10 * time.Minute,
		AverageSpeedKmh: 30,
		MaxCoverageKm:   5,
	}
}

// Engine owns all mutable domain state.
type Engine struct {
	mu  sync.Mutex
	st  *store.Store
	cfg Config
	now func() time.Time

	users       map[string]*domain.User
	usersByName map[string]string
	sessions    map[string]*domain.Session
	locations   map[string]*domain.Location
	connections map[string]*domain.Connection
	sampleTypes map[string]*domain.SampleType
	requests    map[string]*domain.Request
	samples     map[string]*domain.Sample
	journeys    map[string]*domain.Journey
	assignments map[string]*domain.Assignment
	handoffs    map[string]*domain.Handoff
	disruptions map[string]*domain.Disruption

	timelines map[string][]domain.AuditRecord

	auditSeq int64
	eventSeq int64

	networkRevision int
	snapshot        *domain.ServiceabilitySnapshot
	publishing      bool
	snapshotDirty   bool

	subs   map[int64]*subscriber
	subSeq int64
}

type subscriber struct {
	id        int64
	audiences map[string]bool
	ch        chan *domain.RealtimeEvent
}

// New builds an engine and loads durable state from the store.
func New(ctx context.Context, st *store.Store, cfg Config) (*Engine, error) {
	e := &Engine{
		st:          st,
		cfg:         cfg,
		now:         func() time.Time { return time.Now().UTC() },
		users:       map[string]*domain.User{},
		usersByName: map[string]string{},
		sessions:    map[string]*domain.Session{},
		locations:   map[string]*domain.Location{},
		connections: map[string]*domain.Connection{},
		sampleTypes: map[string]*domain.SampleType{},
		requests:    map[string]*domain.Request{},
		samples:     map[string]*domain.Sample{},
		journeys:    map[string]*domain.Journey{},
		assignments: map[string]*domain.Assignment{},
		handoffs:    map[string]*domain.Handoff{},
		disruptions: map[string]*domain.Disruption{},
		timelines:   map[string][]domain.AuditRecord{},
		subs:        map[int64]*subscriber{},
	}
	if err := e.load(ctx); err != nil {
		return nil, err
	}
	return e, nil
}

func (e *Engine) load(ctx context.Context) error {
	snap, err := e.st.Load(ctx)
	if err != nil {
		return err
	}
	for _, u := range snap.Users {
		e.users[u.UserID] = u
		e.usersByName[lower(u.Username)] = u.UserID
	}
	for _, s := range snap.Sessions {
		e.sessions[s.Token] = s
	}
	for _, l := range snap.Locations {
		e.locations[l.LocationID] = l
	}
	for _, c := range snap.Connections {
		e.connections[c.ConnectionID] = c
	}
	for _, t := range snap.SampleTypes {
		e.sampleTypes[t.SampleTypeID] = t
	}
	for _, r := range snap.Requests {
		e.requests[r.RequestID] = r
	}
	for _, s := range snap.Samples {
		e.samples[s.SampleID] = s
	}
	for _, j := range snap.Journeys {
		e.journeys[j.JourneyID] = j
	}
	for _, a := range snap.Assignments {
		e.assignments[a.AssignmentID] = a
	}
	for _, h := range snap.Handoffs {
		e.handoffs[h.HandoffID] = h
	}
	for _, d := range snap.Disruptions {
		e.disruptions[d.DisruptionID] = d
	}
	if len(snap.Snapshots) > 0 {
		e.snapshot = snap.Snapshots[len(snap.Snapshots)-1]
	}
	if raw, ok := snap.Meta["networkRevision"]; ok {
		_ = json.Unmarshal(raw, &e.networkRevision)
	}
	e.auditSeq = snap.MaxAuditID
	e.eventSeq = snap.MaxEventID

	records, err := e.st.AuditTimelines(ctx)
	if err != nil {
		return err
	}
	for _, rec := range records {
		for _, subject := range rec.Subjects {
			e.timelines[subject] = append(e.timelines[subject], *rec)
		}
	}
	return nil
}

// Now exposes the engine clock.
func (e *Engine) Now() time.Time { return e.now() }

// Config exposes engine tunables.
func (e *Engine) Config() Config { return e.cfg }

// Ready reports whether every dependency is reachable.
func (e *Engine) Ready(ctx context.Context) error { return e.st.Ping(ctx) }

// txn accumulates the effects of one operation.
type txn struct {
	e      *Engine
	now    time.Time
	cs     *store.Changeset
	actor  *domain.User
	role   domain.Role
	events []*domain.RealtimeEvent
}

func (t *txn) put(table, key string, doc any) { t.cs.Put(table, key, doc) }

func (t *txn) saveUser(u *domain.User) {
	u.UpdatedAt = t.now
	t.put("users", u.UserID, u)
}

func (t *txn) saveSession(s *domain.Session) { t.put("sessions", s.Token, s) }

func (t *txn) saveLocation(l *domain.Location) {
	l.UpdatedAt = t.now
	t.put("locations", l.LocationID, l)
}

func (t *txn) saveConnection(c *domain.Connection) {
	c.UpdatedAt = t.now
	t.put("connections", c.ConnectionID, c)
}

func (t *txn) saveSampleType(s *domain.SampleType) {
	s.UpdatedAt = t.now
	t.put("sample_types", s.SampleTypeID, s)
}

func (t *txn) saveRequest(r *domain.Request) { t.put("requests", r.RequestID, r) }

func (t *txn) saveSample(s *domain.Sample) {
	s.UpdatedAt = t.now
	t.put("samples", s.SampleID, s)
}

func (t *txn) saveJourney(j *domain.Journey) {
	j.UpdatedAt = t.now
	t.put("journeys", j.JourneyID, j)
}

func (t *txn) saveAssignment(a *domain.Assignment) {
	a.UpdatedAt = t.now
	t.put("assignments", a.AssignmentID, a)
}

func (t *txn) saveHandoff(h *domain.Handoff) {
	h.UpdatedAt = t.now
	t.put("handoffs", h.HandoffID, h)
}

func (t *txn) saveCheckpoint(c *domain.Checkpoint) { t.put("checkpoints", c.CheckpointID, c) }

func (t *txn) saveDisruption(d *domain.Disruption) { t.put("disruptions", d.DisruptionID, d) }

func (t *txn) saveSnapshot(s *domain.ServiceabilitySnapshot) {
	t.put("serviceability_snapshots", fmt.Sprint(s.Version), s)
}

// audit appends an audit record. Subjects are the entities whose timeline includes it.
func (t *txn) audit(action, entityType, entityID string, success bool, details map[string]any, subjects ...string) domain.AuditRecord {
	t.e.auditSeq++
	actorID := "anonymous"
	role := "none"
	if t.actor != nil {
		actorID = t.actor.UserID
	}
	if t.role != "" {
		role = string(t.role)
	}
	if details == nil {
		details = map[string]any{}
	}
	subjectSet := map[string]bool{}
	var subs []string
	for _, s := range subjects {
		if s == "" || subjectSet[s] {
			continue
		}
		subjectSet[s] = true
		subs = append(subs, s)
	}
	rec := domain.AuditRecord{
		EventID:    t.e.auditSeq,
		AuditID:    newUUID(),
		ActorID:    actorID,
		Role:       role,
		Action:     action,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: t.now,
		Details:    details,
		Subjects:   subs,
	}
	t.cs.Audit = append(t.cs.Audit, &rec)
	for _, s := range subs {
		t.e.timelines[s] = append(t.e.timelines[s], rec)
	}
	return rec
}

// event queues a durable realtime event for the given audiences.
func (t *txn) event(eventType, entityType, entityID string, payload map[string]any, audiences ...string) {
	t.e.eventSeq++
	if payload == nil {
		payload = map[string]any{}
	}
	ev := &domain.RealtimeEvent{
		ID:         t.e.eventSeq,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  t.now,
		Audience:   audiences,
	}
	t.cs.Events = append(t.cs.Events, ev)
	t.events = append(t.events, ev)
}

