// Principal is the authenticated caller of one request.
type Principal struct {
	User       *domain.User
	Session    *domain.Session
	ActiveRole domain.Role
}

// HasRole reports whether the selected role matches one of the given roles.
func (p *Principal) HasRole(roles ...domain.Role) bool {
	for _, r := range roles {
		if p.ActiveRole == r {
			return true
		}
	}
	return false
}

// IsOps reports whether the caller acts as dispatcher or administrator.
func (p *Principal) IsOps() bool {
	return p.HasRole(domain.RoleDispatcher, domain.RoleAdministrator)
}

// Audiences lists the realtime audiences a session receives, following the selected role.
func (p *Principal) Audiences() []string {
	out := []string{userAudience(p.User.UserID)}
	if p.ActiveRole != "" {
		out = append(out, roleAudience(p.ActiveRole))
	}
	return out
}

// AuthenticateResult is returned by AuthenticateUser.
type AuthenticateResult struct {
	SessionToken string   `json:"sessionToken"`
	UserID       string   `json:"userId"`
	Roles        []string `json:"roles"`
	ActiveRole   string   `json:"activeRole"`
}

// AuthenticateUser verifies credentials and opens a session.
func (e *Engine) AuthenticateUser(ctx context.Context, username, password string) (any, int, error) {
	if username == "" || password == "" {
		return nil, 0, newErr(401, "invalid_credentials", "username and password are required")
	}
	return e.mutate(ctx, "authenticate_user", "", "", "", func(t *txn) (any, int, error) {
		userID, ok := e.usersByName[lower(username)]
		if !ok {
			t.audit("sign_in", "user", lower(username), false,
				map[string]any{"reason": "unknown_username", "username": username})
			return nil, 0, newErr(401, "invalid_credentials", "invalid username or password")
		}
		user := e.users[userID]
		if !verifyPassword(user.PasswordHash, password) {
			t.audit("sign_in", "user", user.UserID, false,
				map[string]any{"reason": "bad_password", "username": username}, user.UserID)
			return nil, 0, newErr(401, "invalid_credentials", "invalid username or password")
		}
		if !user.Active {
			t.audit("sign_in", "user", user.UserID, false,
				map[string]any{"reason": "inactive_account"}, user.UserID)
			return nil, 0, newErr(401, "invalid_credentials", "account is inactive")
		}

		session := &domain.Session{
			Token:     newToken(),
			UserID:    user.UserID,
			CreatedAt: t.now,
			ExpiresAt: t.now.Add(e.cfg.SessionTTL),
		}
		// A single-role account starts with that role selected; multi-role accounts must choose.
		if len(user.Roles) == 1 {
			session.ActiveRole = user.Roles[0]
		}
		e.sessions[session.Token] = session
		t.actor = user
		t.role = session.ActiveRole
		t.saveSession(session)
		t.audit("sign_in", "user", user.UserID, true, map[string]any{
			"username":   user.Username,
			"roles":      rolesToStrings(user.Roles),
			"activeRole": string(session.ActiveRole),
		}, user.UserID)

		return &AuthenticateResult{
			SessionToken: session.Token,
			UserID:       user.UserID,
			Roles:        rolesToStrings(user.Roles),
			ActiveRole:   string(session.ActiveRole),
		}, 200, nil
	})
}

// Authorize resolves a bearer [REDACTED] into a principal.
func (e *Engine) Authorize(token string) (*Principal, error) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if token == "" {
		return nil, errUnauthorized("missing bearer [REDACTED]")
	}
	session, ok := e.sessions[token]
	if !ok || session.Revoked {
		return nil, errUnauthorized("invalid session token")
	}
	if session.ExpiresAt.Before(e.now()) {
		return nil, errUnauthorized("session expired")
	}
	user, ok := e.users[session.UserID]
	if !ok || !user.Active {
		return nil, errUnauthorized("account is not active")
	}
	// A role removed from the account can no longer be the selected working role.
	if session.ActiveRole != "" && !user.HasRole(session.ActiveRole) {
		session.ActiveRole = ""
	}
	return &Principal{User: user, Session: session, ActiveRole: session.ActiveRole}, nil
}

// RoleSelection is returned by SelectActiveRole.
type RoleSelection struct {
	ActiveRole string   `json:"activeRole"`
	Roles      []string `json:"roles"`
}

// SelectActiveRole switches the working role of the session without changing the account roles.
func (e *Engine) SelectActiveRole(ctx context.Context, p *Principal, role domain.Role) (*RoleSelection, int, error) {
	if !domain.ValidRole(role) {
		return nil, 0, errBadRequest("invalid_role", "unknown role")
	}
	res, status, err := e.mutate(ctx, "select_active_role", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor = p.User
		t.role = p.ActiveRole
		user := e.users[p.User.UserID]
		if user == nil {
			return nil, 0, errNotFound("user not found")
		}
		if !user.HasRole(role) {
			t.audit("permission_check", "user", user.UserID, false,
				map[string]any{"requestedRole": string(role), "reason": "role_not_held"}, user.UserID)
			return nil, 0, errForbiddenCode("role_not_held", "the account does not hold this role")
		}
		session := e.sessions[p.Session.Token]
		if session == nil {
			return nil, 0, errUnauthorized("session not found")
		}
		previous := session.ActiveRole
		session.ActiveRole = role
		t.role = role
		t.saveSession(session)
		t.audit("select_active_role", "user", user.UserID, true, map[string]any{
			"previousRole": string(previous),
			"activeRole":   string(role),
			"roles":        rolesToStrings(user.Roles),
		}, user.UserID)
		return &RoleSelection{ActiveRole: string(role), Roles: rolesToStrings(user.Roles)}, 200, nil
	})
	if err != nil {
		return nil, 0, err
	}
	return resultAs[*RoleSelection](res), status, nil
}

