			session.ExpiresAt = t.now
			delete(e.sessions, session.Token)
			t.cs.Delete("sessions", session.Token)
		}
		t.audit("sign_out", "user", p.User.UserID, true, map[string]any{}, p.User.UserID)
		return map[string]any{"status": "signed_out"}, 200, nil
	})
	return err
