// Principal is the authenticated caller of one request.
type Principal struct {
	User       *domain.User
	Session    *domain.Session
	ActiveRole domain.Role
}

// HasRole reports whether the selected role matches one of the given roles.
func (p *Principal) HasRole(roles ...domain.Role) bool {
	for _, r := range roles {
		if p.ActiveRole == r {
			return true
		}
	}
	return false
}

// IsOps reports whether the caller acts as dispatcher or administrator.
func (p *Principal) IsOps() bool {
	return p.HasRole(domain.RoleDispatcher, domain.RoleAdministrator)
}

// Audiences lists the realtime audiences a session receives, following the selected role.
func (p *Principal) Audiences() []string {
	out := []string{userAudience(p.User.UserID)}
	if p.ActiveRole != "" {
		out = append(out, roleAudience(p.ActiveRole))
	}
	return out
}

// AuthenticateResult is returned by AuthenticateUser.
type AuthenticateResult struct {
	SessionToken string   `json:"sessionToken"`
	UserID       string   `json:"userId"`
	Roles        []string `json:"roles"`
	ActiveRole   string   `json:"activeRole"`
}

// AuthenticateUser verifies credentials and opens a session.
func (e *Engine) AuthenticateUser(ctx context.Context, username, password string) (any, int, error) {
	if username == "" || password == "" {
		return nil, 0, newErr(401, "invalid_credentials", "username and password are required")
	}
	return e.mutate(ctx, "authenticate_user", "", "", "", func(t *txn) (any, int, error) {
		userID, ok := e.usersByName[lower(username)]
		if !ok {
			t.audit("sign_in", "user", lower(username), false,
				map[string]any{"reason": "unknown_username", "username": username})
			return nil, 0, newErr(401, "invalid_credentials", "invalid username or password")
		}
		user := e.users[userID]
		if !verifyPassword(user.PasswordHash, password) {
			t.audit("sign_in", "user", user.UserID, false,
				map[string]any{"reason": "bad_password", "username": username}, user.UserID)
			return nil, 0, newErr(401, "invalid_credentials", "invalid username or password")
		}
		if !user.Active {
			t.audit("sign_in", "user", user.UserID, false,
				map[string]any{"reason": "inactive_account"}, user.UserID)
			return nil, 0, newErr(401, "invalid_credentials", "account is inactive")
		}

		session := &domain.Session{
			Token:     newToken(),
			UserID:    user.UserID,
			CreatedAt: t.now,
			ExpiresAt: t.now.Add(e.cfg.SessionTTL),
		}
		// A single-role account starts with that role selected; multi-role accounts must choose.
		if len(user.Roles) == 1 {
			session.ActiveRole = user.Roles[0]
		}
		e.sessions[session.Token] = session
		t.actor = user
		t.role = session.ActiveRole
		t.saveSession(session)
		t.audit("sign_in", "user", user.UserID, true, map[string]any{
