			return nil
		}
	}
	return errForbidden("role " + string(p.ActiveRole) + " may not " + action)
}

// EnsureInitialAdministrator creates the first administrator when no users exist.
func (e *Engine) EnsureInitialAdministrator(ctx context.Context, username, password string) error {
	if username == "" || password == "" {
		return nil
	}
	_, _, err := e.mutate(ctx, "bootstrap_admin", "", "", "", func(t *txn) (any, int, error) {
		if len(e.users) > 0 {
			return map[string]any{"created": false}, 200, nil
		}
		user := &domain.User{
			UserID:         newUUID(),
			Username:       username,
			PasswordHash:   hashPassword(password),
			FullName:       "Initial Administrator",
			Roles:          []domain.Role{domain.RoleAdministrator},
			Qualifications: []string{},
			Certifications: []domain.Certification{},
			Active:         true,
			Available:      true,
			CapacityUnits:  0,
			CreatedAt:      t.now,
		}
		e.users[user.UserID] = user
		e.usersByName[lower(user.Username)] = user.UserID
		t.actor = user
		t.role = domain.RoleAdministrator
		t.saveUser(user)
		t.audit("create_user", "user", user.UserID, true, map[string]any{
			"username":     user.Username,
			"roles":        rolesToStrings(user.Roles),
			"bootstrapped": true,
		}, user.UserID)
		return map[string]any{"created": true}, 200, nil
	})
	return err
}

// EnsureDefaultSampleTypes seeds the four named sample types when none exist.
func (e *Engine) EnsureDefaultSampleTypes(ctx context.Context) error {
	_, _, err := e.mutate(ctx, "bootstrap_sample_types", "", "", "", func(t *txn) (any, int, error) {
		if len(e.sampleTypes) > 0 {
			return map[string]any{"created": 0}, 200, nil
		}
		var admin *domain.User
		for _, u := range e.users {
			if u.HasRole(domain.RoleAdministrator) {
				admin = u
				break
			}
		}
		t.actor = admin
		t.role = domain.RoleAdministrator

		amber := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Amber",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "amber_collection",
			ContainerType:              "standard",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			BatchingAllowed:            true,
		}
		indigo := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Indigo",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "indigo_collection",
			ContainerType:              "sealed_rigid",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			BatchingAllowed:            true,
		}
		frost := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Frost",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "frost_collection",
			ContainerType:              "cooled_box",
			TemperatureMinC:            2,
			TemperatureMaxC:            8,
			RequiresCooledRoute:        true,
			BatchingAllowed:            true,
		}
		pulse := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Pulse",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "pulse_collection",
			ContainerType:              "standard",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			BatchingAllowed:            false,
		}
		// Indigo must never share a container with Amber.
		amber.IncompatibleSampleTypes = []string{indigo.SampleTypeID}
		indigo.IncompatibleSampleTypes = []string{amber.SampleTypeID}
		frost.IncompatibleSampleTypes = []string{}
		pulse.IncompatibleSampleTypes = []string{}

		for _, st := range []*domain.SampleType{amber, indigo, frost, pulse} {
			st.CreatedAt = t.now
			e.sampleTypes[st.SampleTypeID] = st
			t.saveSampleType(st)
			t.audit("create_sample_type", "sample_type", st.SampleTypeID, true, map[string]any{
				"name":          st.Name,
				"containerType": st.ContainerType,
				"seeded":        true,
			}, st.SampleTypeID)
		}
		return map[string]any{"created": 4}, 200, nil
	})
	return err
}

func rolesToStrings(roles []domain.Role) []string {
	out := make([]string, 0, len(roles))
	for _, r := range roles {
		out = append(out, string(r))
	}
	return out
}

// PurgeExpiredSessions drops sessions that are past their expiry.
func (e *Engine) PurgeExpiredSessions(ctx context.Context) {
	e.mu.Lock()
	now := e.now()
	for token, s := range e.sessions {
		if s.ExpiresAt.Before(now) {
			delete(e.sessions, token)
		}
	}
	e.mu.Unlock()
	_ = e.st.DeleteExpiredSessions(ctx)
}

