action.file_text:
package core

import (
	"context"
	"math"
	"time"

	"labdelivery/internal/domain"
)

// CreateUserInput describes a new account.
type CreateUserInput struct {
	Username           string
	InitialPassword    string
	Email              string
	FullName           string
	Phone              string
	Roles              []domain.Role
	Qualifications     []string
	Certifications     []domain.Certification
	Active             bool
	AssignedLocationID string
}

// UserView is the API projection of an account.
type UserView struct {
	UserID         string                 `json:"userId"`
	Username       string                 `json:"username"`
	Email          string                 `json:"email,omitempty"`
	FullName       string                 `json:"fullName,omitempty"`
	Phone          string                 `json:"phone,omitempty"`
	Roles          []string               `json:"roles"`
	Qualifications []string               `json:"qualifications"`
	Certifications []domain.Certification `json:"certifications"`
	Active         bool                   `json:"active"`
}

func userView(u *domain.User) *UserView {
	certs := u.Certifications
	if certs == nil {
		certs = []domain.Certification{}
	}
	return &UserView{
		UserID:         u.UserID,
		Username:       u.Username,
		Email:          u.Email,
		FullName:       u.FullName,
		Phone:          u.Phone,
		Roles:          rolesToStrings(u.Roles),
		Qualifications: stringsOrEmpty(u.Qualifications),
		Certifications: certs,
		Active:         u.Active,
	}
}

// CreateUser registers a new account; administrator only.
func (e *Engine) CreateUser(ctx context.Context, p *Principal, in CreateUserInput) (any, int, error) {
	if err := e.requireRole(p, "manage users", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if in.Username == "" || in.InitialPassword == "" {
		return nil, 0, errBadRequest("invalid_user", "username and initialPassword are required")
	}
	for _, r := range in.Roles {
		if !domain.ValidRole(r) {
			return nil, 0, errBadRequest("invalid_user", "unknown role "+string(r))
		}
	}
	for _, c := range in.Certifications {
		if c.Code == "" {
			return nil, 0, errBadRequest("invalid_certification", "certification code is required")
		}
	}
	return e.mutate(ctx, "create_user", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		if _, exists := e.usersByName[lower(in.Username)]; exists {
			return nil, 0, errConflict("username_exists", "username is already taken")
		}
		if in.AssignedLocationID != "" {
			if _, ok := e.locations[in.AssignedLocationID]; !ok {
				return nil, 0, errNotFound("assigned location not found")
			}
		}
		user := &domain.User{
			UserID:             newUUID(),
			Username:           in.Username,
			PasswordHash:       hashPassword(in.InitialPassword),
			Email:              in.Email,
			FullName:           in.FullName,
			Phone:              in.Phone,
			Roles:              in.Roles,
			Qualifications:     stringsOrEmpty(in.Qualifications),
			Certifications:     in.Certifications,
			Active:             in.Active,
			AssignedLocationID: in.AssignedLocationID,
			Available:          true,
			CapacityUnits:      defaultWorkerCapacity(in.Roles),
			CreatedAt:          t.now,
		}
		if user.Certifications == nil {
			user.Certifications = []domain.Certification{}
		}
		e.users[user.UserID] = user
		e.usersByName[lower(user.Username)] = user.UserID
		t.saveUser(user)
		t.audit("create_user", "user", user.UserID, true, map[string]any{
			"username":           user.Username,
			"roles":              rolesToStrings(user.Roles),
			"qualifications":     user.Qualifications,
			"active":             user.Active,
			"assignedLocationId": user.AssignedLocationID,
		}, user.UserID)
		t.event("user_created", "user", user.UserID, map[string]any{
			"username": user.Username, "roles": rolesToStrings(user.Roles),
		}, operationsAudience()...)
		return userView(user), 201, nil
	})
}

func defaultWorkerCapacity(roles []domain.Role) int {
	for _, r := range roles {
		switch r {
		case domain.RoleCollectionProfession, domain.RoleDeliveryPartner,
			domain.RoleNodeHandler, domain.RoleLaboratoryTeam:
			return 4
		}
	}
	return 0
}

// ReadUser returns one account. Non-administrators may only read themselves.
func (e *Engine) ReadUser(p *Principal, userID string) (any, error) {
	return e.read(func() (any, error) {
		if p.ActiveRole == "" {
			return nil, errRoleNotSelected()
		}
		user, ok := e.users[userID]
		if !ok {
			return nil, errNotFound("user not found")
		}
		if !p.IsOps() && p.User.UserID != userID {
			return nil, errForbidden("only administrators and dispatchers may read other accounts")
		}
		return userView(user), nil
	})
}

// UpdateUserAccessInput describes a role/certification change.
type UpdateUserAccessInput struct {
	UserID             string
	Roles              []domain.Role
	Qualifications     []string
	Certifications     []domain.Certification
	Active             bool
	AssignedLocationID *string
}

// UpdateUserAccessResult is returned by UpdateUserAccess.
type UpdateUserAccessResult struct {
	UserID         string                 `json:"userId"`
	Roles          []string               `json:"roles"`
	Qualifications []string               `json:"qualifications"`
	Certifications []domain.Certification `json:"certifications"`
	Active         bool                   `json:"active"`
}

// UpdateUserAccess changes roles, qualifications, certifications and node/lab assignment.
func (e *Engine) UpdateUserAccess(ctx context.Context, p *Principal, in UpdateUserAccessInput) (any, int, error) {
	if err := e.requireRole(p, "manage user access", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	for _, r := range in.Roles {
		if !domain.ValidRole(r) {
			return nil, 0, errBadRequest("invalid_json", "unknown role "+string(r))
		}
	}
	for _, c := range in.Certifications {
		if c.Code == "" {
			return nil, 0, errBadRequest("invalid_certification", "certification code is required")
		}
	}
	return e.mutate(ctx, "update_user_access", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		user, ok := e.users[in.UserID]
		if !ok {
			return nil, 0, errNotFound("user not found")
		}
		if in.AssignedLocationID != nil && *in.AssignedLocationID != "" {
			if _, ok := e.locations[*in.AssignedLocationID]; !ok {
				return nil, 0, errNotFound("assigned location not found")
			}
		}
		before := map[string]any{
			"roles":          rolesToStrings(user.Roles),
			"qualifications": stringsOrEmpty(user.Qualifications),
			"active":         user.Active,
		}
		user.Roles = in.Roles
		if in.Qualifications != nil {
			user.Qualifications = in.Qualifications
		}
		if in.Certifications != nil {
			user.Certifications = in.Certifications
		}
		user.Active = in.Active
		if in.AssignedLocationID != nil {
			user.AssignedLocationID = *in.AssignedLocationID
		}
		if user.CapacityUnits == 0 {
			user.CapacityUnits = defaultWorkerCapacity(user.Roles)
		}
		t.saveUser(user)
		// Sessions keep their selected role only while the account still holds it.
		for _, s := range e.sessions {
			if s.UserID == user.UserID && s.ActiveRole != "" && !user.HasRole(s.ActiveRole) {
				s.ActiveRole = ""
				t.saveSession(s)
			}
		}
		t.audit("update_user_access", "user", user.UserID, true, map[string]any{
			"before":             before,
			"roles":              rolesToStrings(user.Roles),
			"qualifications":     stringsOrEmpty(user.Qualifications),
			"active":             user.Active,
			"assignedLocationId": user.AssignedLocationID,
		}, user.UserID)
		t.event("user_updated", "user", user.UserID, map[string]any{
			"roles": rolesToStrings(user.Roles), "active": user.Active,
		}, operationsAudience()...)
		certs := user.Certifications
		if certs == nil {
			certs = []domain.Certification{}
		}
		return &UpdateUserAccessResult{
			UserID:         user.UserID,
			Roles:          rolesToStrings(user.Roles),
			Qualifications: stringsOrEmpty(user.Qualifications),
			Certifications: certs,
			Active:         user.Active,
		}, 201, nil
	})
}

// LocationView is the API projection of a network location.
type LocationView struct {
	LocationID      string                        `json:"locationId"`
	Name            string                        `json:"name"`
	Coordinate      domain.Coordinate             `json:"coordinate"`
	CoverageKm      float64                       `json:"coverageKm"`
	HandlingMinutes int                           `json:"handlingMinutes"`
	Active          bool                          `json:"active"`
	Functions       domain.LocationFunctionStates `json:"functions"`
}

func locationView(l *domain.Location) *LocationView {
	return &LocationView{
		LocationID:      l.LocationID,
		Name:            l.Name,
		Coordinate:      l.Coordinate,
		CoverageKm:      l.CoverageKm,
		HandlingMinutes: l.HandlingMinutes,
		Active:          l.Active,
		Functions:       l.Functions,
	}
}

// CreateLocationInput describes a new network location.
type CreateLocationInput struct {
	Name            string
	Coordinate      domain.Coordinate
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	Functions       []domain.LocationFunction
}

// CreateLocation registers a node, hub, transfer point and/or laboratory.
func (e *Engine) CreateLocation(ctx context.Context, p *Principal, in CreateLocationInput) (any, int, error) {
	if err := e.requireRole(p, "create locations", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if err := validateCoordinate(in.Coordinate); err != nil {
		return nil, 0, err
	}
	if in.CoverageKm <= 0 || in.CoverageKm > 5 {
		return nil, 0, errBadRequest("invalid_node_coverage", "coverageKm must be greater than 0 and at most 5")
	}
	if in.HandlingMinutes < 0 || in.HandlingMinutes > 1440 {
		return nil, 0, errBadRequest("invalid_handling_time", "handlingMinutes must be between 0 and 1440")
	}
	if len(in.Functions) == 0 {
		return nil, 0, errBadRequest("invalid_location_function", "at least one function is required")
	}
	states := domain.LocationFunctionStates{}
	for _, f := range in.Functions {
		if !domain.ValidLocationFunction(f) {
			return nil, 0, errBadRequest("invalid_location_function", "unknown function "+string(f))
		}
		states.Set(f, true)
	}
	return e.mutate(ctx, "create_location", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		loc := &domain.Location{
			LocationID:      newUUID(),
			Name:            in.Name,
			Coordinate:      in.Coordinate,
			CoverageKm:      in.CoverageKm,
			HandlingMinutes: in.HandlingMinutes,
			Active:          in.Active,
			Functions:       states,
			AcceptedTypes:   []string{},
			CreatedAt:       t.now,
		}
		e.locations[loc.LocationID] = loc
		t.saveLocation(loc)
		e.markNetworkChanged(t)
		t.audit("create_location", "location", loc.LocationID, true, map[string]any{
			"name": loc.Name, "functions": loc.Functions, "active": loc.Active,
			"coverageKm": loc.CoverageKm, "handlingMinutes": loc.HandlingMinutes,
		}, loc.LocationID)
		t.event("location_created", "location", loc.LocationID, map[string]any{"name": loc.Name},
			operationsAudience()...)
		return locationView(loc), 201, nil
	})
}

// UpdateLocationInput describes a location edit.
type UpdateLocationInput struct {
	LocationID      string
	Name            string
	Coordinate      domain.Coordinate
	CoverageKm      *float64
	HandlingMinutes *int
	Functions       []domain.LocationFunction
}

// UpdateLocation edits a location's attributes and provided functions.
func (e *Engine) UpdateLocation(ctx context.Context, p *Principal, in UpdateLocationInput) (any, int, error) {
	if err := e.requireRole(p, "update locations", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if err := validateCoordinate(in.Coordinate); err != nil {
		return nil, 0, err
	}
	if in.CoverageKm != nil && (*in.CoverageKm <= 0 || *in.CoverageKm > 5) {
		return nil, 0, errBadRequest("invalid_node_coverage", "coverageKm must be greater than 0 and at most 5")
	}
	if in.HandlingMinutes != nil && (*in.HandlingMinutes < 0 || *in.HandlingMinutes > 1440) {
		return nil, 0, errBadRequest("invalid_handling_time", "handlingMinutes must be between 0 and 1440")
	}
	var states *domain.LocationFunctionStates
	if in.Functions != nil {
		s := domain.LocationFunctionStates{}
		for _, f := range in.Functions {
			if !domain.ValidLocationFunction(f) {
				return nil, 0, errBadRequest("invalid_location_function", "unknown function "+string(f))
			}
			s.Set(f, true)
		}
		states = &s
	}
	return e.mutate(ctx, "update_location", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		loc, ok := e.locations[in.LocationID]
		if !ok {
			return nil, 0, errNotFound("location not found")
		}
		before := map[string]any{
			"name": loc.Name, "coordinate": loc.Coordinate, "coverageKm": loc.CoverageKm,
			"handlingMinutes": loc.HandlingMinutes, "functions": loc.Functions,
		}
		loc.Name = in.Name
		loc.Coordinate = in.Coordinate
		if in.CoverageKm != nil {
			loc.CoverageKm = *in.CoverageKm
		}
		if in.HandlingMinutes != nil {
			loc.HandlingMinutes = *in.HandlingMinutes
		}
		if states != nil {
			loc.Functions = *states
		}
		t.saveLocation(loc)
		e.markNetworkChanged(t)
		t.audit("update_location", "location", loc.LocationID, true, map[string]any{
			"before": before, "name": loc.Name, "functions": loc.Functions,
		}, loc.LocationID)
		t.event("location_updated", "location", loc.LocationID, map[string]any{"name": loc.Name},
			operationsAudience()...)
		return locationView(loc), 201, nil
	})
}

// SetLocationStatus activates or deactivates a whole location at runtime.
func (e *Engine) SetLocationStatus(ctx context.Context, p *Principal, locationID string, active bool) (any, int, error) {
	if err := e.requireRole(p, "change location status", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	return e.mutate(ctx, "set_location_status", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		loc, ok := e.locations[locationID]
		if !ok {
			return nil, 0, errNotFound("location not found")
		}
		before := loc.Active
		loc.Active = active
		t.saveLocation(loc)
		e.markNetworkChanged(t)
		t.audit("set_location_status", "location", loc.LocationID, true,
			map[string]any{"before": before, "active": active}, loc.LocationID)
		t.event("location_status_changed", "location", loc.LocationID,
			map[string]any{"active": active}, operationsAudience()...)
		return map[string]any{"locationId": loc.LocationID, "active": loc.Active}, 200, nil
	})
}

// SetLocationFunctionStatus toggles a single function provided by a location.
func (e *Engine) SetLocationFunctionStatus(ctx context.Context, p *Principal, locationID string,
	function domain.LocationFunction, active bool) (any, int, error) {
	if err := e.requireRole(p, "change location functions", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if !domain.ValidLocationFunction(function) {
		return nil, 0, errBadRequest("invalid_location_function", "unknown function")
	}
	return e.mutate(ctx, "set_location_function_status", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		loc, ok := e.locations[locationID]
		if !ok {
			return nil, 0, errNotFound("location not found")
		}
		before := loc.Functions
		loc.Functions.Set(function, active)
		t.saveLocation(loc)
		e.markNetworkChanged(t)
		t.audit("set_location_function_status", "location", loc.LocationID, true, map[string]any{
			"before": before, "function": string(function), "active": active,
		}, loc.LocationID)
		t.event("location_function_changed", "location", loc.LocationID, map[string]any{
			"function": string(function), "active": active,
		}, operationsAudience()...)
		return map[string]any{
			"locationId": loc.LocationID,
			"function":   string(function),
			"active":     active,
			"functions":  loc.Functions,
		}, 200, nil
	})
}

// CreateConnectionInput describes a transport connection between two locations.
type CreateConnectionInput struct {
	FromLocationID string
	ToLocationID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
}

// CreateConnection registers a directed transport connection.
func (e *Engine) CreateConnection(ctx context.Context, p *Principal, in CreateConnectionInput) (any, int, error) {
	if err := e.requireRole(p, "create connections", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if in.TravelMinutes < 1 {
		return nil, 0, errBadRequest("invalid_connection", "travelMinutes must be at least 1")
	}
	if in.CostUnits < 0 {
		return nil, 0, errBadRequest("invalid_connection", "costUnits must not be negative")
	}
	if in.FromLocationID == in.ToLocationID {
		return nil, 0, errBadRequest("invalid_connection", "a connection must join two different locations")
	}
	return e.mutate(ctx, "create_connection", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		if _, ok := e.locations[in.FromLocationID]; !ok {
			return nil, 0, errBadRequest("invalid_connection", "fromLocationId does not exist")
		}
		if _, ok := e.locations[in.ToLocationID]; !ok {
			return nil, 0, errBadRequest("invalid_connection", "toLocationId does not exist")
		}
		conn := &domain.Connection{
			ConnectionID:   newUUID(),
			FromLocationID: in.FromLocationID,
			ToLocationID:   in.ToLocationID,
			TravelMinutes:  in.TravelMinutes,
			CostUnits:      in.CostUnits,
			Cooled:         in.Cooled,
			Active:         in.Active,
			CreatedAt:      t.now,
		}
		e.connections[conn.ConnectionID] = conn
		t.saveConnection(conn)
		e.markNetworkChanged(t)
		t.audit("create_connection", "connection", conn.ConnectionID, true, map[string]any{
			"fromLocationId": conn.FromLocationID, "toLocationId": conn.ToLocationID,
			"travelMinutes": conn.TravelMinutes, "cooled": conn.Cooled, "active": conn.Active,
		}, conn.ConnectionID)
		t.event("connection_created", "connection", conn.ConnectionID, map[string]any{
			"fromLocationId": conn.FromLocationID, "toLocationId": conn.ToLocationID,
		}, operationsAudience()...)
		return map[string]any{
			"connectionId":   conn.ConnectionID,
			"fromLocationId": conn.FromLocationID,
			"toLocationId":   conn.ToLocationID,
			"travelMinutes":  conn.TravelMinutes,
			"costUnits":      conn.CostUnits,
			"cooled":         conn.Cooled,
			"active":         conn.Active,
		}, 201, nil
	})
}

// SetConnectionStatus activates or deactivates a connection at runtime.
func (e *Engine) SetConnectionStatus(ctx context.Context, p *Principal, connectionID string, active bool) (any, int, error) {
	if err := e.requireRole(p, "change connection status", domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	return e.mutate(ctx, "set_connection_status", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		conn, ok := e.connections[connectionID]
		if !ok {
