// Serviceability reasons, as pinned by the contract.
const (
	ReasonServiceable      = "serviceable"
	ReasonOutsideCoverage  = "outside_service_coverage"
	ReasonNoLaboratory     = "no_accepting_laboratory"
	ReasonNoRoute          = "no_route"
	ReasonNoCapacity       = "insufficient_capacity"
	ReasonDeadline         = "deadline_unreachable"
	ReasonHandlingRules    = "handling_rules_unsatisfiable"
)

// routeRequest describes what a plan must achieve.
type routeRequest struct {
	Origin       domain.Coordinate
	OriginType   domain.OriginType
	OriginNodeID string
	SampleType   *domain.SampleType
	Cooled       bool
	CollectAt    time.Time
	Deadline     time.Time
	// PreSealed skips the collection leg: transport starts at the entry node.
	PreSealed bool
	// SkipCapacity ignores current reservations, used to explain why a route failed.
	SkipCapacity bool
	// ExcludedLocations and ExcludedConnections are unavailable due to a disruption.
	ExcludedLocations   map[string]bool
	ExcludedConnections map[string]bool
}

// routePlan is a concrete feasible plan through the network.
type routePlan struct {
	EntryNodeID   string
	Path          []string
	Connections   []*domain.Connection
	LaboratoryID  string
	CollectAt     time.Time
	ArrivalAt     time.Time
	TotalCost     float64
	CollectTravel time.Duration
	// NodeArrival is the time the sample reaches each location in Path.
	NodeArrival []time.Time
}

// planRoute finds the fastest feasible plan, or the reason no plan exists.
func (e *Engine) planRoute(req routeRequest) (*routePlan, string) {
	if req.SampleType == nil {
		return nil, ReasonHandlingRules
	}

	entries, reason := e.entryNodes(req)
	if reason != "" {
		return nil, reason
	}
	labs := e.acceptingLaboratories(req.SampleType.SampleTypeID, req.ExcludedLocations)
	if len(labs) == 0 {
		return nil, ReasonNoLaboratory
	}

	best, found := e.searchPlans(req, entries, labs, req.Cooled, req.SkipCapacity)
	if found {
		if !best.ArrivalAt.After(req.Deadline) {
			return best, ReasonServiceable
		}
		// A feasible route exists but it is too slow for this deadline.
		return nil, ReasonDeadline
	}

	// Distinguish the cause: cooled-only restriction, capacity, or no connectivity at all.
	if req.Cooled {
		if _, ok := e.searchPlans(req, entries, labs, false, true); ok {
			return nil, ReasonHandlingRules
		}
		return nil, ReasonNoRoute
	}
	if !req.SkipCapacity {
		if _, ok := e.searchPlans(req, entries, labs, req.Cooled, true); ok {
			return nil, ReasonNoCapacity
		}
	}
	return nil, ReasonNoRoute
}

// entryNodes lists the active collection points that can take the sample into the network.
func (e *Engine) entryNodes(req routeRequest) ([]*domain.Location, string) {
	if req.OriginType == domain.OriginNode || req.OriginNodeID != "" {
		loc := e.locations[req.OriginNodeID]
		if loc == nil {
			return nil, ReasonOutsideCoverage
		}
		if req.ExcludedLocations[loc.LocationID] {
			return nil, ReasonOutsideCoverage
		}
		// A node origin must still provide an active entry function.
		if !loc.Active || !(loc.Functions.CollectionPoint || loc.Functions.Hub || loc.Functions.TransferPoint) {
			return nil, ReasonOutsideCoverage
		}
		return []*domain.Location{loc}, ""
	}

	var out []*domain.Location
	for _, loc := range e.locations {
		if !loc.FunctionActive(domain.FunctionCollectionPoint) || req.ExcludedLocations[loc.LocationID] {
			continue
		}
		radius := loc.CoverageKm
		if radius > e.cfg.MaxCoverageKm {
			radius = e.cfg.MaxCoverageKm
		}
		if haversineKm(req.Origin.Latitude, req.Origin.Longitude,
			loc.Coordinate.Latitude, loc.Coordinate.Longitude) <= radius {
			out = append(out, loc)
		}
	}
	if len(out) == 0 {
		return nil, ReasonOutsideCoverage
	}
	sort.Slice(out, func(i, j int) bool {
		di := haversineKm(req.Origin.Latitude, req.Origin.Longitude, out[i].Coordinate.Latitude, out[i].Coordinate.Longitude)
		dj := haversineKm(req.Origin.Latitude, req.Origin.Longitude, out[j].Coordinate.Latitude, out[j].Coordinate.Longitude)
		if di != dj {
			return di < dj
		}
		return out[i].LocationID < out[j].LocationID
	})
	return out, ""
}

func (e *Engine) acceptingLaboratories(sampleTypeID string, excluded map[string]bool) map[string]bool {
	out := map[string]bool{}
	for _, loc := range e.locations {
		if excluded[loc.LocationID] {
			continue
		}
		if loc.FunctionActive(domain.FunctionLaboratory) && loc.Accepts(sampleTypeID) {
			out[loc.LocationID] = true
		}
	}
	return out
}

type searchNode struct {
	locationID string
	minutes    float64
	cost       float64
	index      int
}

type nodeQueue []*searchNode

func (q nodeQueue) Len() int { return len(q) }
func (q nodeQueue) Less(i, j int) bool {
	if q[i].minutes != q[j].minutes {
		return q[i].minutes < q[j].minutes
	}
	return q[i].cost < q[j].cost
}
func (q nodeQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index, q[j].index = i, j
}
func (q *nodeQueue) Push(x any) {
	n := x.(*searchNode)
	n.index = len(*q)
	*q = append(*q, n)
}
func (q *nodeQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// searchPlans runs a shortest-travel-time search from every entry node to any accepting
// laboratory and returns the fastest arriving plan.
func (e *Engine) searchPlans(req routeRequest, entries []*domain.Location, labs map[string]bool,
	cooledOnly, skipCapacity bool) (*routePlan, bool) {
	var best *routePlan
	for _, entry := range entries {
		plan, ok := e.searchFromEntry(req, entry, labs, cooledOnly, skipCapacity)
		if !ok {
			continue
		}
		if best == nil || plan.ArrivalAt.Before(best.ArrivalAt) ||
			(plan.ArrivalAt.Equal(best.ArrivalAt) && plan.TotalCost < best.TotalCost) {
			best = plan
		}
	}
	return best, best != nil
}

func (e *Engine) searchFromEntry(req routeRequest, entry *domain.Location, labs map[string]bool,
	cooledOnly, skipCapacity bool) (*routePlan, bool) {
