package core

import (
	"context"
	"sort"

	"labdelivery/internal/domain"
)

// PublishServiceability computes a complete serviceability calculation and publishes it as
// one new version. The previously published version keeps serving reads until the new one
// is complete, and only one computation runs at a time.
func (e *Engine) PublishServiceability(ctx context.Context) {
	e.mu.Lock()
	if e.publishing {
		// A computation is already running; it will pick up the newer revision itself.
		e.snapshotDirty = true
		e.mu.Unlock()
		return
	}
	e.publishing = true
	e.mu.Unlock()

	defer func() {
		e.mu.Lock()
		e.publishing = false
		again := e.snapshotDirty
		e.snapshotDirty = false
		e.mu.Unlock()
		if again {
			e.PublishServiceability(ctx)
		}
	}()

	e.mu.Lock()
	revision := e.networkRevision
	regions := e.computeRegionsLocked()
	nextVersion := 1
	if e.snapshot != nil {
		nextVersion = e.snapshot.Version + 1
		if e.snapshot.NetworkRevision == revision {
			e.mu.Unlock()
			return
		}
	}
	e.mu.Unlock()

	candidate := &domain.ServiceabilitySnapshot{
		Version:                    nextVersion,
		Status:                     "complete",
		NetworkRevision:            revision,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}

	_, _, _ = e.mutate(ctx, "publish_serviceability", "", "", "", func(t *txn) (any, int, error) {
		candidate.ComputedAt = t.now
		// The snapshot only becomes visible once it is complete and committed.
		t.saveSnapshot(candidate)
		e.snapshot = candidate
		t.audit("publish_serviceability", "serviceability", fmtInt(candidate.Version), true, map[string]any{
			"version":                    candidate.Version,
			"networkRevision":            candidate.NetworkRevision,
			"activeCollectionPointCount": candidate.ActiveCollectionPointCount,
		})
		t.event("serviceability_published", "serviceability", fmtInt(candidate.Version), map[string]any{
			"version": candidate.Version,
		})
		return map[string]any{"version": candidate.Version}, 200, nil
	})
}

// computeRegionsLocked lists the coverage discs of every active collection point.
func (e *Engine) computeRegionsLocked() []domain.ServiceabilityRegion {
	regions := make([]domain.ServiceabilityRegion, 0, len(e.locations))
	for _, loc := range e.locations {
		if !loc.FunctionActive(domain.FunctionCollectionPoint) {
			continue
		}
		coverage := loc.CoverageKm
		if coverage > e.cfg.MaxCoverageKm {
			coverage = e.cfg.MaxCoverageKm
		}
		regions = append(regions, domain.ServiceabilityRegion{
			LocationID: loc.LocationID,
			Name:       loc.Name,
			Latitude:   loc.Coordinate.Latitude,
