			DeclinedByIDs: []string{},
			CreatedAt:     t.now,
		})
	}

	seq++
	assignments = append(assignments, &domain.Assignment{
		AssignmentID:  newUUID(),
		Kind:          domain.AssignmentLaboratory,
		JourneyID:     journey.JourneyID,
		SampleID:      sample.SampleID,
		SampleIDs:     []string{sample.SampleID},
		Sequence:      seq,
		Status:        domain.AssignStatusPending,
		LaboratoryID:  plan.LaboratoryID,
		FromLocationID: plan.Path[len(plan.Path)-2 : len(plan.Path)-1][0],
		RequiredRole:  domain.RoleLaboratoryTeam,
		Cooled:        cooled,
		DeclinedByIDs: []string{},
		CreatedAt:     t.now,
	})

	for _, a := range assignments {
		e.assignments[a.AssignmentID] = a
		journey.AssignmentIDs = append(journey.AssignmentIDs, a.AssignmentID)
		t.saveAssignment(a)
	}

	e.journeys[journey.JourneyID] = journey
	t.saveJourney(journey)

	sample.ActiveJourneyID = journey.JourneyID
	sample.TargetLaboratoryID = plan.LaboratoryID

	t.audit("create_journey", "journey", journey.JourneyID, true, map[string]any{
		"routeMode":           string(journey.RouteMode),
		"planVersion":         journey.PlanVersion,
		"path":                plan.Path,
		"laboratoryId":        plan.LaboratoryID,
		"estimatedDeliveryAt": formatTime(plan.ArrivalAt),
		"assignmentCount":     len(assignments),
	}, journey.JourneyID, sample.SampleID)
	t.event("journey_created", "journey", journey.JourneyID, map[string]any{
		"journeyId": journey.JourneyID, "sampleIds": journey.SampleIDs,
	}, append(operationsAudience(), userAudience(sample.RequesterID))...)

	// Offer each assignment in plan order to one worker at a time.
	for _, a := range assignments {
		e.offerAssignment(t, a)
	}
	return journey, nil
}

func previousLocation(path []string, i int) string {
	if i == 0 {
		return ""
	}
	return path[i-1]
}

func nextLocation(path []string, i int) string {
	if i+1 >= len(path) {
		return ""
	}
	return path[i+1]
}

func locationDwell(loc *domain.Location) int {
	if loc == nil {
		return 0
	}
	return loc.HandlingMinutes
}

func routeModeFor(plan *routePlan) domain.RouteMode {
	if len(plan.Connections) <= 1 {
		return domain.RouteDirect
	}
	return domain.RouteMultiStop
}

// reserveForJourney holds one unit in every pool the plan traverses. The reservation is
// recorded on the journey so it can be released when it is no longer required.
func (e *Engine) reserveForJourney(t *txn, journey *domain.Journey, sample *domain.Sample, plan *routePlan) error {
	sampleType := e.sampleTypes[sample.SampleTypeID]
	cooled := sampleType != nil && sampleType.RequiresCooledRoute

	type pending struct {
		resourceID string
		kind       string
	}
	var wanted []pending
	for _, locationID := range plan.Path {
		wanted = append(wanted, pending{resourceID: locationID, kind: "location"})
	}
	for _, conn := range plan.Connections {
		wanted = append(wanted, pending{resourceID: conn.ConnectionID, kind: "connection"})
	}

	var applied []domain.Reservation
	rollback := func() {
		for _, r := range applied {
			e.releaseReservation(r)
		}
	}
	for _, w := range wanted {
		res := domain.Reservation{
			ReservationID: newUUID(),
			ResourceID:    w.resourceID,
			ResourceKind:  w.kind,
			SampleID:      sample.SampleID,
			Units:         1,
			Cooled:        cooled,
		}
		if err := e.applyReservation(res); err != nil {
			rollback()
			return err
		}
		applied = append(applied, res)
	}

	journey.Reservations = append(journey.Reservations, applied...)
	for _, r := range applied {
		switch r.ResourceKind {
		case "location":
			if loc := e.locations[r.ResourceID]; loc != nil {
				t.saveLocation(loc)
			}
		case "connection":
			if conn := e.connections[r.ResourceID]; conn != nil {
				t.saveConnection(conn)
			}
		}
		t.audit("reserve_capacity", r.ResourceKind, r.ResourceID, true, map[string]any{
			"sampleId": sample.SampleID, "units": r.Units, "cooled": r.Cooled,
			"journeyId": journey.JourneyID,
		}, r.ResourceID, sample.SampleID, journey.JourneyID)
	}
	return nil
}

// applyReservation takes one unit from a pool, never overbooking it.
func (e *Engine) applyReservation(r domain.Reservation) error {
	switch r.ResourceKind {
	case "location":
		loc := e.locations[r.ResourceID]
		if loc == nil {
			return errConflict("invalid_reservation", "unknown capacity pool")
		}
		if r.Cooled {
			if loc.Capacity.CooledCapacityUnits == 0 ||
				loc.Capacity.CooledAvailableUnits() < r.Units {
				return errConflict("cooled_capacity_exhausted", "cooled capacity is exhausted at "+loc.Name)
			}
			loc.Capacity.CooledReservedUnits += r.Units
			return nil
		}
		if loc.Capacity.CapacityUnits > 0 && loc.Capacity.AvailableUnits() < r.Units {
			return errConflict("capacity_exhausted", "capacity is exhausted at "+loc.Name)
		}
		if loc.Capacity.CapacityUnits > 0 {
			loc.Capacity.ReservedUnits += r.Units
		}
		return nil
	case "connection":
		conn := e.connections[r.ResourceID]
		if conn == nil {
			return errConflict("invalid_reservation", "unknown capacity pool")
		}
		if r.Cooled {
			if conn.Capacity.CooledCapacityUnits == 0 {
				if !conn.Cooled {
					return errConflict("cooled_capacity_exhausted", "connection has no cooled transport")
				}
				return nil
			}
			if conn.Capacity.CooledAvailableUnits() < r.Units {
				return errConflict("cooled_capacity_exhausted", "cooled transport capacity is exhausted")
			}
			conn.Capacity.CooledReservedUnits += r.Units
			return nil
		}
		if conn.Capacity.CapacityUnits > 0 && conn.Capacity.AvailableUnits() < r.Units {
			return errConflict("capacity_exhausted", "transport capacity is exhausted")
		}
		if conn.Capacity.CapacityUnits > 0 {
			conn.Capacity.ReservedUnits += r.Units
		}
		return nil
	}
	return errConflict("invalid_reservation", "unknown capacity pool kind")
}

func (e *Engine) releaseReservation(r domain.Reservation) {
	switch r.ResourceKind {
	case "location":
		loc := e.locations[r.ResourceID]
		if loc == nil {
			return
		}
		if r.Cooled {
			loc.Capacity.CooledReservedUnits = maxInt(0, loc.Capacity.CooledReservedUnits-r.Units)
			return
		}
		loc.Capacity.ReservedUnits = maxInt(0, loc.Capacity.ReservedUnits-r.Units)
	case "connection":
		conn := e.connections[r.ResourceID]
		if conn == nil {
			return
		}
		if r.Cooled {
			conn.Capacity.CooledReservedUnits = maxInt(0, conn.Capacity.CooledReservedUnits-r.Units)
			return
		}
		conn.Capacity.ReservedUnits = maxInt(0, conn.Capacity.ReservedUnits-r.Units)
	}
}

// releaseJourneyReservations frees every capacity hold a journey still owns.
func (e *Engine) releaseJourneyReservations(t *txn, journey *domain.Journey) {
	for i := range journey.Reservations {
		r := &journey.Reservations[i]
		if r.Released {
			continue
		}
		e.releaseReservation(*r)
		r.Released = true
		switch r.ResourceKind {
		case "location":
			if loc := e.locations[r.ResourceID]; loc != nil {
				t.saveLocation(loc)
			}
		case "connection":
			if conn := e.connections[r.ResourceID]; conn != nil {
				t.saveConnection(conn)
			}
		}
		t.audit("release_capacity", r.ResourceKind, r.ResourceID, true, map[string]any{
			"sampleId": r.SampleID, "units": r.Units, "cooled": r.Cooled,
			"journeyId": journey.JourneyID,
		}, r.ResourceID, r.SampleID, journey.JourneyID)
	}
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func fmtInt(v int) string { return fmt.Sprint(v) }

func formatTime(t time.Time) string { return t.UTC().Format(time.RFC3339Nano) }
