package core

import (
	"fmt"
	"time"

	"labdelivery/internal/domain"
)

// buildJourney materialises a plan: stops, assignments and capacity reservations.
//
// A journey contains an optional collection assignment (skipped for pre-sealed samples),
// one transport assignment per connection hop, a node assignment at every intermediate
// stop, and a laboratory assignment at the destination.
func (e *Engine) buildJourney(t *txn, sample *domain.Sample, plan *routePlan) (*domain.Journey, error) {
	journey := &domain.Journey{
		JourneyID:           newUUID(),
		PlanVersion:         1,
		RouteMode:           routeModeFor(plan),
		Status:              domain.JourneyStatusPlanned,
		SampleIDs:           []string{sample.SampleID},
		EstimatedDeliveryAt: timePtr(plan.ArrivalAt),
		TotalCostUnits:      plan.TotalCost,
		LaboratoryID:        plan.LaboratoryID,
		Valid:               true,
		CreatedAt:           t.now,
	}

	if err := e.reserveForJourney(t, journey, sample, plan); err != nil {
		return nil, err
	}

	sequence := 0
	addStop := func(locationID string, stopType domain.StopType, at time.Time, dwell int) *domain.Stop {
		sequence++
		loc := e.locations[locationID]
		coord := domain.Coordinate{}
		if loc != nil {
			coord = loc.Coordinate
		}
		journey.Stops = append(journey.Stops, domain.Stop{
			StopID:       newUUID(),
			LocationID:   locationID,
			StopType:     stopType,
			Sequence:     sequence,
			EstimatedAt:  at,
			DwellMinutes: dwell,
			Coordinate:   coord,
		})
		return &journey.Stops[len(journey.Stops)-1]
	}

	sampleType := e.sampleTypes[sample.SampleTypeID]
	cooled := sampleType != nil && sampleType.RequiresCooledRoute

	// Collection at the origin, unless the sample entered the network already sealed.
	var collection *domain.Assignment
	if !sample.Sealed {
		qualification := ""
		if sampleType != nil && sampleType.QualifiedCollectorRequired {
			qualification = sampleType.RequiredQualification
		}
		collection = &domain.Assignment{
			AssignmentID:          newUUID(),
			Kind:                  domain.AssignmentCollection,
			JourneyID:             journey.JourneyID,
			SampleID:              sample.SampleID,
			SampleIDs:             []string{sample.SampleID},
			Sequence:              1,
			Status:                domain.AssignStatusPending,
			ToLocationID:          plan.EntryNodeID,
			RequiredRole:          domain.RoleCollectionProfession,
			RequiredQualification: qualification,
			Cooled:                cooled,
			DeclinedByIDs:         []string{},
			CreatedAt:             t.now,
		}
	}

	entryStop := addStop(plan.EntryNodeID, domain.StopPickup, plan.NodeArrival[0],
		locationDwell(e.locations[plan.EntryNodeID]))
	if collection != nil {
		collection.DropoffStopID = entryStop.StopID
	}

	// One transport assignment per hop, plus a node assignment at each intermediate stop.
	var assignments []*domain.Assignment
	if collection != nil {
		assignments = append(assignments, collection)
	}
	seq := len(assignments)
	for i, conn := range plan.Connections {
		seq++
		fromStop := journey.Stops[len(journey.Stops)-1]
		isFinal := i == len(plan.Connections)-1
		stopType := domain.StopHandoff
		if isFinal {
			stopType = domain.StopDelivery
		}
		toStop := addStop(conn.ToLocationID, stopType, plan.NodeArrival[i+1],
			locationDwell(e.locations[conn.ToLocationID]))
		transport := &domain.Assignment{
			AssignmentID:   newUUID(),
			Kind:           domain.AssignmentTransport,
			JourneyID:      journey.JourneyID,
			SampleID:       sample.SampleID,
			SampleIDs:      []string{sample.SampleID},
			Sequence:       seq,
			Status:         domain.AssignStatusPending,
			FromLocationID: conn.FromLocationID,
			ToLocationID:   conn.ToLocationID,
			ConnectionID:   conn.ConnectionID,
			RequiredRole:   domain.RoleDeliveryPartner,
			Cooled:         cooled,
			PickupStopID:   fromStop.StopID,
			DropoffStopID:  toStop.StopID,
			DeclinedByIDs:  []string{},
			CreatedAt:      t.now,
		}
		assignments = append(assignments, transport)
	}

	// Node assignments cover custody at the entry node and every intermediate stop.
	for i, locationID := range plan.Path {
		if locationID == plan.LaboratoryID {
			continue
		}
		loc := e.locations[locationID]
		if loc == nil {
			continue
		}
		// The entry node only needs a handler when a courier collects into it.
		seq++
		assignments = append(assignments, &domain.Assignment{
			AssignmentID:  newUUID(),
			Kind:          domain.AssignmentNode,
			JourneyID:     journey.JourneyID,
			SampleID:      sample.SampleID,
			SampleIDs:     []string{sample.SampleID},
			Sequence:      seq,
			Status:        domain.AssignStatusPending,
			NodeID:        locationID,
			FromLocationID: previousLocation(plan.Path, i),
			ToLocationID:   nextLocation(plan.Path, i),
			RequiredRole:  domain.RoleNodeHandler,
			Cooled:        cooled,
			DeclinedByIDs: []string{},
			CreatedAt:     t.now,
		})
	}

	seq++
	assignments = append(assignments, &domain.Assignment{
		AssignmentID:  newUUID(),
		Kind:          domain.AssignmentLaboratory,
		JourneyID:     journey.JourneyID,
		SampleID:      sample.SampleID,
		SampleIDs:     []string{sample.SampleID},
		Sequence:      seq,
		Status:        domain.AssignStatusPending,
		LaboratoryID:  plan.LaboratoryID,
		FromLocationID: plan.Path[len(plan.Path)-2 : len(plan.Path)-1][0],
		RequiredRole:  domain.RoleLaboratoryTeam,
		Cooled:        cooled,
		DeclinedByIDs: []string{},
		CreatedAt:     t.now,
	})

	for _, a := range assignments {
		e.assignments[a.AssignmentID] = a
		journey.AssignmentIDs = append(journey.AssignmentIDs, a.AssignmentID)
		t.saveAssignment(a)
	}

	e.journeys[journey.JourneyID] = journey
	t.saveJourney(journey)

	sample.ActiveJourneyID = journey.JourneyID
	sample.TargetLaboratoryID = plan.LaboratoryID

	t.audit("create_journey", "journey", journey.JourneyID, true, map[string]any{
		"routeMode":           string(journey.RouteMode),
		"planVersion":         journey.PlanVersion,
		"path":                plan.Path,
		"laboratoryId":        plan.LaboratoryID,
		"estimatedDeliveryAt": formatTime(plan.ArrivalAt),
		"assignmentCount":     len(assignments),
	}, journey.JourneyID, sample.SampleID)
	t.event("journey_created", "journey", journey.JourneyID, map[string]any{
		"journeyId": journey.JourneyID, "sampleIds": journey.SampleIDs,
	}, append(operationsAudience(), userAudience(sample.RequesterID))...)

	// Offer each assignment in plan order to one worker at a time.
	for _, a := range assignments {
		e.offerAssignment(t, a)
	}
	return journey, nil
}

