package core

import "net/http"

// APIError is an error carrying the exact HTTP status and contract error code.
type APIError struct {
        Status  int
        Code    string
        Message string
}

func (e *APIError) Error() string { return e.Code + ": " + e.Message }

func newErr(status int, code, message string) *APIError {
        return &APIError{Status: status, Code: code, Message: message}
}

func errBadRequest(code, message string) *APIError  { return newErr(http.StatusBadRequest, code, message) }
func errConflict(code, message string) *APIError    { return newErr(http.StatusConflict, code, message) }
func errForbiddenCode(code, msg string) *APIError   { return newErr(http.StatusForbidden, code, msg) }
func errUnauthorized(message string) *APIError      { return newErr(http.StatusUnauthorized, "unauthorized", message) }
func errForbidden(message string) *APIError         { return newErr(http.StatusForbidden, "forbidden", message) }
func errNotFound(message string) *APIError          { return newErr(http.StatusNotFound, "not_found", message) }
func errInternal(message string) *APIError          { return newErr(http.StatusInternalServerError, "internal_error", message) }
func errInvalidJSON(message string) *APIError       { return errBadRequest("invalid_json", message) }
func errRoleNotSelected() *APIError {
        return errConflict("role_not_selected", "no active role is selected for this session")
}
func errIdempotencyRequired() *APIError {
        return errBadRequest("idempotency_required", "idempotencyKey is required")
}
func errIdempotencyConflict() *APIError {
        return errConflict("idempotency_conflict", "idempotencyKey was already used with a different request body")
}
package core

import (
        "fmt"
        "time"

        "labdelivery/internal/domain"
)

// buildJourney materialises a plan: stops, assignments and capacity reservations.
//
// A journey contains an optional collection assignment (skipped for pre-sealed samples),
// one transport assignment per connection hop, a node assignment at every intermediate
// stop, and a laboratory assignment at the destination.
func (e *Engine) buildJourney(t *txn, sample *domain.Sample, plan *routePlan) (*domain.Journey, error) {
        journey := &domain.Journey{
                JourneyID:           newUUID(),
                PlanVersion:         1,
                RouteMode:           routeModeFor(plan),
                Status:              domain.JourneyStatusPlanned,
                SampleIDs:           []string{sample.SampleID},
                EstimatedDeliveryAt: timePtr(plan.ArrivalAt),
                TotalCostUnits:      plan.TotalCost,
                LaboratoryID:        plan.LaboratoryID,
                Valid:               true,
                CreatedAt:           t.now,
        }

        if err := e.reserveForJourney(t, journey, sample, plan); err != nil {
                return nil, err
        }

        sequence := 0
        addStop := func(locationID string, stopType domain.StopType, at time.Time, dwell int) *domain.Stop {
                sequence++
                loc := e.locations[locationID]
                coord := domain.Coordinate{}
                if loc != nil {
                        coord = loc.Coordinate
                }
                journey.Stops = append(journey.Stops, domain.Stop{
                        StopID:       newUUID(),
                        LocationID:   locationID,
                        StopType:     stopType,
                        Sequence:     sequence,
                        EstimatedAt:  at,
                        DwellMinutes: dwell,
                        Coordinate:   coord,
                })
                return &journey.Stops[len(journey.Stops)-1]
        }

        sampleType := e.sampleTypes[sample.SampleTypeID]
        cooled := sampleType != nil && sampleType.RequiresCooledRoute

        // Collection at the origin, unless the sample entered the network already sealed.
        var collection *domain.Assignment
        if !sample.Sealed {
                qualification := ""
                if sampleType != nil && sampleType.QualifiedCollectorRequired {
                        qualification = sampleType.RequiredQualification
                }
                collection = &domain.Assignment{
                        AssignmentID:          newUUID(),
                        Kind:                  domain.AssignmentCollection,
                        JourneyID:             journey.JourneyID,
                        SampleID:              sample.SampleID,
                        SampleIDs:             []string{sample.SampleID},
                        Sequence:              1,
                        Status:                domain.AssignStatusPending,
                        ToLocationID:          plan.EntryNodeID,
                        RequiredRole:          domain.RoleCollectionProfession,
                        RequiredQualification: qualification,
                        Cooled:                cooled,
                        DeclinedByIDs:         []string{},
                        CreatedAt:             t.now,
                }
        }

        entryStop := addStop(plan.EntryNodeID, domain.StopPickup, plan.NodeArrival[0],
                locationDwell(e.locations[plan.EntryNodeID]))
        if collection != nil {
                collection.DropoffStopID = entryStop.StopID
        }

        // One transport assignment per hop, plus a node assignment at each intermediate stop.
        var assignments []*domain.Assignment
        if collection != nil {
                assignments = append(assignments, collection)
        }
        seq := len(assignments)
        for i, conn := range plan.Connections {
                seq++
                fromStop := journey.Stops[len(journey.Stops)-1]
                isFinal := i == len(plan.Connections)-1
                stopType := domain.StopHandoff
                if isFinal {
                        stopType = domain.StopDelivery
                }
                toStop := addStop(conn.ToLocationID, stopType, plan.NodeArrival[i+1],
                        locationDwell(e.locations[conn.ToLocationID]))
                transport := &domain.Assignment{
                        AssignmentID:   newUUID(),
                        Kind:           domain.AssignmentTransport,
                        JourneyID:      journey.JourneyID,
                        SampleID:       sample.SampleID,
                        SampleIDs:      []string{sample.SampleID},
                        Sequence:       seq,
                        Status:         domain.AssignStatusPending,
                        FromLocationID: conn.FromLocationID,
                        ToLocationID:   conn.ToLocationID,
                        ConnectionID:   conn.ConnectionID,
                        RequiredRole:   domain.RoleDeliveryPartner,
                        Cooled:         cooled,
                        PickupStopID:   fromStop.StopID,
                        DropoffStopID:  toStop.StopID,
                        DeclinedByIDs:  []string{},
                        CreatedAt:      t.now,
                }
                assignments = append(assignments, transport)

// Package core implements the domain logic of the lab sample pickup and delivery network.
//
// The authoritative state is kept in memory behind a single mutex. Every mutating
// operation builds one changeset which is committed to PostgreSQL before the response is
// returned, so a restart reloads exactly the state that was acknowledged to clients.
package core

import (
        "context"
        "encoding/json"
        "fmt"
        "sort"
        "sync"
        "time"

        "labdelivery/internal/domain"
        "labdelivery/internal/store"
)

// Config carries tunables used by the engine.
type Config struct {
        SessionTTL      time.Duration
        OfferTimeout    time.Duration
        NoWorkerGrace   time.Duration
        StaleAfter      time.Duration
        DeclinePenalty  time.Duration
        AverageSpeedKmh float64
        MaxCoverageKm   float64
}

// DefaultConfig returns the production defaults.
func DefaultConfig() Config {
        return Config{
                SessionTTL:      12 * time.Hour,
                OfferTimeout:    90 * time.Second,
                NoWorkerGrace:   60 * time.Second,
                StaleAfter:      5 * time.Minute,
                DeclinePenalty:  10 * time.Minute,
                AverageSpeedKmh: 30,
                MaxCoverageKm:   5,
        }
}

// Engine owns all mutable domain state.
type Engine struct {
        mu  sync.Mutex
        st  *store.Store
        cfg Config
        now func() time.Time

        users       map[string]*domain.User
        usersByName map[string]string
        sessions    map[string]*domain.Session
        locations   map[string]*domain.Location
        connections map[string]*domain.Connection
        sampleTypes map[string]*domain.SampleType
        requests    map[string]*domain.Request
        samples     map[string]*domain.Sample
        journeys    map[string]*domain.Journey
        assignments map[string]*domain.Assignment
