// mutate runs fn under the engine lock, commits its changeset and publishes events.
//
// When idemKey is set the operation is replayed from the recorded response if the same
// key was already used with an identical request body.
func (e *Engine) mutate(ctx context.Context, operation, idemKey, idemHash, userID string,
        fn func(t *txn) (any, int, error)) (any, int, error) {
        e.mu.Lock()
        defer e.mu.Unlock()
        return e.mutateLocked(ctx, operation, idemKey, idemHash, userID, fn)
}

func (e *Engine) mutateLocked(ctx context.Context, operation, idemKey, idemHash, userID string,
        fn func(t *txn) (any, int, error)) (any, int, error) {
        if idemKey != "" {
                rec, err := e.st.LookupIdempotency(ctx, operation, userID, idemKey)
                if err != nil {
                        return nil, 0, errInternal(err.Error())
                }
                if rec != nil {
                        if rec.RequestHash != idemHash {
                                return nil, 0, errIdempotencyConflict()
                        }
                        return json.RawMessage(rec.Response), rec.StatusCode, nil
                }
        }

        t := &txn{e: e, now: e.now(), cs: &store.Changeset{}}
        result, status, err := fn(t)
        if err != nil {
                // Persist audit records describing the rejected attempt; discard everything else.
                if len(t.cs.Audit) > 0 {
                        failed := &store.Changeset{Audit: t.cs.Audit}
                        if commitErr := e.st.Commit(ctx, failed); commitErr != nil {
                                return nil, 0, errInternal(commitErr.Error())
                        }
                }
                return nil, 0, err
        }
        if idemKey != "" {
                raw, mErr := json.Marshal(result)
                if mErr != nil {
                        return nil, 0, errInternal(mErr.Error())
                }
                t.cs.Idem = append(t.cs.Idem, &domain.IdempotencyRecord{
                        Key:         idemKey,
                        Operation:   operation,
                        UserID:      userID,
                        RequestHash: idemHash,
                        StatusCode:  status,
                        Response:    raw,
                        CreatedAt:   t.now,
                })
        }
        if err := e.st.Commit(ctx, t.cs); err != nil {
                return nil, 0, errInternal(err.Error())
        }
        e.publish(t.events)
        if e.snapshotDirty {
                e.snapshotDirty = false
                go e.PublishServiceability(context.Background())
        }
        return result, status, nil
}

// read runs fn under the engine lock without writing anything.
func (e *Engine) read(fn func() (any, error)) (any, error) {
        e.mu.Lock()
        defer e.mu.Unlock()
        return fn()
}

