package core

import (
	"sort"

	"labdelivery/internal/domain"
)

// BootstrapUserView identifies the signed-in account and its role selection state.
type BootstrapUserView struct {
	UserID                string   `json:"userId"`
	Username              string   `json:"username"`
	FullName              string   `json:"fullName,omitempty"`
	Roles                 []string `json:"roles"`
	ActiveRole            string   `json:"activeRole"`
	RoleSelectionRequired bool     `json:"roleSelectionRequired"`
}

// BootstrapView is the first payload the frontend loads after sign-in.
type BootstrapView struct {
	User             *BootstrapUserView    `json:"user"`
	ServerTime       string                `json:"serverTime"`
	RequesterSamples []*SampleStateView    `json:"requesterSamples,omitempty"`
	Operations       *OperationsStateView  `json:"operations,omitempty"`
}

// ReadUIBootstrap returns identity plus the role-appropriate first view of state.
func (e *Engine) ReadUIBootstrap(p *Principal) (any, error) {
	return e.read(func() (any, error) {
		user := e.users[p.User.UserID]
		if user == nil {
			return nil, errNotFound("user not found")
		}
		view := &BootstrapView{
			User: &BootstrapUserView{
				UserID:     user.UserID,
				Username:   user.Username,
				FullName:   user.FullName,
				Roles:      rolesToStrings(user.Roles),
				ActiveRole: string(p.ActiveRole),
				// A multi-role account must pick the role it is working under.
				RoleSelectionRequired: p.ActiveRole == "",
			},
			ServerTime: formatTime(e.now()),
		}
		switch {
		case p.ActiveRole == domain.RoleRequester:
			samples := make([]*domain.Sample, 0)
			for _, sample := range e.samples {
				if sample.RequesterID == user.UserID {
					samples = append(samples, sample)
				}
			}
			sort.Slice(samples, func(i, j int) bool {
				return samples[i].CreatedAt.Before(samples[j].CreatedAt)
			})
			view.RequesterSamples = make([]*SampleStateView, 0, len(samples))
			for _, sample := range samples {
				view.RequesterSamples = append(view.RequesterSamples, e.sampleStateView(sample))
			}
		case p.IsOps():
			view.Operations = e.operationsStateView("")
		}
		return view, nil
	})
}

