					"deliveryDeadline":    formatTime(sample.DeliveryDeadline),
					"delayMinutes":        int(journey.EstimatedDeliveryAt.Sub(sample.DeliveryDeadline).Minutes()),
				})
			}
		}

		counts := []int{}
		var workers []*domain.User
		for _, u := range e.users {
			if isWorker(u) {
				workers = append(workers, u)
			}
		}
		sort.Slice(workers, func(i, j int) bool { return workers[i].Username < workers[j].Username })
		for _, u := range workers {
			count := e.activeAssignmentCount(u.UserID)
			status := "unavailable"
			if u.Available && u.Active {
				status = "available"
			}
			row := &OperationsWorkerView{
				WorkerID:        u.UserID,
				FullName:        u.FullName,
				Roles:           rolesToStrings(u.Roles),
				Available:       u.Available && u.Active,
				Status:          status,
				CapacityUnits:   u.CapacityUnits,
				AssignmentCount: count,
				LatestLocation:  u.LatestLocation,
				LocationStale:   e.locationStale(u.LocationRecordedAt),
			}
			if u.LocationRecordedAt != nil {
				row.LocationRecordedAt = formatTime(*u.LocationRecordedAt)
			}
			out.Workers = append(out.Workers, row)
			counts = append(counts, count)
		}
		out.AssignmentCountSpread = spread(counts)

		var locations []*domain.Location
		for _, loc := range e.locations {
			locations = append(locations, loc)
		}
		sort.Slice(locations, func(i, j int) bool { return locations[i].Name < locations[j].Name })
		for _, loc := range locations {
			out.Locations = append(out.Locations, &OperationsLocationView{
				ID:              loc.LocationID,
				LocationID:      loc.LocationID,
				Name:            loc.Name,
				Coordinate:      loc.Coordinate,
				Active:          loc.Active,
				CoverageKm:      loc.CoverageKm,
				HandlingMinutes: loc.HandlingMinutes,
				Functions:       loc.Functions,
				Capacity:        capacityView(loc.Capacity),
				AcceptedTypeIDs: stringsOrEmpty(loc.AcceptedTypes),
			})
		}

		var connections []*domain.Connection
		for _, conn := range e.connections {
			connections = append(connections, conn)
		}
		sort.Slice(connections, func(i, j int) bool { return connections[i].ConnectionID < connections[j].ConnectionID })
		for _, conn := range connections {
			out.Connections = append(out.Connections, &OperationsConnectionView{
				ID:             conn.ConnectionID,
				ConnectionID:   conn.ConnectionID,
				FromLocationID: conn.FromLocationID,
				ToLocationID:   conn.ToLocationID,
				TravelMinutes:  conn.TravelMinutes,
				CostUnits:      conn.CostUnits,
				Cooled:         conn.Cooled,
				Active:         conn.Active,
				Capacity:       capacityView(conn.Capacity),
			})
		}

		var journeys []*domain.Journey
		for _, journey := range e.journeys {
			journeys = append(journeys, journey)
		}
		sort.Slice(journeys, func(i, j int) bool { return journeys[i].CreatedAt.Before(journeys[j].CreatedAt) })
		for _, journey := range journeys {
			if sampleTypeID != "" && !e.journeyHasSampleType(journey, sampleTypeID) {
				continue
			}
			stops := make([]map[string]any, 0, len(journey.Stops))
			for _, s := range journey.Stops {
				stops = append(stops, map[string]any{
					"stopId": s.StopID, "locationId": s.LocationID, "stopType": string(s.StopType),
					"sequence": s.Sequence, "estimatedAt": formatTime(s.EstimatedAt),
					"completed": s.CompletedAt != nil,
				})
			}
			route := map[string]any{
				"journeyId":   journey.JourneyID,
				"status":      journey.Status,
				"routeMode":   string(journey.RouteMode),
				"planVersion": journey.PlanVersion,
				"sampleIds":   stringsOrEmpty(journey.SampleIDs),
				"stops":       stops,
				"valid":       journey.Valid,
			}
			if journey.EstimatedDeliveryAt != nil {
				route["estimatedDeliveryAt"] = formatTime(*journey.EstimatedDeliveryAt)
			}
			if journey.LaboratoryID != "" {
				route["laboratoryId"] = journey.LaboratoryID
			}
			out.Routes = append(out.Routes, route)
		}

		var handoffs []*domain.Handoff
		for _, h := range e.handoffs {
			handoffs = append(handoffs, h)
		}
		sort.Slice(handoffs, func(i, j int) bool { return handoffs[i].CreatedAt.Before(handoffs[j].CreatedAt) })
		for _, h := range handoffs {
			if sampleTypeID != "" {
				sample := e.samples[h.SampleID]
				if sample == nil || sample.SampleTypeID != sampleTypeID {
					continue
				}
			}
			entry := map[string]any{
				"handoffId": h.HandoffID, "sampleId": h.SampleID, "status": h.Status,
				"senderId": h.SenderID, "receiverId": h.ReceiverID,
				"senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed,
				"initiatedAt": formatTime(h.InitiatedAt),
			}
			if h.ConfirmedAt != nil {
				entry["confirmedAt"] = formatTime(*h.ConfirmedAt)
			}
			out.Handoffs = append(out.Handoffs, entry)
		}

		for _, d := range e.disruptions {
			out.Delays = append(out.Delays, map[string]any{
				"disruptionId": d.DisruptionID, "resourceType": d.ResourceType,
				"resourceId": d.ResourceID, "reason": d.Reason,
				"occurredAt": formatTime(d.OccurredAt), "replanStatus": d.ReplanStatus,
			})
		}

		out.IneligibleAssignmentCount = e.ineligibleAssignmentCount(now)
		return out, nil
	})
}

func (e *Engine) journeyHasSampleType(journey *domain.Journey, sampleTypeID string) bool {
	for _, id := range journey.SampleIDs {
		if sample := e.samples[id]; sample != nil && sample.SampleTypeID == sampleTypeID {
			return true
		}
	}
	return false
}

// ineligibleAssignmentCount counts unfinished assignments that currently have no eligible worker.
func (e *Engine) ineligibleAssignmentCount(now time.Time) int {
	count := 0
	for _, a := range e.assignments {
		if a.Terminal() || a.WorkerID != "" {
			continue
		}
		if len(e.candidateWorkers(a, now)) == 0 {
			count++
		}
	}
	return count
}

func isWorker(u *domain.User) bool {
	for _, r := range u.Roles {
		switch r {
		case domain.RoleCollectionProfession, domain.RoleDeliveryPartner,
			domain.RoleNodeHandler, domain.RoleLaboratoryTeam:
			return true
		}
	}
	return false
}

// spread is the difference between the busiest and least busy worker.
func spread(counts []int) int {
	if len(counts) == 0 {
		return 0
	}
	min, max := counts[0], counts[0]
	for _, c := range counts {
		if c < min {
			min = c
		}
		if c > max {
			max = c
		}
	}
	return max - min
}

// AuditQuery describes a search over the audit trail.
type AuditQuery struct {
	Query      string
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

// AuditEntryView is one audit record, exposed in both camelCase and snake_case.
type AuditEntryView struct {
	AuditID    string         `json:"auditId"`
	AuditIDAlt string         `json:"audit_id"`
	ActorID    string         `json:"actorId"`
	ActorIDAlt string         `json:"actor_id"`
	Role       string         `json:"role"`
	ActorRole  string         `json:"actorRole"`
	Action     string         `json:"action"`
	EntityType string         `json:"entityType"`
	EntityTyp2 string         `json:"entity_type"`
	EntityID   string         `json:"entityId"`
	EntityID2  string         `json:"entity_id"`
	Success    bool           `json:"success"`
	OccurredAt string         `json:"occurredAt"`
	OccurredA2 string         `json:"occurred_at"`
	Details    map[string]any `json:"details"`
}

// AuditSearchResultView is a page of audit results.
type AuditSearchResultView struct {
	Entries    []*AuditEntryView `json:"entries"`
	Total      int               `json:"total"`
	Returned   int               `json:"returned"`
	Offset     int               `json:"offset"`
	Limit      int               `json:"limit"`
	Order      string            `json:"order"`
	HasMore    bool              `json:"hasMore"`
	NextOffset int               `json:"nextOffset,omitempty"`
}

// SearchAuditTrail searches the complete audit history.
func (e *Engine) SearchAuditTrail(ctx context.Context, p *Principal, q AuditQuery) (any, error) {
	if err := e.requireRole(p, "search the audit trail",
		domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, err
	}
	if q.Limit < 1 || q.Limit > 5000 {
		return nil, errBadRequest("invalid_limit", "limit must be between 1 and 5000")
	}
	if q.Offset < 0 {
		return nil, errBadRequest("invalid_offset", "offset must not be negative")
	}
	if q.Order != "newest_first" && q.Order != "oldest_first" {
		return nil, errBadRequest("invalid_order", "order must be newest_first or oldest_first")
	}
	if q.FromTime != nil && q.ToTime != nil && q.ToTime.Before(*q.FromTime) {
		return nil, errBadRequest("invalid_time", "toTime precedes fromTime")
	}

	records, total, err := e.st.SearchAudit(ctx, store.AuditQuery{
		Query:      q.Query,
		ActorID:    q.ActorID,
		EntityType: q.EntityType,
		EntityID:   q.EntityID,
		Action:     q.Action,
		Role:       q.Role,
		Success:    q.Success,
		FromTime:   q.FromTime,
		ToTime:     q.ToTime,
		Limit:      q.Limit,
		Offset:     q.Offset,
		Newest:     q.Order == "newest_first",
	})
	if err != nil {
		return nil, errInternal(err.Error())
	}
	entries := make([]*AuditEntryView, 0, len(records))
	for _, r := range records {
		details := r.Details
		if details == nil {
			details = map[string]any{}
		}
		occurred := formatTime(r.OccurredAt)
		entries = append(entries, &AuditEntryView{
			AuditID: r.AuditID, AuditIDAlt: r.AuditID,
			ActorID: r.ActorID, ActorIDAlt: r.ActorID,
			Role: r.Role, ActorRole: r.Role,
			Action:     r.Action,
			EntityType: r.EntityType, EntityTyp2: r.EntityType,
			EntityID: r.EntityID, EntityID2: r.EntityID,
			Success:    r.Success,
			OccurredAt: occurred, OccurredA2: occurred,
			Details: details,
		})
	}
	result := &AuditSearchResultView{
		Entries:  entries,
		Total:    total,
		Returned: len(entries),
		Offset:   q.Offset,
		Limit:    q.Limit,
		Order:    q.Order,
		HasMore:  q.Offset+len(entries) < total,
	}
	if result.HasMore {
		result.NextOffset = q.Offset + len(entries)
	}
	return result, nil
}

