package api

import (
	"bufio"
	"crypto/sha1"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"errors"
	"io"
	"net"
	"net/http"
	"strconv"
	"strings"
	"time"

	"labdelivery/internal/core"
	"labdelivery/internal/domain"
)

const (
	wsSubprotocol   = "lab-logistics-v1"
	wsGUID          = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
	eventPollLimit  = 500
	wsWriteDeadline = 10 * time.Second
	wsPingInterval  = 25 * time.Second
)

// handleEvents serves the realtime stream. Clients may either upgrade to a
// WebSocket or poll the same endpoint with a `since` cursor.
func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeErr(w, http.StatusMethodNotAllowed, "method_not_allowed", "this operation requires GET")
		return
	}
	since := int64(0)
	if raw := r.URL.Query().Get("since"); raw != "" {
		parsed, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || parsed < 0 {
			writeErr(w, http.StatusBadRequest, "invalid_json", "since must be a non-negative integer")
			return
		}
		since = parsed
	}

	requested := parseSubprotocols(r.Header.Get("Sec-WebSocket-Protocol"))
	// The bearer [REDACTED] may arrive in the subprotocol list because browsers cannot
	// set headers on a WebSocket handshake.
	token := bearerToken(r)
	if token == "" {
		token = tokenFromSubprotocols(requested)
	}
	p, err := s.engine.Authorize(token)
	if err != nil {
		writeAPIError(w, err)
		return
	}

	if isWebSocketUpgrade(r) {
		s.serveWebSocket(w, r, p, requested, since)
		return
	}

	events, cursor, err := s.engine.EventsSince(r.Context(), since, p.Audiences(), eventPollLimit)
	if err != nil {
		writeAPIError(w, err)
		return
	}
	writeData(w, http.StatusOK, map[string]any{
		"events": eventViews(events),
		"cursor": cursor,
	})
}

func eventViews(events []*domain.RealtimeEvent) []map[string]any {
	out := make([]map[string]any, 0, len(events))
	for _, ev := range events {
		payload := ev.Payload
		if payload == nil {
			payload = map[string]any{}
		}
		out = append(out, map[string]any{
			"id":         ev.ID,
			"type":       ev.Type,
			"entityType": ev.EntityType,
			"entityId":   ev.EntityID,
			"payload":    payload,
			"createdAt":  ev.CreatedAt.UTC().Format(time.RFC3339Nano),
		})
	}
	return out
}

func parseSubprotocols(header string) []string {
	if header == "" {
		return nil
	}
	parts := strings.Split(header, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		if trimmed := strings.TrimSpace(part); trimmed != "" {
			out = append(out, trimmed)
		}
	}
	return out
}

// tokenFromSubprotocols decodes a `bearer.<base64url token>` subprotocol entry.
func tokenFromSubprotocols(protocols []string) string {
	for _, proto := range protocols {
		if !strings.HasPrefix(proto, "bearer.") {
			continue
		}
		encoded := strings.TrimPrefix(proto, "bearer.")
		if decoded, err := base64.RawURLEncoding.DecodeString(strings.TrimRight(encoded, "=")); err == nil {
			return string(decoded)
		}
		return encoded
	}
	return ""
}

func isWebSocketUpgrade(r *http.Request) bool {
	return tokenListContains(r.Header.Get("Connection"), "upgrade") &&
		strings.EqualFold(strings.TrimSpace(r.Header.Get("Upgrade")), "websocket") &&
		r.Header.Get("Sec-WebSocket-Key") != ""
}

func tokenListContains(header, want string) bool {
	for _, part := range strings.Split(header, ",") {
		if strings.EqualFold(strings.TrimSpace(part), want) {
			return true
		}
	}
	return false
}

// serveWebSocket completes the RFC 6455 handshake and streams events, replaying
// durable events after the `since` cursor first.
func (s *Server) serveWebSocket(w http.ResponseWriter, r *http.Request, p *core.Principal,
	requested []string, since int64) {

	hj, ok := w.(http.Hijacker)
	if !ok {
		writeErr(w, http.StatusInternalServerError, "internal_error", "connection cannot be upgraded")
		return
	}

	audiences := p.Audiences()
	subID, live := s.engine.Subscribe(audiences)
	defer s.engine.Unsubscribe(subID)

	backlog, cursor, err := s.engine.EventsSince(r.Context(), since, audiences, eventPollLimit)
	if err != nil {
		writeAPIError(w, err)
		return
	}

	conn, buf, err := hj.Hijack()
	if err != nil {
		return
	}
	defer conn.Close()

	accept := computeAcceptKey(r.Header.Get("Sec-WebSocket-Key"))
	handshake := "HTTP/1.1 101 Switching Protocols\r\n" +
		"Upgrade: websocket\r\nConnection: Upgrade\r\n" +
		"Sec-WebSocket-Accept: " + accept + "\r\n"
	for _, proto := range requested {
		if proto == wsSubprotocol {
			handshake += "Sec-WebSocket-Protocol: " + wsSubprotocol + "\r\n"
			break
		}
	}
	handshake += "\r\n"
	if _, err := buf.WriteString(handshake); err != nil {
		return
	}
	if err := buf.Flush(); err != nil {
		return
	}

	for _, ev := range backlog {
		if err := writeWSEvent(conn, buf, ev); err != nil {
			return
		}
	}
	if err := writeWSJSON(conn, buf, map[string]any{"type": "cursor", "cursor": cursor}); err != nil {
		return
	}

	closed := make(chan struct{})
	go func() {
		defer close(closed)
		readWSFrames(conn, buf)
	}()

	ping := time.NewTicker(wsPingInterval)
	defer ping.Stop()
	for {
		select {
		case <-closed:
			return
		case <-r.Context().Done():
			return
		case ev, open := <-live:
			if !open {
				return
			}
			// Replayed backlog already covered anything at or below the cursor.
			if ev.ID <= cursor {
				continue
			}
			if err := writeWSEvent(conn, buf, ev); err != nil {
				return
			}
		case <-ping.C:
			if err := writeWSFrame(conn, buf, opPing, nil); err != nil {
				return
			}
		}
	}
}

func computeAcceptKey(key string) string {
	sum := sha1.Sum([]byte(strings.TrimSpace(key) + wsGUID))
	return base64.StdEncoding.EncodeToString(sum[:])
}

const (
	opText   byte = 0x1
	opClose  byte = 0x8
	opPing   byte = 0x9
	opPong   byte = 0xA
)

func writeWSEvent(conn net.Conn, buf *bufio.ReadWriter, ev *domain.RealtimeEvent) error {
	views := eventViews([]*domain.RealtimeEvent{ev})
	return writeWSJSON(conn, buf, views[0])
}

func writeWSJSON(conn net.Conn, buf *bufio.ReadWriter, payload any) error {
	body, err := json.Marshal(payload)
	if err != nil {
		return err
	}
	return writeWSFrame(conn, buf, opText, body)
}

// writeWSFrame writes one unmasked server frame.
func writeWSFrame(conn net.Conn, buf *bufio.ReadWriter, opcode byte, payload []byte) error {
	_ = conn.SetWriteDeadline(time.Now().Add(wsWriteDeadline))
	header := []byte{0x80 | opcode}
	n := len(payload)
	switch {
	case n < 126:
		header = append(header, byte(n))
	case n <= 0xFFFF:
		header = append(header, 126, 0, 0)
		binary.BigEndian.PutUint16(header[2:], uint16(n))
	default:
		header = append(header, 127, 0, 0, 0, 0, 0, 0, 0, 0)
		binary.BigEndian.PutUint64(header[2:], uint64(n))
	}
	if _, err := buf.Write(header); err != nil {
		return err
	}
	if _, err := buf.Write(payload); err != nil {
		return err
	}
	return buf.Flush()
}

// readWSFrames drains client frames, answering pings and stopping on close.
func readWSFrames(conn net.Conn, buf *bufio.ReadWriter) {
	for {
		opcode, payload, err := readWSFrame(buf)
		if err != nil {
			return
		}
		switch opcode {
		case opClose:
			_ = writeWSFrame(conn, buf, opClose, nil)
			return
		case opPing:
			if err := writeWSFrame(conn, buf, opPong, payload); err != nil {
				return
			}
		}
	}
}

func readWSFrame(buf *bufio.ReadWriter) (byte, []byte, error) {
	header := make([]byte, 2)
	if _, err := io.ReadFull(buf, header); err != nil {
		return 0, nil, err
	}
	opcode := header[0] & 0x0F
	masked := header[1]&0x80 != 0
	length := int64(header[1] & 0x7F)
	switch length {
	case 126:
		ext := make([]byte, 2)
		if _, err := io.ReadFull(buf, ext); err != nil {
			return 0, nil, err
		}
		length = int64(binary.BigEndian.Uint16(ext))
	case 127:
		ext := make([]byte, 8)
		if _, err := io.ReadFull(buf, ext); err != nil {
			return 0, nil, err
		}
		length = int64(binary.BigEndian.Uint64(ext))
	}
	if length > maxBodyBytes {
		return 0, nil, errors.New("frame too large")
	}
	var mask []byte
	if masked {
		mask = make([]byte, 4)
		if _, err := io.ReadFull(buf, mask); err != nil {
			return 0, nil, err
		}
	}
	payload := make([]byte, length)
	if _, err := io.ReadFull(buf, payload); err != nil {
		return 0, nil, err
	}
	if masked {
		for i := range payload {
			payload[i] ^= mask[i%4]
		}
	}
	return opcode, payload, nil
}

