package api

import (
	"encoding/json"
	"net/http"
	"os"
	"path"
	"path/filepath"
	"strings"
)

// newStaticHandler serves the built frontend, the local map assets and the
// runtime map configuration. PMTiles are served with range support so MapLibre
// can read them directly from disk without any network map service.
func newStaticHandler(opts Options) http.Handler {
	mux := http.NewServeMux()

	if opts.MapAssetDir != "" {
		mux.Handle("/map-assets/", http.StripPrefix("/map-assets/",
			http.FileServer(http.Dir(opts.MapAssetDir))))
	}

	mux.HandleFunc("/map-config.json", func(w http.ResponseWriter, r *http.Request) {
		cfg := map[string]any{
			"styleUrl": "/map-assets/style.json",
			"center":   parseFloatList(opts.MapCenter),
			"bounds":   parseFloatList(opts.MapBounds),
			"assets":   listMapAssets(opts.MapAssetDir),
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(cfg)
	})

	frontend := opts.FrontendDir
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if frontend == "" {
			http.Error(w, "frontend build is not available", http.StatusNotFound)
			return
		}
		clean := filepath.Clean("/" + strings.TrimPrefix(r.URL.Path, "/"))
		candidate := filepath.Join(frontend, clean)
		if info, err := os.Stat(candidate); err == nil && !info.IsDir() {
			// Hashed build assets are immutable; the shell HTML is not.
			if strings.HasPrefix(clean, "/assets/") {
				w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
			}
			http.ServeFile(w, r, candidate)
			return
		}
		// Unknown paths fall back to the SPA shell for client-side routing.
		http.ServeFile(w, r, filepath.Join(frontend, "index.html"))
	})

	return mux
}

func parseFloatList(raw string) []float64 {
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ",")
	out := make([]float64, 0, len(parts))
	for _, part := range parts {
		var v float64
		if _, err := fmtSscan(strings.TrimSpace(part), &v); err != nil {
			return nil
		}
		out = append(out, v)
	}
	return out
}

func listMapAssets(dir string) []string {
	if dir == "" {
		return []string{}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return []string{}
	}
	out := make([]string, 0, len(entries))
	for _, entry := range entries {
		if !entry.IsDir() {
			out = append(out, path.Join("/map-assets", entry.Name()))
		}
	}
	return out
}

