package api

import (
        "crypto/sha256"
        "encoding/hex"
        "net/http"

        "labdelivery/internal/core"
        "labdelivery/internal/domain"
)

// requestHash fingerprints a request body so a replayed idempotency key with a
// different body can be rejected.
func requestHash(raw []byte) string {
        sum := sha256.Sum256(raw)
        return hex.EncodeToString(sum[:])
}

// respond writes the (payload, status, error) triple returned by engine mutations.
func respond(w http.ResponseWriter, payload any, status int, err error, fallback int) {
        if err != nil {
                writeAPIError(w, err)
                return
        }
        if status == 0 {
                status = fallback
        }
        writeData(w, status, payload)
}

type authenticateRequest struct {
        Username string `json:"username"`
        Password string `json:"password"`
}

func (s *Server) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
        var req authenticateRequest
        if _, ok := decode(w, r, &req); !ok {
                return
        }
        payload, status, err := s.engine.AuthenticateUser(r.Context(), req.Username, req.Password)
        respond(w, payload, status, err, http.StatusOK)
}

type selectRoleRequest struct {
        Role string `json:"role"`
}

func (s *Server) handleSelectActiveRole(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
        var req selectRoleRequest
        if _, ok := decode(w, r, &req); !ok {
                return
        }
        payload, status, err := s.engine.SelectActiveRole(r.Context(), p, domain.Role(req.Role))
        respond(w, payload, status, err, http.StatusOK)
}

func (s *Server) handleReadUser(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
        userID := pathTail(r.URL.Path, "/api/read-user")
        if userID == "" {
                writeErr(w, http.StatusNotFound, "not_found", "userId path parameter is required")
                return
        }
        payload, err := s.engine.ReadUser(p, userID)
        if err != nil {
                writeAPIError(w, err)
                return
        }
        writeData(w, http.StatusOK, payload)
}

type createUserRequest struct {
        Username        string                 `json:"username"`
        InitialPassword string                 `json:"initialPassword"`
        Email           string                 `json:"email"`
        FullName        string                 `json:"fullName"`
        Phone           string                 `json:"phone"`
        Roles           []domain.Role          `json:"roles"`
        Qualifications  []string               `json:"qualifications"`
        Certifications  []domain.Certification `json:"certifications"`
        Active          *bool                  `json:"active"`
        AssignedLocID   string                 `json:"assignedLocationId"`
}

func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
        var req createUserRequest
        if _, ok := decode(w, r, &req); !ok {
                return
        }
        active := true
        if req.Active != nil {
                active = *req.Active
        }
        payload, status, err := s.engine.CreateUser(r.Context(), p, core.CreateUserInput{
                Username:           req.Username,
                InitialPassword:    req.InitialPassword,
                Email:              req.Email,
                FullName:           req.FullName,
                Phone:              req.Phone,
                Roles:              req.Roles,
                Qualifications:     req.Qualifications,
                Certifications:     req.Certifications,
                Active:             active,
                AssignedLocationID: req.AssignedLocID,
        })
        respond(w, payload, status, err, http.StatusCreated)
}

type updateUserAccessRequest struct {
        UserID         string                 `json:"userId"`
        Roles          []domain.Role          `json:"roles"`
        Qualifications []string               `json:"qualifications"`
        Certifications []domain.Certification `json:"certifications"`
        Active         *bool                  `json:"active"`
        AssignedLocID  *string                `json:"assignedLocationId"`
}

func (s *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
        var req updateUserAccessRequest
        if _, ok := decode(w, r, &req); !ok {
                return
        }
        active := true
        if req.Active != nil {
                active = *req.Active
        }
        payload, status, err := s.engine.UpdateUserAccess(r.Context(), p, core.UpdateUserAccessInput{
                UserID:             req.UserID,
                Roles:              req.Roles,
                Qualifications:     req.Qualifications,
                Certifications:     req.Certifications,
                Active:             active,
                AssignedLocationID: req.AssignedLocID,
        })
        respond(w, payload, status, err, http.StatusCreated)
}

type setWorkerAvailabilityRequest struct {
        WorkerID      string `json:"workerId"`
        Available     *bool  `json:"available"`
        CapacityUnits *int   `json:"capacityUnits"`
}

func (s *Server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
        var req setWorkerAvailabilityRequest
        if _, ok := decode(w, r, &req); !ok {
                return
        }
        if req.Available == nil || req.CapacityUnits == nil {
                writeErr(w, http.StatusBadRequest, "invalid_json", "workerId, available and capacityUnits are required")
                return
        }
        payload, status, err := s.engine.SetWorkerAvailability(r.Context(), p, req.WorkerID, *req.Available, *req.CapacityUnits)
        respond(w, payload, status, err, http.StatusOK)
}

