import json
d = json.load(open('/workspace/contracts/openapi.contract.json'))


def flat(s, comps):
    """Return top-level property names / required set for a schema."""
    if s is None:
        return None, set()
    if '$ref' in s:
        return flat(comps['schemas'][s['$ref'].split('/')[-1]], comps)
    if 'allOf' in s:
        props, req = {}, set()
        for sub in s['allOf']:
            p, r = flat(sub, comps)
            if p:
                props.update(p)
            req |= r
        return props, req
    return s.get('properties'), set(s.get('required', []))


comps = d['components']
print('%-42s %-10s %s' % ('operationId', 'idemKey', 'request fields'))
print('-' * 120)
for p, item in d['paths'].items():
    for m, op in item.items():
        if m not in ('get', 'post', 'put', 'patch', 'delete'):
            continue
        rb = op.get('requestBody')
        props, req = (None, set())
        if rb:
            props, req = flat(rb['content']['application/json']['schema'], comps)
        names = []
        if props:
            for k in props:
                names.append(k + ('*' if k in req else ''))
        idem = 'REQUIRED' if 'idempotencyKey' in req else ('opt' if props and 'idempotencyKey' in props else '-')
        print('%-42s %-10s %s' % (op['operationId'], idem, ' '.join(names)))

print()
print('=' * 120)
print('RESPONSE data shapes (success codes)')
print('=' * 120)
for p, item in d['paths'].items():
    for m, op in item.items():
        if m not in ('get', 'post', 'put', 'patch', 'delete'):
            continue
        for code, r in op.get('responses', {}).items():
            if not code.startswith('2'):
                continue
            sch = r.get('content', {}).get('application/json', {}).get('schema')
            if not sch:
                continue
            props, req = flat(sch, comps)
            data = (props or {}).get('data')
            if data is None:
                print('%-42s %s NO-DATA %s' % (op['operationId'], code, list(props or {})))
                continue
