call("/api/ingest-presealed-sample",
     dict(pre_base, idempotencyKey=idem(), originType="home", originNodeId=None),
     token=tok["node"], expect=400, label="pre-sealed home origin rejected")
call("/api/ingest-presealed-sample", dict(pre_base, idempotencyKey=idem()),
     token=tok["req"], expect=403, label="requester cannot register pre-sealed")

print("\n[laboratory operations]")
_, lw = call("/api/list-role-work", {"role": "laboratory_team"}, token=tok["lab"],
             label="laboratory work list")
call("/api/configure-capacity", {
    "resourceId": lab_id, "capacityUnits": 44, "cooledCapacityUnits": 21,
}, token=tok["lab"], label="lab operator sets own capacity")
call("/api/configure-capacity", {
    "resourceId": cp_id, "capacityUnits": 3, "cooledCapacityUnits": 1,
}, token=tok["lab"], expect=403, label="lab operator denied other node capacity")
call("/api/configure-capacity", {
    "resourceId": cp_id, "capacityUnits": 40, "cooledCapacityUnits": 20,
}, token=tok["node"], label="node handler sets own capacity")
_, labexc = call("/api/record-laboratory-exception", {
    "sampleId": pre_sample, "laboratoryId": lab_id, "reason": "container_compromised",
    "observedAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
}, token=tok["lab"], expect=201, label="laboratory records exception")
print("   exception status:", labexc["status"], "reason:", labexc["reason"])

print("\n[capacity is never overbooked]")
_, opsc = call("/api/read-operations-state", {}, token=tok["disp"], label="capacity snapshot")
for loc in opsc["locations"]:
    cap = loc.get("capacity")
    if not cap:
        continue
    if cap["reservedUnits"] > cap["capacityUnits"]:
        failures.append(f"location {loc['name']} is overbooked: "
                        f"{cap['reservedUnits']}/{cap['capacityUnits']}")
    if cap["cooledReservedUnits"] > cap["cooledCapacityUnits"]:
        failures.append(f"location {loc['name']} cooled pool overbooked")
    if cap["availableUnits"] != cap["capacityUnits"] - cap["reservedUnits"]:
        failures.append(f"location {loc['name']} available units are inconsistent")
for cn in opsc["connections"]:
    cap = cn.get("capacity")
    if cap and cap["reservedUnits"] > cap["capacityUnits"]:
        failures.append("a connection capacity pool is overbooked")

print("\n[dispatcher plan control]")
_, dj = call("/api/read-journey-plan", {"journeyId": journey}, token=tok["disp"],
             label="plan before edits")
pv = dj["planVersion"]
call("/api/edit-active-plan", {
    "journeyId": journey, "expectedPlanVersion": pv + 50, "changeType": "adjust_stops",
    "changes": {"note": "stale version probe"}, "idempotencyKey": idem(),
}, token=tok["disp"], expect=409, label="stale plan version rejected")
call("/api/edit-active-plan", {
    "journeyId": journey, "expectedPlanVersion": pv, "changeType": "adjust_stops",
    "changes": {"note": "dispatcher adjustment"}, "idempotencyKey": idem(),
}, token=tok["cour"], expect=403, label="courier cannot edit the plan")
_, rr = call("/api/reroute-journey", {
    "journeyId": journey, "expectedPlanVersion": pv, "reason": "traffic",
    "idempotencyKey": idem(),
}, token=tok["disp"], expect=201, label="dispatcher reroutes")
print("   replanStatus:", rr["replanStatus"])
_, after_rr = call("/api/read-sample-lifecycle", {"sampleId": sample}, token=tok["disp"],
                   label="custody preserved by reroute")
if t_assign and after_rr.get("currentHolderId") != uid[t_key]:
    failures.append("replanning changed the current sample holder")
if len(after_rr.get("activeReplacementPlanIds", [])) > 1:
    failures.append("more than one active replacement plan exists")

print("\n[disruption reporting]")
call("/api/set-worker-availability", {
    "workerId": uid["cour2"], "available": False, "capacityUnits": 0,
}, token=admin, label="admin marks courier unavailable")
_, dis = call("/api/report-disruption", {
    "resourceType": "worker", "resourceId": uid["cour2"], "reason": "vehicle breakdown",
    "occurredAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
}, token=tok["disp"], expect=201, label="dispatcher reports worker disruption")
print("   replanStatus:", dis["replanStatus"], "affected:", len(dis["affectedSampleIds"]))
_, dis2 = call("/api/report-disruption", {
    "resourceType": "connection", "resourceId": conns[(cp_id, hub_id)],
    "reason": "road closed", "occurredAt": iso(datetime.now(timezone.utc)),
    "idempotencyKey": idem(),
}, token=tok["disp"], expect=201, label="dispatcher reports route disruption")

print("\n[network activation toggles]")
call("/api/set-connection-status", {
    "connectionId": conns[(cp_id, hub_id)], "active": False,
}, token=admin, label="deactivate connection")
call("/api/set-location-function-status", {
    "locationId": hub_id, "function": "hub", "active": False,
}, token=admin, label="deactivate one function")
_, lfs = call("/api/set-location-function-status", {
    "locationId": hub_id, "function": "hub", "active": True,
}, token=admin, label="reactivate that function")
call("/api/set-location-status", {"locationId": hub_id, "active": False},
     token=admin, label="deactivate location")
call("/api/set-location-status", {"locationId": hub_id, "active": True},
     token=admin, label="reactivate location")
call("/api/set-connection-status", {"connectionId": conns[(cp_id, hub_id)], "active": True},
     token=admin, label="reactivate connection")
call("/api/update-location", {
    "locationId": hub_id, "name": f"Hub {run} renamed",
    "coordinate": {"latitude": 52.3850, "longitude": 4.9000},
    "coverageKm": 4, "handlingMinutes": 12,
}, token=admin, expect=201, label="update location")
call("/api/set-location-status", {"locationId": hub_id, "active": False},
     token=tok["req"], expect=403, label="requester cannot deactivate a location")

print("\n[split and merge]")
_, sA = call("/api/create-collection-request", dict(base_req, idempotencyKey=idem()),
             token=tok["req"], expect=201, label="request A for split/merge")
_, sB = call("/api/create-collection-request", dict(base_req, idempotencyKey=idem()),
             token=tok["req"], expect=201, label="request B for split/merge")
jA, jB = sA.get("journeyId"), sB.get("journeyId")
if jA and jB:
    _, pA = call("/api/read-journey-plan", {"journeyId": jA}, token=tok["disp"],
                 label="read plan A")
    _, mg = call("/api/merge-journeys", {
        "targetJourneyId": jA, "expectedPlanVersion": pA["planVersion"],
        "sourceJourneyIds": [jB], "idempotencyKey": idem(),
    }, token=tok["disp"], expect=201, label="merge journeys")
    print("   merged samples:", len(mg["sampleIds"]), "mode:", mg["routeMode"])
    _, pA2 = call("/api/read-journey-plan", {"journeyId": jA}, token=tok["disp"],
                  label="read merged plan")
    if len(mg["sampleIds"]) >= 2:
        _, sp = call("/api/split-journey", {
            "journeyId": jA, "expectedPlanVersion": pA2["planVersion"],
            "sampleIds": [sB["sampleId"]], "idempotencyKey": idem(),
        }, token=tok["disp"], expect=201, label="split journey")
        print("   split ->", sp["splitJourney"]["journeyId"][:8])
    call("/api/merge-journeys", {
        "targetJourneyId": jA, "expectedPlanVersion": 1,
        "sourceJourneyIds": [jB], "idempotencyKey": idem(),
    }, token=tok["disp"], expect=409, label="merge with stale version rejected")

print("\n[Pulse must not wait for batching]")
_, pulse = call("/api/create-collection-request",
                dict(base_req, idempotencyKey=idem(), sampleTypeId=types["Pulse"]),
                token=tok["req"], expect=201, label="create Pulse request")
if pulse.get("journeyId"):
    _, pj = call("/api/read-journey-plan", {"journeyId": pulse["journeyId"]},
                 token=tok["disp"], label="Pulse journey plan")
    print("   Pulse routeMode:", pj.get("routeMode"), "samples:", len(pj.get("sampleIds", [])))
    if pj.get("routeMode") == "batched":
        failures.append("a time-critical Pulse sample was placed in a batched journey")

print("\n[Frost requires a cooled route]")
_, frost = call("/api/create-collection-request",
                dict(base_req, idempotencyKey=idem(), sampleTypeId=types["Frost"],
                     containerType="cooled", temperatureMinC=2, temperatureMaxC=8),
                token=tok["req"], expect=201, label="create Frost request")
print("   Frost serviceability:", frost["serviceability"])

print("\n[laboratory receipt]")
_, lab_work = call("/api/list-role-work", {"role": "laboratory_team"}, token=tok["lab"],
                   label="lab work before receipt")
for aid in offers(lab_work, "laboratory"):
    call("/api/accept-assignment", {"assignmentId": aid, "idempotencyKey": idem()},
         token=tok["lab"], expect=201, label="lab accepts assignment")
call("/api/confirm-laboratory-receipt", {
    "sampleId": sample, "laboratoryId": lab_id,
    "receivedAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
}, token=tok["req"], expect=403, label="requester cannot confirm receipt")

print("\n[node handler work]")
_, nw = call("/api/list-role-work", {"role": "node_handler"}, token=tok["node"],
             label="node handler work")
for aid in offers(nw, "node")[:1]:
    call("/api/accept-assignment", {"assignmentId": aid, "idempotencyKey": idem()},
         token=tok["node"], expect=201, label="node handler accepts")
    call("/api/accept-assignment", {"assignmentId": aid, "idempotencyKey": idem()},
         token=tok["hubh"], expect=403, label="handler at another node cannot accept")

print("\n[monitoring]")
_, ops = call("/api/read-operations-state", {}, token=tok["disp"], label="dispatcher monitor")
print("   samples:", len(ops["samples"]), "workers:", len(ops["workers"]),
      "locations:", len(ops["locations"]), "connections:", len(ops["connections"]),
      "exceptions:", len(ops["exceptions"]), "handoffs:", len(ops["handoffs"]),
      "spread:", ops["assignmentCountSpread"], "ineligible:", ops["ineligibleAssignmentCount"])
if ops["ineligibleAssignmentCount"] != 0:
    failures.append(f"{ops['ineligibleAssignmentCount']} assignments are held by "
                    f"ineligible workers")
call("/api/read-operations-state", {"filters": {"sampleTypeId": types["Amber"]}},
     token=tok["disp"], label="monitor filtered by sample type")
call("/api/read-operations-state", {}, token=tok["req"], expect=403,
     label="requester denied monitor")
call("/api/read-operations-state", {}, token=admin, label="administrator monitor")

print("\n[audit trail]")
_, au = call("/api/search-audit-trail", {"limit": 10, "order": "newest_first"},
             token=tok["disp"], label="audit newest first")
print("   total:", au["total"], "returned:", au["returned"], "hasMore:", au["hasMore"])
if au["total"] < 10:
    failures.append("audit log is suspiciously small")
_, au_old = call("/api/search-audit-trail", {"limit": 5, "order": "oldest_first"},
                 token=tok["disp"], label="audit oldest first")
if au_old["entries"] and au["entries"]:
    if au_old["entries"][0]["occurredAt"] > au["entries"][0]["occurredAt"]:
        pass
    else:
        failures.append("audit ordering flags appear to be ignored")
_, au_s = call("/api/search-audit-trail", {"entityId": sample, "limit": 100},
               token=tok["disp"], label="audit by entity id")
if au_s["total"] == 0:
    failures.append("no audit entries recorded for the sample")
_, au_a = call("/api/search-audit-trail", {"action": "sign_in", "limit": 50},
               token=tok["disp"], label="audit by action")
if any(e["action"] != "sign_in" for e in au_a["entries"]):
    failures.append("the audit action filter returned unrelated actions")
_, au_f = call("/api/search-audit-trail", {"success": False, "limit": 50},
               token=tok["disp"], label="audit failed outcomes")
if any(e["success"] for e in au_f["entries"]):
    failures.append("the audit success filter returned successful entries")
print("   failed-outcome entries:", au_f["total"])
_, au_p = call("/api/search-audit-trail", {"limit": 5, "offset": 5},
               token=tok["disp"], label="audit pagination")
if au_p["offset"] != 5:
    failures.append("audit pagination offset was not echoed")
call("/api/search-audit-trail", {"limit": 5}, token=tok["col"], expect=403,
     label="collector denied audit")

print("\n[realtime events]")
_, ev = call("/api/events?since=0", token=tok["disp"], label="event replay from 0")
print("   events:", len(ev.get("events", [])), "cursor:", ev.get("cursor"))
if ev.get("cursor", 0) <= 0:
    failures.append("no durable events were recorded")
seqs = [e["id"] for e in ev.get("events", [])]
if seqs != sorted(seqs):
    failures.append("replayed events are not in sequence order")
if len(seqs) > 2:
    _, ev2 = call(f"/api/events?since={seqs[1]}", token=tok["disp"], label="event resume")
    if any(e["id"] <= seqs[1] for e in ev2.get("events", [])):
        failures.append("resuming with since= replayed already-delivered events")
call("/api/events?since=0", expect=401, label="events require a token")

print("\n[cancel]")
_, sc = call("/api/create-collection-request", dict(base_req, idempotencyKey=idem()),
             token=tok["req"], expect=201, label="request to cancel")
if sc.get("journeyId"):
    _, pc = call("/api/read-journey-plan", {"journeyId": sc["journeyId"]}, token=tok["disp"],
                 label="plan to cancel")
    _, cj = call("/api/cancel-journey", {
        "journeyId": sc["journeyId"], "expectedPlanVersion": pc["planVersion"],
        "reason": "requester withdrew", "idempotencyKey": idem(),
    }, token=tok["disp"], expect=201, label="cancel journey")
    print("   cancelled:", cj["status"], "samples:", len(cj["sampleIds"]))
    _, ops_after_cancel = call("/api/read-operations-state", {}, token=tok["disp"],
                               label="capacity released after cancel")
    for loc in ops_after_cancel["locations"]:
        cap = loc.get("capacity")
        if cap and cap["reservedUnits"] > cap["capacityUnits"]:
            failures.append("capacity overbooked after cancellation")

print("\n[coverage]")
all_ops = {op["operationId"] for item in CONTRACT["paths"].values()
           for m, op in item.items() if m in ("get", "post", "put", "patch", "delete")}
gaps = sorted(all_ops - set(covered))
print(f"   exercised {len(covered)}/{len(all_ops)} contract operations")
if gaps:
    print("   not exercised:", gaps)

print("\n" + "=" * 72)
print(f"{validated} response bodies validated against the pinned contract")
if failures:
    print(f"\n{len(failures)} PROBLEM(S):")
    for f in failures:
        print("  -", f)
    sys.exit(1)
print("ALL CONTRACT CHECKS PASSED")

