	return []string{"role:dispatcher", "role:administrator"}
}

func userAudience(userID string) string { return "user:" + userID }

func roleAudience(role domain.Role) string { return "role:" + string(role) }

// mutate runs fn under the engine lock, commits its changeset and publishes events.
//
// When idemKey is set the operation is replayed from the recorded response if the same
// key was already used with an identical request body.
func (e *Engine) mutate(ctx context.Context, operation, idemKey, idemHash, userID string,
	fn func(t *txn) (any, int, error)) (any, int, error) {
	e.mu.Lock()
	defer e.mu.Unlock()
	return e.mutateLocked(ctx, operation, idemKey, idemHash, userID, fn)
}

func (e *Engine) mutateLocked(ctx context.Context, operation, idemKey, idemHash, userID string,
	fn func(t *txn) (any, int, error)) (any, int, error) {
	if idemKey != "" {
		rec, err := e.st.LookupIdempotency(ctx, operation, userID, idemKey)
		if err != nil {
			return nil, 0, errInternal(err.Error())
		}
		if rec != nil {
			if rec.RequestHash != idemHash {
				return nil, 0, errIdempotencyConflict()
			}
			return json.RawMessage(rec.Response), rec.StatusCode, nil
		}
	}

	t := &txn{e: e, now: e.now(), cs: &store.Changeset{}}
	result, status, err := fn(t)
	if err != nil {
		// Persist audit records describing the rejected attempt; discard everything else.
		if len(t.cs.Audit) > 0 {
			failed := &store.Changeset{Audit: t.cs.Audit}
			if commitErr := e.st.Commit(ctx, failed); commitErr != nil {
				return nil, 0, errInternal(commitErr.Error())
			}
		}
		return nil, 0, err
	}
	if idemKey != "" {
		raw, mErr := json.Marshal(result)
		if mErr != nil {
			return nil, 0, errInternal(mErr.Error())
		}
		t.cs.Idem = append(t.cs.Idem, &domain.IdempotencyRecord{
			Key:         idemKey,
			Operation:   operation,
			UserID:      userID,
			RequestHash: idemHash,
			StatusCode:  status,
			Response:    raw,
			CreatedAt:   t.now,
		})
	}
	if err := e.st.Commit(ctx, t.cs); err != nil {
		return nil, 0, errInternal(err.Error())
	}
	e.publish(t.events)
	if e.snapshotDirty {
		e.snapshotDirty = false
		go e.PublishServiceability(context.Background())
	}
	return result, status, nil
}

// read runs fn under the engine lock without writing anything.
func (e *Engine) read(fn func() (any, error)) (any, error) {
	e.mu.Lock()
	defer e.mu.Unlock()
	return fn()
}

func (e *Engine) publish(events []*domain.RealtimeEvent) {
	if len(events) == 0 {
		return
	}
	for _, sub := range e.subs {
		for _, ev := range events {
			if !matchAudience(sub.audiences, ev.Audience) {
				continue
			}
			select {
			case sub.ch <- ev:
			default:
			}
		}
	}
}

func matchAudience(subscribed map[string]bool, audiences []string) bool {
	if len(audiences) == 0 {
		return true
	}
	for _, a := range audiences {
		if subscribed[a] {
			return true
		}
	}
	return false
}

// Subscribe registers a realtime listener for the audiences of the given session.
func (e *Engine) Subscribe(audiences []string) (int64, <-chan *domain.RealtimeEvent) {
	e.mu.Lock()
	defer e.mu.Unlock()
	e.subSeq++
	set := map[string]bool{}
	for _, a := range audiences {
		set[a] = true
	}
	sub := &subscriber{id: e.subSeq, audiences: set, ch: make(chan *domain.RealtimeEvent, 256)}
	e.subs[sub.id] = sub
	return sub.id, sub.ch
}

// Unsubscribe removes a realtime listener.
func (e *Engine) Unsubscribe(id int64) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if sub, ok := e.subs[id]; ok {
		delete(e.subs, id)
		close(sub.ch)
	}
}

// EventsSince replays durable events for a reconnecting client.
func (e *Engine) EventsSince(ctx context.Context, since int64, audiences []string, limit int) ([]*domain.RealtimeEvent, int64, error) {
	events, err := e.st.EventsSince(ctx, since, audiences, limit)
	if err != nil {
		return nil, 0, errInternal(err.Error())
	}
	cursor := since
	for _, ev := range events {
		if ev.ID > cursor {
			cursor = ev.ID
		}
	}
	if cursor < since {
		cursor = since
	}
	if len(events) == 0 {
		e.mu.Lock()
		if e.eventSeq > cursor {
			cursor = e.eventSeq
		}
		e.mu.Unlock()
	}
	return events, cursor, nil
}

// timelineFor returns the ordered status history recorded for an entity.
func (e *Engine) timelineFor(id string) []domain.AuditRecord {
	recs := e.timelines[id]
	out := make([]domain.AuditRecord, len(recs))
	copy(out, recs)
	sort.SliceStable(out, func(i, j int) bool { return out[i].EventID < out[j].EventID })
	return out
}

func (e *Engine) markNetworkChanged(t *txn) {
	e.networkRevision++
	t.cs.SetMeta("networkRevision", e.networkRevision)
	e.snapshotDirty = true
}

