	}
}

func matchAudience(subscribed map[string]bool, audiences []string) bool {
	if len(audiences) == 0 {
		return true
	}
	for _, a := range audiences {
		if subscribed[a] {
			return true
		}
	}
	return false
}

// Subscribe registers a realtime listener for the audiences of the given session.
func (e *Engine) Subscribe(audiences []string) (int64, <-chan *domain.RealtimeEvent) {
	e.mu.Lock()
	defer e.mu.Unlock()
	e.subSeq++
	set := map[string]bool{}
	for _, a := range audiences {
		set[a] = true
	}
	sub := &subscriber{id: e.subSeq, audiences: set, ch: make(chan *domain.RealtimeEvent, 256)}
	e.subs[sub.id] = sub
	return sub.id, sub.ch
}

// Unsubscribe removes a realtime listener.
func (e *Engine) Unsubscribe(id int64) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if sub, ok := e.subs[id]; ok {
		delete(e.subs, id)
		close(sub.ch)
	}
}

// EventsSince replays durable events for a reconnecting client.
func (e *Engine) EventsSince(ctx context.Context, since int64, audiences []string, limit int) ([]*domain.RealtimeEvent, int64, error) {
	events, err := e.st.EventsSince(ctx, since, audiences, limit)
	if err != nil {
		return nil, 0, errInternal(err.Error())
	}
	cursor := since
	for _, ev := range events {
		if ev.ID > cursor {
			cursor = ev.ID
		}
	}
	if cursor < since {
		cursor = since
	}
	if len(events) == 0 {
		e.mu.Lock()
		if e.eventSeq > cursor {
			cursor = e.eventSeq
		}
		e.mu.Unlock()
	}
	return events, cursor, nil
}

// timelineFor returns the ordered status history recorded for an entity.
func (e *Engine) timelineFor(id string) []domain.AuditRecord {
	recs := e.timelines[id]
	out := make([]domain.AuditRecord, len(recs))
	copy(out, recs)
	sort.SliceStable(out, func(i, j int) bool { return out[i].EventID < out[j].EventID })
	return out
}

func (e *Engine) markNetworkChanged(t *txn) {
	e.networkRevision++
	t.cs.SetMeta("networkRevision", e.networkRevision)
	e.snapshotDirty = true
}

