package api

import (
	"net/http"

	"labdelivery/internal/core"
)

func (s *Server) routes() {
	s.mux.HandleFunc("/ready", s.handleReady)

	s.postPublic("/api/authenticate-user", s.handleAuthenticateUser)
	s.post("/api/select-active-role", s.handleSelectActiveRole)

	// Users, certifications and assignments to a node or laboratory.
	s.post("/api/create-user", s.handleCreateUser)
	s.post("/api/update-user-access", s.handleUpdateUserAccess)
	s.get("/api/read-user/", s.handleReadUser)
	s.post("/api/set-worker-availability", s.handleSetWorkerAvailability)

	// Network structure.
	s.post("/api/create-location", s.handleCreateLocation)
	s.post("/api/update-location", s.handleUpdateLocation)
	s.post("/api/set-location-status", s.handleSetLocationStatus)
	s.post("/api/set-location-function-status", s.handleSetLocationFunctionStatus)
	s.post("/api/create-connection", s.handleCreateConnection)
	s.post("/api/set-connection-status", s.handleSetConnectionStatus)
	s.post("/api/create-sample-type", s.handleCreateSampleType)
	s.post("/api/update-sample-type", s.handleUpdateSampleType)
	s.post("/api/configure-capacity", s.handleConfigureCapacity)
	s.post("/api/configure-laboratory-acceptance", s.handleConfigureLaboratoryAcceptance)

	// Requests and serviceability.
	s.post("/api/check-serviceability", s.handleCheckServiceability)
	s.post("/api/create-collection-request", s.handleCreateCollectionRequest)
	s.post("/api/ingest-presealed-sample", s.handleIngestPreSealedSample)
	s.post("/api/read-serviceability-snapshot", s.handleReadServiceabilitySnapshot)

	// Assignments and custody.
	s.post("/api/accept-assignment", s.handleAcceptAssignment)
	s.post("/api/decline-assignment", s.handleDeclineAssignment)
	s.post("/api/collect-and-seal-sample", s.handleCollectAndSealSample)
	s.post("/api/record-handling-checkpoint", s.handleRecordHandlingCheckpoint)
	s.post("/api/initiate-handoff", s.handleInitiateHandoff)
	s.post("/api/confirm-handoff", s.handleConfirmHandoff)
	s.post("/api/update-assignment-progress", s.handleUpdateAssignmentProgress)
	s.post("/api/record-worker-location", s.handleRecordWorkerLocation)
	s.post("/api/confirm-laboratory-receipt", s.handleConfirmLaboratoryReceipt)
	s.post("/api/record-laboratory-exception", s.handleRecordLaboratoryException)

	// Dispatcher replanning.
	s.post("/api/edit-active-plan", s.handleEditActivePlan)
	s.post("/api/split-journey", s.handleSplitJourney)
	s.post("/api/merge-journeys", s.handleMergeJourneys)
	s.post("/api/cancel-journey", s.handleCancelJourney)
	s.post("/api/reroute-journey", s.handleRerouteJourney)
	s.post("/api/report-disruption", s.handleReportDisruption)

	// Reads.
	s.post("/api/list-role-work", s.handleListRoleWork)
	s.post("/api/read-journey-plan", s.handleReadJourneyPlan)
	s.post("/api/read-sample-lifecycle", s.handleReadSampleLifecycle)
	s.get("/api/read-sample-state/", s.handleReadSampleState)
	s.post("/api/read-operations-state", s.handleReadOperationsState)
	s.post("/api/search-audit-trail", s.handleSearchAuditTrail)

	s.get("/api/ui/bootstrap", s.handleReadUIBootstrap)
	s.mux.HandleFunc("/api/events", s.handleEvents)

	// Option lists for the UI forms. The pinned contract fixes the bootstrap
	// shape and has no sample-type listing, so this lives outside /api.
	s.get("/ui-reference", s.handleReadUIReference)

	// Any other /api path is not part of the contract.
	s.mux.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
		writeErr(w, http.StatusNotFound, "not_found", "unknown API operation")
	})
}

func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeErr(w, http.StatusMethodNotAllowed, "method_not_allowed", "this operation requires GET")
		return
	}
	if err := s.engine.Ready(r.Context()); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]any{"status": "starting"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"status": "ready"})
}

func (s *Server) handleReadUIReference(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
	payload, err := s.engine.ReadUIReference(p)
	if err != nil {
		writeAPIError(w, err)
		return
	}
	writeData(w, http.StatusOK, payload)
}

func (s *Server) handleReadUIBootstrap(w http.ResponseWriter, r *http.Request, p *core.Principal, _ []byte) {
	payload, err := s.engine.ReadUIBootstrap(p)
	if err != nil {
		writeAPIError(w, err)
		return
	}
	writeData(w, http.StatusOK, payload)
}

