    }, token=tok[holder], expect=201, label="collector seals sample")
    print("   status:", sealed["status"], "holder:", sealed["currentHolderId"][:8],
          "compliant:", sealed["handlingCompliant"])
    if sealed["currentHolderId"] != uid[holder]:
        failures.append("sealing did not make the collector the current holder")
    call("/api/collect-and-seal-sample", {
        "sampleId": sample, "assignmentId": coll,
        "collectedAt": iso(now - timedelta(hours=5)),
        "containerType": "standard", "observedTemperatureC": 20, "idempotencyKey": idem(),
    }, token=tok[holder], expect=409, label="collection outside window rejected")
    _, cpk = call("/api/record-handling-checkpoint", {
        "sampleId": sample, "assignmentId": coll, "containerType": "standard",
        "observedTemperatureC": 21, "recordedAt": iso(datetime.now(timezone.utc)),
        "idempotencyKey": idem(),
    }, token=tok[holder], expect=201, label="in-range checkpoint")
