        failures.append("an in-range handling checkpoint was reported non-compliant")

print("\n[journey plan visibility by role]")
_, dp = call("/api/read-journey-plan", {"journeyId": journey}, token=tok["disp"],
             label="dispatcher sees full plan")
print("   mode:", dp.get("routeMode"), "legs:", len(dp.get("legs", [])),
      "stops:", len(dp.get("orderedStops", [])), "version:", dp.get("planVersion"))
if len(dp.get("legs", [])) < 1:
    failures.append("journey plan has no transport legs")
stops = dp.get("orderedStops", [])
if [s["sequence"] for s in stops] != sorted(s["sequence"] for s in stops):
    failures.append("journey stops are not in ascending sequence order")
call("/api/read-journey-plan", {"journeyId": journey}, token=tok["req"],
     label="requester sees own journey")
_, wp = call("/api/read-journey-plan", {"journeyId": journey}, token=tok["cour"],
             label="courier sees scoped plan")
if wp.get("scope") != "assigned_legs":
    failures.append(f"courier plan is not scoped to assigned legs: scope={wp.get('scope')}")
call("/api/read-journey-plan", {"journeyId": str(uuid.uuid4())}, token=tok["disp"],
     expect=404, label="unknown journey is 404")

print("\n[sample state, timeline and freshness]")
_, ss = call(f"/api/read-sample-state/{sample}", token=tok["req"], label="requester sample state")
print("   status:", ss["state"]["status"], "stale:", ss["locationStale"],
      "timeline:", len(ss["timeline"]))
ids = [t["eventId"] for t in ss["timeline"]]
if ids != sorted(ids):
