    }, token=tok[t_key], expect=201, label="receiver confirms")
    print("   after both:", hc2["status"], "holder:", hc2["currentHolderId"][:8])
    if hc2["currentHolderId"] != uid[t_key]:
        failures.append("receiver did not become custodian after both confirmations")
    _, hc3 = call("/api/confirm-handoff", {
