    "deliveryDeadline": T(hours=9), "containerType": "cooled",
    "temperatureMinC": 2, "temperatureMaxC": 8,
}
_, pre = call("/api/ingest-presealed-sample", dict(pre_base, idempotencyKey=idem()),
              token=tok["node"], expect=201, label="node handler registers pre-sealed")
pre_sample = pre["sampleId"]
print("   sealed:", pre.get("alreadySealed"), "originType:", pre.get("originType"))
_, pl = call("/api/read-sample-lifecycle", {"sampleId": pre_sample}, token=tok["disp"],
             label="pre-sealed lifecycle")
if not pl["sealed"]:
    failures.append("a pre-sealed sample is not marked sealed")
if pl.get("currentHolderId") != uid["node"]:
    failures.append("the registrant of a pre-sealed sample is not the current holder")
call("/api/ingest-presealed-sample",
     dict(pre_base, idempotencyKey=idem(), originType="home", originNodeId=None),
     token=tok["node"], expect=400, label="pre-sealed home origin rejected")
call("/api/ingest-presealed-sample", dict(pre_base, idempotencyKey=idem()),
