}, token=tok["disp"], expect=409, label="stale plan version rejected")
call("/api/edit-active-plan", {
    "journeyId": journey, "expectedPlanVersion": pv, "changeType": "adjust_stops",
    "changes": {"note": "dispatcher adjustment"}, "idempotencyKey": idem(),
}, token=tok["cour"], expect=403, label="courier cannot edit the plan")
_, rr = call("/api/reroute-journey", {
    "journeyId": journey, "expectedPlanVersion": pv, "reason": "traffic",
