"""Drive a running server through a full scenario and validate every response
body against the pinned schemas in contracts/openapi.contract.json.

Usage: python3 backend/testdata/contract_check.py [base-url]
"""
import copy
import json
import sys
import urllib.error
import urllib.request
import uuid
from datetime import datetime, timedelta, timezone

from jsonschema import Draft202012Validator

BASE = (sys.argv[1] if len(sys.argv) > 1 else "http://127.0.0.1:18082").rstrip("/")
CONTRACT = json.load(open("/workspace/contracts/openapi.contract.json"))

failures = []
validated = 0
covered = {}


def resolve(method, path):
    for tmpl, item in CONTRACT["paths"].items():
        op = item.get(method.lower())
        if not op:
            continue
        t = tmpl.strip("/").split("/")
        p = path.split("?")[0].strip("/").split("/")
        if len(t) == len(p) and all(a.startswith("{") or a == b for a, b in zip(t, p)):
            return tmpl, op
    return None, None


def check_schema(op, tmpl, method, status, payload, label):
    global validated
    responses = op.get("responses", {})
    spec = responses.get(str(status))
    if spec is None:
        failures.append(f"{label}: HTTP {status} is not declared for {method} {tmpl} "
                        f"(contract declares {sorted(responses)})")
        return
    schema = spec.get("content", {}).get("application/json", {}).get("schema")
    if schema is None:
        return
    full = copy.deepcopy(schema)
    full["components"] = CONTRACT["components"]
    errs = sorted(Draft202012Validator(full).iter_errors(payload), key=lambda e: e.json_path)
    if errs:
        e = errs[0]
        failures.append(f"{label}: HTTP {status} body violates contract at "
                        f"{e.json_path}: {e.message[:200]}")
    else:
        validated += 1


def call(path, body=None, token=None, method=None, expect=200, label=None):
    data = json.dumps(body).encode() if body is not None else None
    headers = {}
    if data:
        headers["Content-Type"] = "application/json"
    if token:
        headers["Authorization"] = "Bearer " + token
    method = method or ("POST" if body is not None else "GET")
    req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req) as r:
            status, raw = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, raw = e.code, e.read()
    try:
        payload = json.loads(raw or b"{}")
    except Exception:
        payload = {"_raw": raw[:200].decode(errors="replace")}

    label = label or f"{method} {path}"
    tmpl, op = resolve(method, path)
    if op is None:
        failures.append(f"{label}: {method} {path} is not in the contract")
    else:
        covered.setdefault(op["operationId"], set()).add(status)
        check_schema(op, tmpl, method, status, payload, label)

    if status != expect:
        failures.append(f"{label}: expected HTTP {expect} got {status} -> "
                        f"{json.dumps(payload)[:300]}")
        print(f"  FAIL {label}: {status} {json.dumps(payload)[:200]}")
    else:
        print(f"  ok   {label}: {status}")
    return status, payload.get("data", payload)


def idem():
    return str(uuid.uuid4())


def iso(dt):
    return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


now = datetime.now(timezone.utc)
run = uuid.uuid4().hex[:8]
T = lambda **kw: iso(now + timedelta(**kw))

print("\n[authentication]")
call("/api/authenticate-user", {"username": "admin", "password": "WRONG"}, expect=401,
     label="wrong password rejected")
call("/api/authenticate-user", {"username": f"ghost-{run}", "password": "x"}, expect=401,
     label="unknown user rejected")
_, a = call("/api/authenticate-user", {"username": "admin", "password": "secret123"},
            label="admin signs in")
admin = a["sessionToken"]
if a["activeRole"] != "administrator":
    failures.append(f"single-role admin should start as administrator, got {a['activeRole']}")
call("/api/read-operations-state", {}, expect=401, label="no token rejected")
call("/api/read-operations-state", {}, token="not-a-token", expect=401,
     label="bad token rejected")

print("\n[bootstrap and default sample types]")
_, boot = call("/api/ui/bootstrap", token=admin, label="ui bootstrap")
ref = json.loads(urllib.request.urlopen(urllib.request.Request(
    BASE + "/ui-reference", headers={"Authorization": "Bearer " + admin})).read())["data"]
types = {t["name"]: t["sampleTypeId"] for t in ref["sampleTypes"]}
missing = [n for n in ("Amber", "Indigo", "Frost", "Pulse") if n not in types]
if missing:
    failures.append(f"default sample types not available: {missing}")
print("   sample types:", sorted(types))

print("\n[network structure]")
_, lab = call("/api/create-location", {
    "name": f"Lab {run}", "coordinate": {"latitude": 52.3702, "longitude": 4.8952},
    "coverageKm": 4.5, "handlingMinutes": 15, "active": True,
    "functions": ["laboratory", "hub", "transfer_point"],
}, token=admin, expect=201, label="create laboratory")
lab_id = lab["locationId"]
_, hub = call("/api/create-location", {
    "name": f"Hub {run}", "coordinate": {"latitude": 52.3850, "longitude": 4.9000},
    "coverageKm": 4, "handlingMinutes": 10, "active": True,
    "functions": ["hub", "transfer_point"],
}, token=admin, expect=201, label="create hub")
hub_id = hub["locationId"]
_, cp = call("/api/create-location", {
    "name": f"Collection {run}", "coordinate": {"latitude": 52.4000, "longitude": 4.9100},
    "coverageKm": 5, "handlingMinutes": 8, "active": True,
    "functions": ["collection_point", "transfer_point"],
}, token=admin, expect=201, label="create collection point")
cp_id = cp["locationId"]

call("/api/create-location", {
    "name": "Too much coverage", "coordinate": {"latitude": 52.4, "longitude": 4.9},
    "coverageKm": 40, "handlingMinutes": 5, "active": True, "functions": ["collection_point"],
}, token=admin, expect=400, label="coverage over 5km rejected")
call("/api/create-location", {
    "name": "Bad coordinate", "coordinate": {"latitude": 999, "longitude": 4.9},
    "coverageKm": 3, "handlingMinutes": 5, "active": True, "functions": ["collection_point"],
}, token=admin, expect=400, label="invalid coordinate rejected")
call("/api/create-location", {
    "name": "No functions", "coordinate": {"latitude": 52.4, "longitude": 4.9},
    "coverageKm": 3, "handlingMinutes": 5, "active": True, "functions": [],
}, token=admin, expect=400, label="location with no function rejected")

conns = {}
for frm, to, mins in ((cp_id, hub_id, 18), (hub_id, lab_id, 22), (cp_id, lab_id, 35)):
    _, c = call("/api/create-connection", {
        "fromLocationId": frm, "toLocationId": to, "travelMinutes": mins,
        "costUnits": 10, "cooled": True, "active": True,
    }, token=admin, expect=201, label=f"connect {frm[:6]}->{to[:6]}")
    conns[(frm, to)] = c["connectionId"]

for rid in (cp_id, hub_id, lab_id, conns[(cp_id, hub_id)], conns[(hub_id, lab_id)],
            conns[(cp_id, lab_id)]):
    call("/api/configure-capacity", {
        "resourceId": rid, "capacityUnits": 40, "cooledCapacityUnits": 20,
    }, token=admin, label=f"capacity {rid[:6]}")

for st in types.values():
    call("/api/configure-laboratory-acceptance", {
        "laboratoryId": lab_id, "sampleTypeId": st, "accepts": True,
    }, token=admin, label=f"lab accepts {st[:6]}")

print("\n[sample type administration]")
_, nt = call("/api/create-sample-type", {
    "name": f"Custom-{run}", "containerType": "standard", "temperatureMinC": 2,
    "temperatureMaxC": 25, "qualifiedCollectorRequired": False,
    "requiresCooledRoute": False, "batchingAllowed": True,
}, token=admin, expect=201, label="create sample type")
call("/api/update-sample-type", {
    "sampleTypeId": nt["sampleTypeId"], "containerType": "standard",
    "temperatureMinC": 2, "temperatureMaxC": 30,
}, token=admin, expect=201, label="update sample type")

print("\n[users, roles and certifications]")
people = {
    "req":  (["requester"], [], {}),
    "col":  (["collection_professional"], ["Amber", "Indigo", "Frost", "Pulse"], {}),
    "col2": (["collection_professional"], ["Amber", "Indigo", "Frost", "Pulse"], {}),
    "cour": (["delivery_partner"], [], {}),
    "cour2": (["delivery_partner"], [], {}),
    "node": (["node_handler"], [], {"assignedLocationId": cp_id}),
    "hubh": (["node_handler"], [], {"assignedLocationId": hub_id}),
    "lab":  (["laboratory_team"], [], {"assignedLocationId": lab_id}),
    "disp": (["dispatcher", "requester"], [], {}),
}
uid, tok = {}, {}
for key, (roles, certs, extra) in people.items():
    body = {"username": f"{key}-{run}", "initialPassword": "Passw0rd!",
            "fullName": key.title(), "roles": roles, "active": True,
            "certifications": [{"code": c, "active": True} for c in certs],
            "qualifications": certs}
    body.update(extra)
    _, u = call("/api/create-user", body, token=admin, expect=201, label="create " + key)
    uid[key] = u["userId"]
    _, s = call("/api/authenticate-user",
                {"username": f"{key}-{run}", "password": "Passw0rd!"}, label="sign in " + key)
    tok[key] = s["sessionToken"]

call("/api/create-user", {
    "username": f"req-{run}", "initialPassword": "Passw0rd!", "roles": ["requester"],
    "active": True,
}, token=admin, expect=409, label="duplicate username rejected")
call("/api/create-user", {
    "username": f"sneak-{run}", "initialPassword": "Passw0rd!", "roles": ["administrator"],
    "active": True,
}, token=tok["req"], expect=403, label="requester cannot create users")
call(f"/api/read-user/{uid['col']}", token=admin, label="admin reads user")
call(f"/api/read-user/{uuid.uuid4()}", token=admin, expect=404, label="unknown user is 404")
call("/api/update-user-access", {
    "userId": uid["cour2"], "roles": ["delivery_partner"], "active": True,
    "certifications": [{"code": "Amber", "active": True}], "qualifications": ["Amber"],
}, token=admin, expect=201, label="update user access")
call("/api/update-user-access", {
    "userId": uid["cour2"], "roles": ["administrator"], "active": True,
}, token=tok["cour"], expect=403, label="worker cannot grant itself roles")
print("\n[role selection]")
# A multi-role account has nothing selected until it chooses, so privileged
# checks for this token only mean something after selection.
call("/api/create-location", {
    "name": "Unselected", "coordinate": {"latitude": 52.4, "longitude": 4.9},
    "coverageKm": 3, "handlingMinutes": 5, "active": True, "functions": ["collection_point"],
}, token=tok["disp"], expect=409, label="multi-role session must select a role first")
_, sel = call("/api/select-active-role", {"role": "dispatcher"}, token=tok["disp"],
              label="dispatcher role selected")
call("/api/create-location", {
    "name": "Unprivileged", "coordinate": {"latitude": 52.4, "longitude": 4.9},
    "coverageKm": 3, "handlingMinutes": 5, "active": True, "functions": ["collection_point"],
}, token=tok["disp"], expect=403, label="dispatcher cannot create a location")
call("/api/create-sample-type", {
    "name": "Unprivileged", "containerType": "standard", "temperatureMinC": 2,
    "temperatureMaxC": 8,
}, token=tok["disp"], expect=403, label="dispatcher cannot create a sample type")
if sel["activeRole"] != "dispatcher":
    failures.append("selected role was not applied")
if sorted(sel["roles"]) != ["dispatcher", "requester"]:
    failures.append(f"role switch altered the account roles: {sel['roles']}")
call("/api/select-active-role", {"role": "administrator"}, token=tok["disp"], expect=403,
     label="cannot select an unheld role")

print("\n[serviceability]")
origin = {"latitude": 52.4020, "longitude": 4.9125}
_, svc = call("/api/check-serviceability", {
    "origin": origin, "originType": "home", "sampleTypeId": types["Amber"],
    "requestedAt": T(minutes=1), "earliestCollectionAt": T(minutes=15),
    "latestCollectionAt": T(hours=3), "deliveryDeadline": T(hours=10),
}, token=tok["req"], label="origin inside coverage")
print("   serviceable:", svc["serviceable"], "reason:", svc["reason"],
      "version:", svc["serviceabilityVersion"])
if not svc["serviceable"]:
    failures.append(f"origin within 5km reported unserviceable: {svc['reason']}")

_, ops0 = call("/api/read-operations-state", {}, token=tok["disp"], label="state before dry run")
n_before = (len(ops0["samples"]), len(ops0["routes"]), len(ops0["handoffs"]))
call("/api/check-serviceability", {
    "origin": origin, "originType": "home", "sampleTypeId": types["Amber"],
    "requestedAt": T(minutes=1), "earliestCollectionAt": T(minutes=15),
    "latestCollectionAt": T(hours=3), "deliveryDeadline": T(hours=10),
}, token=tok["req"], label="dry run repeated")
_, ops1 = call("/api/read-operations-state", {}, token=tok["disp"], label="state after dry run")
if (len(ops1["samples"]), len(ops1["routes"]), len(ops1["handoffs"])) != n_before:
    failures.append("serviceability check mutated state — it must be a dry run")

_, far = call("/api/check-serviceability", {
    "origin": {"latitude": 48.8566, "longitude": 2.3522}, "originType": "home",
    "sampleTypeId": types["Amber"], "requestedAt": T(minutes=1),
    "earliestCollectionAt": T(minutes=15), "latestCollectionAt": T(hours=3),
    "deliveryDeadline": T(hours=10),
}, token=tok["req"], label="origin outside coverage")
if far["serviceable"]:
    failures.append("an origin hundreds of km away was reported serviceable")
print("   far reason:", far["reason"])

_, tight = call("/api/check-serviceability", {
    "origin": origin, "originType": "home", "sampleTypeId": types["Amber"],
    "requestedAt": T(minutes=1), "earliestCollectionAt": T(minutes=15),
    "latestCollectionAt": T(hours=3), "deliveryDeadline": T(minutes=16),
}, token=tok["req"], label="deadline too tight")
if tight["serviceable"]:
    failures.append("an unreachable deadline was reported serviceable")
print("   tight reason:", tight["reason"])

_, snap = call("/api/read-serviceability-snapshot", {}, token=tok["req"],
               label="serviceability snapshot")
print("   version:", snap["version"], "status:", snap["status"],
      "regions:", len(snap["regions"]), "points:", snap["activeCollectionPointCount"])
if snap["status"] != "complete":
    failures.append(f"published snapshot is not complete: {snap['status']}")

print("\n[collection requests]")
base_req = {
    "origin": origin, "originType": "home", "sampleTypeId": types["Amber"],
    "requestedAt": T(minutes=1), "earliestCollectionAt": T(minutes=15),
    "latestCollectionAt": T(hours=3), "deliveryDeadline": T(hours=10),
    "containerType": "standard", "temperatureMinC": 15, "temperatureMaxC": 25,
}
_, r1 = call("/api/create-collection-request", dict(base_req, idempotencyKey=idem()),
             token=tok["req"], expect=201, label="create home request")
sample, journey = r1["sampleId"], r1.get("journeyId")
print("   sample:", sample[:8], "journey:", (journey or "-")[:8],
      "serviceability:", r1["serviceability"], "assignments:", len(r1["activeAssignmentIds"]))

k = idem()
_, ra = call("/api/create-collection-request", dict(base_req, idempotencyKey=k),
             token=tok["req"], expect=201, label="idempotent create (first)")
_, rb = call("/api/create-collection-request", dict(base_req, idempotencyKey=k),
             token=tok["req"], expect=201, label="idempotent create (replay)")
if ra["sampleId"] != rb["sampleId"]:
    failures.append("an idempotency key replay created a second sample")

call("/api/create-collection-request",
     dict(base_req, idempotencyKey=idem(), earliestCollectionAt=T(hours=4),
          latestCollectionAt=T(hours=1)),
     token=tok["req"], expect=400, label="reversed collection window rejected")
call("/api/create-collection-request",
     dict(base_req, idempotencyKey=idem(), deliveryDeadline=T(hours=-2)),
     token=tok["req"], expect=400, label="deadline in the past rejected")
call("/api/create-collection-request",
     dict(base_req, idempotencyKey=idem(), sampleTypeId=str(uuid.uuid4())),
     token=tok["req"], expect=404, label="unknown sample type rejected")

print("\n[fair offering and acceptance]")


def offers(work, kind):
    out = []
    for bucket in ("pending", "inProgress"):
        for it in work.get(bucket, []):
            if it.get("kind") == kind and it.get("status") == "offered":
                out.append(it["assignmentId"])
    return out


_, w1 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col"],
             label="collector 1 work")
_, w2 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col2"],
             label="collector 2 work")
o1, o2 = offers(w1, "collection"), offers(w2, "collection")
shared = set(o1) & set(o2)
if shared:
    failures.append(f"assignment offered to two collectors at once: {shared}")
holder, other = ("col", "col2") if o1 else ("col2", "col")
coll_ids = o1 or o2
if not coll_ids:
    failures.append("no collection assignment was offered to a qualified collector")
    coll = None
else:
    coll = coll_ids[0]
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[other], expect=403, label="non-offeree cannot accept")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok["disp"], expect=403, label="dispatcher cannot accept worker offer")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=201, label="offeree accepts")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=409, label="second accept is a conflict")

print("\n[decline is not permanent exclusion]")
_, r_dec = call("/api/create-collection-request",
                dict(base_req, idempotencyKey=idem(), sampleTypeId=types["Indigo"]),
                token=tok["req"], expect=201, label="request for decline flow")
dec_sample = r_dec["sampleId"]
dec_assignment = None
for key in ("col", "col2"):
    _, w = call("/api/list-role-work", {"role": "collection_professional"}, token=tok[key],
                label=f"work for decline ({key})")
    for aid in offers(w, "collection"):
        if aid != coll:
            dec_assignment, dec_key = aid, key
            break
    if dec_assignment:
        break
if dec_assignment:
    _, d = call("/api/decline-assignment", {
        "assignmentId": dec_assignment, "reason": "already committed",
        "idempotencyKey": idem(),
    }, token=tok[dec_key], expect=201, label="worker declines")
    print("   re-offered to:", (d.get("reofferedTo") or "-")[:8])
    if d.get("reofferedTo") == uid[dec_key]:
        failures.append("a declined assignment was re-offered to the same worker immediately")
    _, w_again = call("/api/list-role-work", {"role": "collection_professional"},
                      token=tok[dec_key], label="decliner still receives work")

print("\n[collection and sealing]")
if coll:
    call("/api/record-worker-location", {
        "assignmentId": coll, "coordinate": origin, "sequence": 1,
        "recordedAt": iso(datetime.now(timezone.utc)),
    }, token=tok[holder], expect=201, label="collector records location")
    call("/api/collect-and-seal-sample", {
        "sampleId": sample, "assignmentId": coll, "collectedAt": T(minutes=20),
        "containerType": "standard", "observedTemperatureC": 20, "idempotencyKey": idem(),
    }, token=tok[other], expect=403, label="other collector cannot seal")
    _, sealed = call("/api/collect-and-seal-sample", {
        "sampleId": sample, "assignmentId": coll, "collectedAt": T(minutes=20),
        "containerType": "standard", "observedTemperatureC": 20, "idempotencyKey": idem(),
    }, token=tok[holder], expect=201, label="collector seals sample")
