print("\n[fair offering and acceptance]")


def offers(work, kind):
    out = []
    for bucket in ("pending", "inProgress"):
        for it in work.get(bucket, []):
            if it.get("kind") == kind and it.get("status") == "offered":
                out.append(it["assignmentId"])
    return out


_, w1 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col"],
             label="collector 1 work")
_, w2 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col2"],
             label="collector 2 work")
o1, o2 = offers(w1, "collection"), offers(w2, "collection")
shared = set(o1) & set(o2)
if shared:
    failures.append(f"assignment offered to two collectors at once: {shared}")
holder, other = ("col", "col2") if o1 else ("col2", "col")
coll_ids = o1 or o2
if not coll_ids:
    failures.append("no collection assignment was offered to a qualified collector")
    coll = None
else:
    coll = coll_ids[0]
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[other], expect=403, label="non-offeree cannot accept")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok["disp"], expect=403, label="dispatcher cannot accept worker offer")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=201, label="offeree accepts")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=409, label="second accept is a conflict")

print("\n[decline is not permanent exclusion]")
_, r_dec = call("/api/create-collection-request",
                dict(base_req, idempotencyKey=idem(), sampleTypeId=types["Indigo"]),
                token=tok["req"], expect=201, label="request for decline flow")
dec_sample = r_dec["sampleId"]
dec_assignment = None
for key in ("col", "col2"):
    _, w = call("/api/list-role-work", {"role": "collection_professional"}, token=tok[key],
                label=f"work for decline ({key})")
    for aid in offers(w, "collection"):
        if aid != coll:
            dec_assignment, dec_key = aid, key
            break
    if dec_assignment:
        break
if dec_assignment:
    _, d = call("/api/decline-assignment", {
        "assignmentId": dec_assignment, "reason": "already committed",
        "idempotencyKey": idem(),
    }, token=tok[dec_key], expect=201, label="worker declines")
    print("   re-offered to:", (d.get("reofferedTo") or "-")[:8])
    if d.get("reofferedTo") == uid[dec_key]:
        failures.append("a declined assignment was re-offered to the same worker immediately")
    _, w_again = call("/api/list-role-work", {"role": "collection_professional"},
                      token=tok[dec_key], label="decliner still receives work")

