    call("/api/collect-and-seal-sample", {
        "sampleId": sample, "assignmentId": coll,
        "collectedAt": iso(now - timedelta(hours=5)),
        "containerType": "standard", "observedTemperatureC": 20, "idempotencyKey": idem(),
