print("\n[transport, custody and handoff]")
t_assign = t_key = None
for key in ("cour", "cour2"):
    _, dw = call("/api/list-role-work", {"role": "delivery_partner"}, token=tok[key],
                 label=f"courier work ({key})")
    got = offers(dw, "transport")
    if got:
        t_assign, t_key = got[0], key
        break
if not t_assign:
    failures.append("no transport assignment was offered to any courier")
elif coll:
    call("/api/accept-assignment", {"assignmentId": t_assign, "idempotencyKey": idem()},
         token=tok[t_key], expect=201, label="courier accepts leg")
    _, ho = call("/api/initiate-handoff", {
        "sampleId": sample, "fromAssignmentId": coll, "toAssignmentId": t_assign,
        "receiverId": uid[t_key], "initiatedAt": iso(datetime.now(timezone.utc)),
        "idempotencyKey": idem(),
    }, token=tok[holder], expect=201, label="sender initiates handoff")
    hid = ho["handoffId"]
    print("   handoff:", hid[:8], "status:", ho["status"], "holder:", ho["currentHolderId"][:8])
    if ho["currentHolderId"] != uid[holder]:
        failures.append("custody changed as soon as the handoff was initiated")

    _, hc1 = call("/api/confirm-handoff", {
        "handoffId": hid, "confirmationSide": "sender",
        "confirmedAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
    }, token=tok[holder], expect=201, label="sender confirms")
    if hc1["currentHolderId"] != uid[holder]:
        failures.append("custody moved before the receiver confirmed")
    _, hc2 = call("/api/confirm-handoff", {
        "handoffId": hid, "confirmationSide": "receiver",
        "confirmedAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
    }, token=tok[t_key], expect=201, label="receiver confirms")
    print("   after both:", hc2["status"], "holder:", hc2["currentHolderId"][:8])
    if hc2["currentHolderId"] != uid[t_key]:
        failures.append("receiver did not become custodian after both confirmations")
    _, hc3 = call("/api/confirm-handoff", {
        "handoffId": hid, "confirmationSide": "receiver",
        "confirmedAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
    }, token=tok[t_key], expect=201, label="repeat confirm is idempotent")
    if hc3["currentHolderId"] != uid[t_key]:
        failures.append("a repeated confirmation changed custody again")

    call("/api/update-assignment-progress", {
        "assignmentId": t_assign, "status": "in_progress",
        "occurredAt": iso(datetime.now(timezone.utc)), "idempotencyKey": idem(),
    }, token=tok[t_key], expect=201, label="courier reports progress")
    call("/api/record-worker-location", {
        "assignmentId": t_assign, "coordinate": {"latitude": 52.392, "longitude": 4.905},
        "sequence": 2, "recordedAt": iso(datetime.now(timezone.utc)),
    }, token=tok[t_key], expect=201, label="courier records location")
    _, bad = call("/api/record-handling-checkpoint", {
        "sampleId": sample, "assignmentId": t_assign, "containerType": "standard",
        "observedTemperatureC": 91, "recordedAt": iso(datetime.now(timezone.utc)),
        "idempotencyKey": idem(),
    }, token=tok[t_key], expect=201, label="out-of-range checkpoint")
    if bad["compliant"]:
        failures.append("a temperature far outside range was reported compliant")
    if bad["sampleStatus"] != "exception":
        failures.append(f"out-of-range checkpoint did not flag an exception "
                        f"(status={bad['sampleStatus']})")

