print("\n[capacity is never overbooked]")
_, opsc = call("/api/read-operations-state", {}, token=tok["disp"], label="capacity snapshot")
for loc in opsc["locations"]:
    cap = loc.get("capacity")
    if not cap:
        continue
    if cap["reservedUnits"] > cap["capacityUnits"]:
        failures.append(f"location {loc['name']} is overbooked: "
                        f"{cap['reservedUnits']}/{cap['capacityUnits']}")
    if cap["cooledReservedUnits"] > cap["cooledCapacityUnits"]:
        failures.append(f"location {loc['name']} cooled pool overbooked")
    if cap["availableUnits"] != cap["capacityUnits"] - cap["reservedUnits"]:
        failures.append(f"location {loc['name']} available units are inconsistent")
for cn in opsc["connections"]:
    cap = cn.get("capacity")
    if cap and cap["reservedUnits"] > cap["capacityUnits"]:
        failures.append("a connection capacity pool is overbooked")

