"""Drive a running server through a full scenario and validate every response
body against the pinned schemas in contracts/openapi.contract.json.

Usage: python3 backend/testdata/contract_check.py [base-url]
"""
import copy
import json
import sys
import urllib.error
import urllib.request
import uuid
from datetime import datetime, timedelta, timezone

from jsonschema import Draft202012Validator

BASE = (sys.argv[1] if len(sys.argv) > 1 else "http://127.0.0.1:18082").rstrip("/")
CONTRACT = json.load(open("/workspace/contracts/openapi.contract.json"))

failures = []
validated = 0
covered = {}


def resolve(method, path):
    for tmpl, item in CONTRACT["paths"].items():
        op = item.get(method.lower())
        if not op:
            continue
        t = tmpl.strip("/").split("/")
        p = path.split("?")[0].strip("/").split("/")
        if len(t) == len(p) and all(a.startswith("{") or a == b for a, b in zip(t, p)):
            return tmpl, op
    return None, None


def check_schema(op, tmpl, method, status, payload, label):
    global validated
    responses = op.get("responses", {})
    spec = responses.get(str(status))
    if spec is None:
        failures.append(f"{label}: HTTP {status} is not declared for {method} {tmpl} "
                        f"(contract declares {sorted(responses)})")
        return
    schema = spec.get("content", {}).get("application/json", {}).get("schema")
    if schema is None:
        return
    full = copy.deepcopy(schema)
    full["components"] = CONTRACT["components"]
    errs = sorted(Draft202012Validator(full).iter_errors(payload), key=lambda e: e.json_path)
    if errs:
        e = errs[0]
        failures.append(f"{label}: HTTP {status} body violates contract at "
                        f"{e.json_path}: {e.message[:200]}")
    else:
        validated += 1


def call(path, body=None, token=None, method=None, expect=200, label=None):
    data = json.dumps(body).encode() if body is not None else None
    headers = {}
    if data:
        headers["Content-Type"] = "application/json"
    if token:
        headers["Authorization"] = "Bearer " + token
    method = method or ("POST" if body is not None else "GET")
    req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req) as r:
            status, raw = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, raw = e.code, e.read()
    try:
        payload = json.loads(raw or b"{}")
    except Exception:
        payload = {"_raw": raw[:200].decode(errors="replace")}

    label = label or f"{method} {path}"
    tmpl, op = resolve(method, path)
    if op is None:
        failures.append(f"{label}: {method} {path} is not in the contract")
    else:
        covered.setdefault(op["operationId"], set()).add(status)
        check_schema(op, tmpl, method, status, payload, label)

    if status != expect:
        failures.append(f"{label}: expected HTTP {expect} got {status} -> "
                        f"{json.dumps(payload)[:300]}")
        print(f"  FAIL {label}: {status} {json.dumps(payload)[:200]}")
    else:
        print(f"  ok   {label}: {status}")
    return status, payload.get("data", payload)


def idem():
    return str(uuid.uuid4())


def iso(dt):
    return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


now = datetime.now(timezone.utc)
run = uuid.uuid4().hex[:8]
T = lambda **kw: iso(now + timedelta(**kw))

print("\n[authentication]")
call("/api/authenticate-user", {"username": "admin", "password": "WRONG"}, expect=401,
     label="wrong password rejected")
call("/api/authenticate-user", {"username": f"ghost-{run}", "password": "x"}, expect=401,
     label="unknown user rejected")
_, a = call("/api/authenticate-user", {"username": "admin", "password": "secret123"},
            label="admin signs in")
admin = a["sessionToken"]
if a["activeRole"] != "administrator":
    failures.append(f"single-role admin should start as administrator, got {a['activeRole']}")
call("/api/read-operations-state", {}, expect=401, label="no token rejected")
call("/api/read-operations-state", {}, token="not-a-token", expect=401,
     label="bad token rejected")

print("\n[bootstrap and default sample types]")
_, boot = call("/api/ui/bootstrap", token=admin, label="ui bootstrap")
ref = json.loads(urllib.request.urlopen(urllib.request.Request(
    BASE + "/ui-reference", headers={"Authorization": "Bearer " + admin})).read())["data"]
types = {t["name"]: t["sampleTypeId"] for t in ref["sampleTypes"]}
# Each type has its own container/temperature rules, so a request body has to be
# built from the type it names rather than from one hardcoded set of attributes.
type_attrs = {
    t["sampleTypeId"]: {
        "containerType": t["containerType"],
        "temperatureMinC": t["temperatureMinC"],
        "temperatureMaxC": t["temperatureMaxC"],
    }
    for t in ref["sampleTypes"]
}
qual_codes = {t["name"]: t.get("requiredQualification", "") for t in ref["sampleTypes"]}
missing = [n for n in ("Amber", "Indigo", "Frost", "Pulse") if n not in types]
if missing:
    failures.append(f"default sample types not available: {missing}")
print("   sample types:", sorted(types))

print("\n[network structure]")
_, lab = call("/api/create-location", {
    "name": f"Lab {run}", "coordinate": {"latitude": 52.3702, "longitude": 4.8952},
    "coverageKm": 4.5, "handlingMinutes": 15, "active": True,
    "functions": ["laboratory", "hub", "transfer_point"],
}, token=admin, expect=201, label="create laboratory")
lab_id = lab["locationId"]
_, hub = call("/api/create-location", {
    "name": f"Hub {run}", "coordinate": {"latitude": 52.3850, "longitude": 4.9000},
    "coverageKm": 4, "handlingMinutes": 10, "active": True,
    "functions": ["hub", "transfer_point"],
}, token=admin, expect=201, label="create hub")
hub_id = hub["locationId"]
_, cp = call("/api/create-location", {
    "name": f"Collection {run}", "coordinate": {"latitude": 52.4000, "longitude": 4.9100},
    "coverageKm": 5, "handlingMinutes": 8, "active": True,
    "functions": ["collection_point", "transfer_point"],
}, token=admin, expect=201, label="create collection point")
cp_id = cp["locationId"]

call("/api/create-location", {
    "name": "Too much coverage", "coordinate": {"latitude": 52.4, "longitude": 4.9},
