    "requestedAt": T(minutes=1), "earliestCollectionAt": T(minutes=15),
    "latestCollectionAt": T(hours=3), "deliveryDeadline": T(hours=10),
}, token=tok["req"], label="origin inside coverage")
print("   serviceable:", svc["serviceable"], "reason:", svc["reason"],
      "version:", svc["serviceabilityVersion"])
if not svc["serviceable"]:
    failures.append(f"origin within 5km reported unserviceable: {svc['reason']}")

_, ops0 = call("/api/read-operations-state", {}, token=tok["disp"], label="state before dry run")
n_before = (len(ops0["samples"]), len(ops0["routes"]), len(ops0["handoffs"]))
call("/api/check-serviceability", {
    "origin": origin, "originType": "home", "sampleTypeId": types["Amber"],
    "requestedAt": T(minutes=1), "earliestCollectionAt": T(minutes=15),
    "latestCollectionAt": T(hours=3), "deliveryDeadline": T(hours=10),
}, token=tok["req"], label="dry run repeated")
_, ops1 = call("/api/read-operations-state", {}, token=tok["disp"], label="state after dry run")
if (len(ops1["samples"]), len(ops1["routes"]), len(ops1["handoffs"])) != n_before:
    failures.append("serviceability check mutated state — it must be a dry run")

_, far = call("/api/check-serviceability", {
    "origin": {"latitude": 48.8566, "longitude": 2.3522}, "originType": "home",
