}


def req_for(type_name, **overrides):
    """A collection request for a named type, with that type's handling rules."""
    type_id = types[type_name]
    return dict(base_req, sampleTypeId=type_id, **type_attrs[type_id],
                idempotencyKey=idem(), **overrides)


