    "temperatureMinC": 2, "temperatureMaxC": 30,
}, token=admin, expect=201, label="update sample type")

print("\n[users, roles and certifications]")
# A collector is only eligible when it holds the qualification code the sample
# type names, so the codes come from the type definitions, not from the name.
all_quals = [qual_codes[n] for n in ("Amber", "Indigo", "Frost", "Pulse") if qual_codes.get(n)]
people = {
