             label="collector 1 work")
_, w2 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col2"],
             label="collector 2 work")
o1 = offers(w1, "collection", sample)
o2 = offers(w2, "collection", sample)
shared = set(o1) & set(o2)
if shared:
    failures.append(f"assignment offered to two collectors at once: {shared}")
holder, other = ("col", "col2") if o1 else ("col2", "col")
coll_ids = o1 or o2
if not coll_ids:
    failures.append("no collection assignment was offered to a qualified collector")
    coll = None
else:
    coll = coll_ids[0]
    # The contract allows either a 403 (ineligible) or a 409 (offered elsewhere)
    # for someone who is not the offeree.
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[other], expect=(403, 409), label="non-offeree cannot accept")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok["disp"], expect=(403, 409), label="dispatcher cannot accept worker offer")
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=201, label="offeree accepts")
    # Re-accepting one's own accepted assignment is idempotent, not a conflict.
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=201, label="re-accept by the same worker is idempotent")

