call("/api/create-location", {
    "name": "Bad coordinate", "coordinate": {"latitude": 999, "longitude": 4.9},
    "coverageKm": 3, "handlingMinutes": 5, "active": True, "functions": ["collection_point"],
}, token=admin, expect=400, label="invalid coordinate rejected")
call("/api/create-location", {
    "name": "No functions", "coordinate": {"latitude": 52.4, "longitude": 4.9},
    "coverageKm": 3, "handlingMinutes": 5, "active": True, "functions": [],
}, token=admin, expect=400, label="location with no function rejected")

conns = {}
for frm, to, mins in ((cp_id, hub_id, 18), (hub_id, lab_id, 22), (cp_id, lab_id, 35)):
    _, c = call("/api/create-connection", {
