def offers(work, kind, sample_id=None):
    """Offered assignment ids of a kind, optionally only those for one sample."""
    out = []
    for bucket in ("pending", "inProgress"):
        for it in work.get(bucket, []):
            if it.get("kind") != kind or it.get("status") != "offered":
                continue
            if sample_id and it.get("sampleId") != sample_id:
                continue
            out.append(it["assignmentId"])
    return out


