    # Re-accepting one's own accepted assignment is idempotent, not a conflict.
    call("/api/accept-assignment", {"assignmentId": coll, "idempotencyKey": idem()},
         token=tok[holder], expect=201, label="re-accept by the same worker is idempotent")

