observation.old_content:
package core

import (
	"context"
	"sort"
	"time"

	"labdelivery/internal/domain"
)

// eligibleWorker reports whether a worker may be offered the given assignment.
//
// Eligibility covers the role, the qualification and certification a sample type demands,
// the worker's availability and personal capacity, and — for node and laboratory work —
// being assigned to that specific site.
func (e *Engine) eligibleWorker(worker *domain.User, a *domain.Assignment, now time.Time) bool {
	if !worker.Active || !worker.Available {
		return false
	}
	if !worker.HasRole(a.RequiredRole) {
		return false
	}
	if a.RequiredQualification != "" {
		if !worker.HasQualification(a.RequiredQualification) {
			return false
		}
		if !worker.HasActiveCertification(a.RequiredQualification, now) {
			return false
		}
	}
	switch a.Kind {
	case domain.AssignmentNode:
		if a.NodeID == "" || worker.AssignedLocationID != a.NodeID {
			return false
		}
	case domain.AssignmentLaboratory:
		if a.LaboratoryID == "" || worker.AssignedLocationID != a.LaboratoryID {
			return false
		}
	}
	if worker.CapacityUnits > 0 && e.activeAssignmentCount(worker.UserID) >= worker.CapacityUnits {
		return false
	}
	return true
}

// candidateWorkers ranks eligible workers fairly: least loaded first, then least recently
// assigned. Workers who already declined this assignment and workers inside a decline
// penalty window are pushed to the back rather than excluded.
func (e *Engine) candidateWorkers(a *domain.Assignment, now time.Time) []*domain.User {
	var primary, deferred []*domain.User
	for _, worker := range e.users {
		if !e.eligibleWorker(worker, a, now) {
			continue
		}
		if containsString(a.DeclinedByIDs, worker.UserID) {
			continue
		}
		if worker.DeclinePenaltyUntil != nil && worker.DeclinePenaltyUntil.After(now) {
			deferred = append(deferred, worker)
			continue
		}
		primary = append(primary, worker)
	}
	e.sortByFairness(primary)
	e.sortByFairness(deferred)
	return append(primary, deferred...)
}

func (e *Engine) sortByFairness(workers []*domain.User) {
	load := map[string]int{}
	for _, w := range workers {
		load[w.UserID] = e.activeAssignmentCount(w.UserID)
	}
	sort.Slice(workers, func(i, j int) bool {
		a, b := workers[i], workers[j]
		if load[a.UserID] != load[b.UserID] {
			return load[a.UserID] < load[b.UserID]
		}
		if a.TotalAssignments != b.TotalAssignments {
			return a.TotalAssignments < b.TotalAssignments
		}
		at, bt := a.LastAssignedAt, b.LastAssignedAt
		switch {
		case at == nil && bt != nil:
			return true
		case at != nil && bt == nil:
			return false
		case at != nil && bt != nil && !at.Equal(*bt):
			return at.Before(*bt)
		}
		return a.UserID < b.UserID
	})
}

// offerAssignment offers the work to the next eligible worker, one at a time.
//
// When nobody is eligible the assignment starts (or keeps) its no-worker clock; once the
// grace period passes with still nobody available the sample is flagged with a
// no-qualified-worker exception, which is distinct from a missed deadline.
func (e *Engine) offerAssignment(t *txn, a *domain.Assignment) *domain.User {
	candidates := e.candidateWorkers(a, t.now)
	if len(candidates) == 0 {
		if a.NoWorkerSince == nil {
			a.NoWorkerSince = timePtr(t.now)
		}
		a.Status = domain.AssignStatusPending
		a.OfferedToID = ""
		a.OfferExpiresAt = nil
		t.saveAssignment(a)
		t.audit("offer_assignment", "assignment", a.AssignmentID, false, map[string]any{
			"reason":                "no_eligible_worker",
			"requiredRole":          string(a.RequiredRole),
			"requiredQualification": a.RequiredQualification,
		}, a.AssignmentID, a.SampleID, a.JourneyID)
		if t.now.Sub(*a.NoWorkerSince) >= e.cfg.NoWorkerGrace {
			e.flagNoQualifiedWorker(t, a)
		}
		return nil
	}

	worker := candidates[0]
	a.Status = domain.AssignStatusOffered
	a.OfferedToID = worker.UserID
	a.OfferExpiresAt = timePtr(t.now.Add(e.cfg.OfferTimeout))
	a.OfferAttempts++
	a.NoWorkerSince = nil
	t.saveAssignment(a)

	t.audit("offer_assignment", "assignment", a.AssignmentID, true, map[string]any{
		"offeredTo":    worker.UserID,
		"kind":         a.Kind,
		"requiredRole": string(a.RequiredRole),
		"attempt":      a.OfferAttempts,
		"expiresAt":    formatTime(*a.OfferExpiresAt),
	}, a.AssignmentID, a.SampleID, a.JourneyID, worker.UserID)
	t.event("assignment_offered", "assignment", a.AssignmentID, map[string]any{
		"assignmentId": a.AssignmentID,
		"kind":         a.Kind,
		"sampleId":     a.SampleID,
		"offerExpires": formatTime(*a.OfferExpiresAt),
	}, append(operationsAudience(), userAudience(worker.UserID), roleAudience(a.RequiredRole))...)
	return worker
}

// flagNoQualifiedWorker marks the sample with a dedicated no-worker exception.
func (e *Engine) flagNoQualifiedWorker(t *txn, a *domain.Assignment) {
	for _, sampleID := range a.Samples() {
		sample := e.samples[sampleID]
		if sample == nil || sample.Terminal() || sample.Status == domain.SampleStatusException {
			continue
		}
		sample.Status = domain.SampleStatusException
		sample.Exception = &domain.ExceptionInfo{
			Reason:     "no_qualified_worker",
			Kind:       "no_qualified_worker",
			Detail:     "no qualified worker became available for assignment " + a.AssignmentID,
			OccurredAt: t.now,
		}
		t.saveSample(sample)
		t.audit("sample_exception", "sample", sample.SampleID, true, map[string]any{
			"reason":       "no_qualified_worker",
			"assignmentId": a.AssignmentID,
			"requiredRole": string(a.RequiredRole),
		}, sample.SampleID, a.AssignmentID, sample.ActiveJourneyID)
		t.event("sample_exception", "sample", sample.SampleID, map[string]any{
			"reason": "no_qualified_worker", "assignmentId": a.AssignmentID,
		}, append(operationsAudience(), userAudience(sample.RequesterID))...)
	}
}

// expireStaleOffers treats offers with no response inside the timeout as declines and
// re-offers them to the next eligible worker.
func (e *Engine) expireStaleOffers(ctx context.Context) {
	e.mu.Lock()
	var stale []string
	now := e.now()
	for id, a := range e.assignments {
		if a.Status == domain.AssignStatusOffered && a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(now) {
			stale = append(stale, id)
		}
		if a.Status == domain.AssignStatusPending && a.NoWorkerSince != nil &&
			now.Sub(*a.NoWorkerSince) >= e.cfg.NoWorkerGrace {
			stale = append(stale, id)
		}
	}
	e.mu.Unlock()
	if len(stale) == 0 {
		return
	}
	sort.Strings(stale)
	for _, id := range stale {
		_, _, _ = e.mutate(ctx, "expire_offer:"+id, "", "", "", func(t *txn) (any, int, error) {
			a := e.assignments[id]
			if a == nil || a.Terminal() {
				return map[string]any{"skipped": true}, 200, nil
			}
			if a.Status == domain.AssignStatusOffered {
				if a.OfferExpiresAt == nil || a.OfferExpiresAt.After(t.now) {
					return map[string]any{"skipped": true}, 200, nil
				}
				declined := a.OfferedToID
				a.DeclinedByIDs = appendUnique(a.DeclinedByIDs, declined)
				a.Status = domain.AssignStatusPending
				a.OfferedToID = ""
				a.OfferExpiresAt = nil
				t.saveAssignment(a)
				t.audit("offer_timed_out", "assignment", a.AssignmentID, true, map[string]any{
					"workerId": declined, "treatedAs": "declined",
				}, a.AssignmentID, a.SampleID, a.JourneyID, declined)
				e.offerAssignment(t, a)
				return map[string]any{"reoffered": a.OfferedToID}, 200, nil
			}
			if a.Status == domain.AssignStatusPending && a.NoWorkerSince != nil &&
				t.now.Sub(*a.NoWorkerSince) >= e.cfg.NoWorkerGrace {
				if e.offerAssignment(t, a) == nil {
					return map[string]any{"exception": true}, 200, nil
				}
			}
			return map[string]any{}, 200, nil
		})
	}
}

// AcceptAssignment records a worker accepting the assignment offered to them.
func (e *Engine) AcceptAssignment(ctx context.Context, p *Principal, assignmentID, idemKey, idemHash string) (any, int, error) {
	if p.ActiveRole == "" {
		return nil, 0, errRoleNotSelected()
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	return e.mutate(ctx, "accept_assignment", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		a := e.assignments[assignmentID]
		if a == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		if a.Terminal() {
			return nil, 0, errConflict("assignment_inactive", "assignment is no longer active")
		}
		if a.Status == domain.AssignStatusAccepted || a.InProgress() {
			if a.WorkerID == p.User.UserID {
				return map[string]any{
					"assignmentId": a.AssignmentID,
					"workerId":     a.WorkerID,
					"status":       "accepted",
				}, 201, nil
			}
			return nil, 0, errConflict("assignment_taken", "assignment was already accepted by another worker")
		}
		if a.Status != domain.AssignStatusOffered || a.OfferedToID == "" {
			return nil, 0, errConflict("offer_not_available", "assignment is not currently offered")
		}
		if a.OfferedToID != p.User.UserID {
			t.audit("permission_check", "assignment", a.AssignmentID, false, map[string]any{
				"action": "accept_assignment", "reason": "offered_to_other_worker",
			}, a.AssignmentID, p.User.UserID)
			return nil, 0, errConflict("offer_not_offered", "this assignment was offered to another worker")
		}
		if a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(t.now) {
			return nil, 0, errConflict("offer_not_available", "the offer has expired")
		}
		if p.ActiveRole != a.RequiredRole {
			return nil, 0, errForbiddenCode("ineligible_worker",
				"this assignment requires the "+string(a.RequiredRole)+" role")
		}
		worker := e.users[p.User.UserID]
		if !worker.Available {
			return nil, 0, errConflict("worker_unavailable", "worker is currently unavailable")
		}
		if !e.eligibleWorker(worker, a, t.now) {
			return nil, 0, errForbiddenCode("ineligible_worker", "worker is not eligible for this assignment")
		}

		a.Status = domain.AssignStatusAccepted
		a.WorkerID = worker.UserID
		a.OfferedToID = ""
		a.OfferExpiresAt = nil
		t.saveAssignment(a)

		worker.TotalAssignments++
		worker.LastAssignedAt = timePtr(t.now)
		t.saveUser(worker)

		e.markSamplesAssigned(t, a)

		t.audit("accept_assignment", "assignment", a.AssignmentID, true, map[string]any{
			"workerId": worker.UserID, "kind": a.Kind, "status": a.Status,
		}, a.AssignmentID, a.SampleID, a.JourneyID, worker.UserID)
		t.event("assignment_accepted", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "workerId": worker.UserID, "status": a.Status,
		}, append(operationsAudience(), userAudience(worker.UserID))...)

		return map[string]any{
			"assignmentId": a.AssignmentID,
			"workerId":     worker.UserID,
			"status":       "accepted",
		}, 201, nil
	})
}

func (e *Engine) markSamplesAssigned(t *txn, a *domain.Assignment) {
	for _, sampleID := range a.Samples() {
		sample := e.samples[sampleID]
		if sample == nil || sample.Terminal() {
			continue
		}
		if sample.Status == domain.SampleStatusRequested {
			sample.Status = domain.SampleStatusAssigned
			t.saveSample(sample)
			t.audit("sample_assigned", "sample", sample.SampleID, true, map[string]any{
				"assignmentId": a.AssignmentID, "status": sample.Status,
			}, sample.SampleID, a.AssignmentID, sample.ActiveJourneyID)
		}
	}
}

// DeclineAssignment records a decline and re-offers the work to the next eligible worker.
func (e *Engine) DeclineAssignment(ctx context.Context, p *Principal, assignmentID, reason string,
	declinedAt *time.Time, idemKey, idemHash string) (any, int, error) {
	if p.ActiveRole == "" {
		return nil, 0, errRoleNotSelected()
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	return e.mutate(ctx, "decline_assignment", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		a := e.assignments[assignmentID]
		if a == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		if a.Terminal() {
			return nil, 0, errConflict("offer_not_available", "assignment is no longer active")
		}
		if a.Status != domain.AssignStatusOffered || a.OfferedToID != p.User.UserID {
			return nil, 0, errConflict("offer_not_available", "no open offer for this worker")
		}
		at := t.now
		if declinedAt != nil {
			at = *declinedAt
		}

		worker := e.users[p.User.UserID]
		a.DeclinedByIDs = appendUnique(a.DeclinedByIDs, worker.UserID)
		a.Status = domain.AssignStatusPending
		a.OfferedToID = ""
		a.OfferExpiresAt = nil
		t.saveAssignment(a)

		// Repeated declines lower priority for a limited time but never exclude permanently.
		worker.DeclineCount++
		if worker.DeclineCount >= 2 {
