}
qual_codes = {t["name"]: t.get("requiredQualification", "") for t in ref["sampleTypes"]}
missing = [n for n in ("Amber", "Indigo", "Frost", "Pulse") if n not in types]
if missing:
    failures.append(f"default sample types not available: {missing}")
print("   sample types:", sorted(types))

print("\n[network structure]")
_, lab = call("/api/create-location", {
    "name": f"Lab {run}", "coordinate": {"latitude": 52.3702, "longitude": 4.8952},
    "coverageKm": 4.5, "handlingMinutes": 15, "active": True,
    "functions": ["laboratory", "hub", "transfer_point"],
}, token=admin, expect=201, label="create laboratory")
lab_id = lab["locationId"]
