    conns[(frm, to)] = c["connectionId"]

for rid in (cp_id, hub_id, lab_id, conns[(cp_id, hub_id)], conns[(hub_id, lab_id)],
            conns[(cp_id, lab_id)]):
    call("/api/configure-capacity", {
        "resourceId": rid, "capacityUnits": 40, "cooledCapacityUnits": 20,
    }, token=admin, label=f"capacity {rid[:6]}")

for st in types.values():
    call("/api/configure-laboratory-acceptance", {
        "laboratoryId": lab_id, "sampleTypeId": st, "accepts": True,
    }, token=admin, label=f"lab accepts {st[:6]}")

print("\n[sample type administration]")
_, nt = call("/api/create-sample-type", {
    "name": f"Custom-{run}", "containerType": "standard", "temperatureMinC": 2,
    "temperatureMaxC": 25, "qualifiedCollectorRequired": False,
    "requiresCooledRoute": False, "batchingAllowed": True,
}, token=admin, expect=201, label="create sample type")
call("/api/update-sample-type", {
    "sampleTypeId": nt["sampleTypeId"], "containerType": "standard",
    "temperatureMinC": 2, "temperatureMaxC": 30,
}, token=admin, expect=201, label="update sample type")

print("\n[users, roles and certifications]")
# Workers left behind by earlier runs are still eligible and would win offers,
# making this run's assertions depend on leftover state. Park them first so every
# offer below can only reach the workers this run creates.
_, pre_state = call("/api/read-operations-state", {}, token=admin,
                    label="state before fixtures")
leftover = [w["workerId"] for w in pre_state["workers"] if w["available"]]
for wid in leftover:
    call("/api/set-worker-availability",
         {"workerId": wid, "available": False, "capacityUnits": 0},
         token=admin, expect=200, label="park leftover worker", quiet=True)
print(f"   parked {len(leftover)} leftover workers")
# A collector is only eligible when it holds the qualification code the sample
# type names, so the codes come from the type definitions, not from the name.
all_quals = [qual_codes[n] for n in ("Amber", "Indigo", "Frost", "Pulse") if qual_codes.get(n)]
people = {
    "req":  (["requester"], [], {}),
    "col":  (["collection_professional"], all_quals, {}),
    "col2": (["collection_professional"], all_quals, {}),
    "cour": (["delivery_partner"], [], {}),
    "cour2": (["delivery_partner"], [], {}),
    "node": (["node_handler"], [], {"assignedLocationId": cp_id}),
    "hubh": (["node_handler"], [], {"assignedLocationId": hub_id}),
    "lab":  (["laboratory_team"], [], {"assignedLocationId": lab_id}),
    "disp": (["dispatcher", "requester"], [], {}),
}
uid, tok = {}, {}
for key, (roles, certs, extra) in people.items():
    body = {"username": f"{key}-{run}", "initialPassword": "Passw0rd!",
            "fullName": key.title(), "roles": roles, "active": True,
            "certifications": [{"code": c, "active": True} for c in certs],
            "qualifications": certs}
    body.update(extra)
    _, u = call("/api/create-user", body, token=admin, expect=201, label="create " + key)
    uid[key] = u["userId"]
    _, s = call("/api/authenticate-user",
                {"username": f"{key}-{run}", "password": "Passw0rd!"}, label="sign in " + key)
    tok[key] = s["sessionToken"]

call("/api/create-user", {
