        for it in work.get(bucket, []):
            if it.get("kind") != kind or it.get("status") != "offered":
                continue
            if sample_id and it.get("sampleId") != sample_id:
                continue
            out.append(it["assignmentId"])
    return out


_, w1 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col"],
             label="collector 1 work")
_, w2 = call("/api/list-role-work", {"role": "collection_professional"}, token=tok["col2"],
             label="collector 2 work")
