package core

import (
	"sort"
	"strings"
	"time"

	"labdelivery/internal/domain"
)

// TimelineEntry is one ordered status-history record exposed to clients.
type TimelineEntry struct {
	EventID    int64          `json:"eventId"`
	Action     string         `json:"action"`
	ActorID    string         `json:"actorId"`
	Role       string         `json:"role"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Success    bool           `json:"success"`
	OccurredAt string         `json:"occurredAt"`
	Details    map[string]any `json:"details"`
}

// timeline returns the ordered history of a subject entity.
func (e *Engine) timeline(subject string) []TimelineEntry {
	records := e.timelines[subject]
	out := make([]TimelineEntry, 0, len(records))
	for _, r := range records {
		details := r.Details
		if details == nil {
			details = map[string]any{}
		}
		out = append(out, TimelineEntry{
			EventID:    r.EventID,
			Action:     r.Action,
			ActorID:    r.ActorID,
			Role:       r.Role,
			EntityType: r.EntityType,
			EntityID:   r.EntityID,
			Success:    r.Success,
			OccurredAt: formatTime(r.OccurredAt),
			Details:    details,
		})
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].EventID < out[j].EventID })
	return out
}

// locationStale reports whether a recorded position is older than the freshness window.
func (e *Engine) locationStale(recordedAt *time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return e.now().Sub(*recordedAt) > e.cfg.StaleAfter
}

// SampleStateView is the tracking projection of one sample.
type SampleStateView struct {
	SampleID                string             `json:"sampleId"`
	RequestID               string             `json:"requestId"`
	RequesterID             string             `json:"requesterId"`
	Origin                  domain.Coordinate  `json:"origin"`
	OriginType              string             `json:"originType"`
	RequestedAt             string             `json:"requestedAt"`
	DeliveryDeadline        string             `json:"deliveryDeadline"`
	SampleTypeID            string             `json:"sampleTypeId"`
	ContainerType           string             `json:"containerType"`
	TemperatureMinC         float64            `json:"temperatureMinC"`
	TemperatureMaxC         float64            `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string           `json:"incompatibleSampleTypes"`
	Serviceability          string             `json:"serviceability"`
	ActiveAssignmentIDs     []string           `json:"activeAssignmentIds"`
	State                   map[string]any     `json:"state"`
	Timeline                []TimelineEntry    `json:"timeline"`
	ActiveJourneyID         string             `json:"activeJourneyId,omitempty"`
	TargetLaboratoryID      string             `json:"targetLaboratoryId,omitempty"`
	LatestLocation          *domain.Coordinate `json:"latestLocation,omitempty"`
	LocationRecordedAt      string             `json:"locationRecordedAt,omitempty"`
	LocationStale           bool               `json:"locationStale"`
}

// ReadSampleState returns the current tracking state of a sample.
func (e *Engine) ReadSampleState(p *Principal, sampleID string) (any, error) {
	return e.read(func() (any, error) {
		if p.ActiveRole == "" {
			return nil, errRoleNotSelected()
		}
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, errNotFound("sample not found")
		}
		if err := e.authorizeSampleRead(p, sample); err != nil {
			return nil, err
		}
		return e.sampleStateView(sample), nil
	})
}

func (e *Engine) sampleStateView(sample *domain.Sample) *SampleStateView {
	view := &SampleStateView{
		SampleID:                sample.SampleID,
		RequestID:               sample.RequestID,
		RequesterID:             sample.RequesterID,
		Origin:                  sample.Origin,
		OriginType:              string(sample.OriginType),
		RequestedAt:             formatTime(sample.RequestedAt),
		DeliveryDeadline:        formatTime(sample.DeliveryDeadline),
		SampleTypeID:            sample.SampleTypeID,
		ContainerType:           sample.ContainerType,
		TemperatureMinC:         sample.TemperatureMinC,
		TemperatureMaxC:         sample.TemperatureMaxC,
		IncompatibleSampleTypes: stringsOrEmpty(sample.IncompatibleSampleTypes),
		Serviceability:          sample.Serviceability,
		ActiveAssignmentIDs:     e.activeAssignmentIDs(sample.SampleID),
		State:                   map[string]any{"status": sample.Status},
		Timeline:                e.timeline(sample.SampleID),
		ActiveJourneyID:         sample.ActiveJourneyID,
		TargetLaboratoryID:      sample.TargetLaboratoryID,
		LatestLocation:          sample.LatestLocation,
		LocationStale:           e.locationStale(sample.LocationRecordedAt),
	}
	if sample.Serviceability == "" {
		view.Serviceability = "serviceable"
	}
	if sample.LocationRecordedAt != nil {
		view.LocationRecordedAt = formatTime(*sample.LocationRecordedAt)
	}
	return view
}

// authorizeSampleRead applies role-based data access to one sample.
func (e *Engine) authorizeSampleRead(p *Principal, sample *domain.Sample) error {
	switch p.ActiveRole {
	case domain.RoleAdministrator, domain.RoleDispatcher:
		return nil
	case domain.RoleRequester:
		// A requester sees only their own requests.
		if sample.RequesterID != p.User.UserID {
			return errForbidden("this sample belongs to another requester")
		}
		return nil
	case domain.RoleCollectionProfession, domain.RoleDeliveryPartner,
		domain.RoleNodeHandler, domain.RoleLaboratoryTeam:
		// A worker sees samples they hold or are assigned to move.
		if sample.CurrentHolderID == p.User.UserID {
			return nil
		}
		for _, a := range e.assignments {
			if a.WorkerID != p.User.UserID && a.OfferedToID != p.User.UserID {
				continue
			}
			if containsString(a.Samples(), sample.SampleID) {
				return nil
			}
		}
		return errForbidden("this sample is not part of your work")
	}
	return errForbidden("the selected role may not read samples")
}

// SampleLifecycleView is the custody and replanning projection of a sample.
type SampleLifecycleView struct {
	SampleID                 string             `json:"sampleId"`
	Status                   string             `json:"status"`
	Sealed                   bool               `json:"sealed"`
	CompletedLegIDs          []string           `json:"completedLegIds"`
	ActiveReplacementPlanIDs []string           `json:"activeReplacementPlanIds"`
	Timeline                 []TimelineEntry    `json:"timeline"`
	ActiveJourneyID          string             `json:"activeJourneyId,omitempty"`
	CurrentHolderID          string             `json:"currentHolderId,omitempty"`
	ReceivedLaboratoryID     string             `json:"receivedLaboratoryId,omitempty"`
	Exception                map[string]any     `json:"exception,omitempty"`
	PendingHandoffID         string             `json:"pendingHandoffId,omitempty"`
	PendingHandoff           map[string]any     `json:"pendingHandoff,omitempty"`
	LatestLocation           *domain.Coordinate `json:"latestLocation,omitempty"`
	LocationRecordedAt       string             `json:"locationRecordedAt,omitempty"`
	LocationStale            bool               `json:"locationStale"`
}

// ReadSampleLifecycle returns custody, completion and replacement-plan state.
func (e *Engine) ReadSampleLifecycle(p *Principal, sampleID string) (any, error) {
	return e.read(func() (any, error) {
		if p.ActiveRole == "" {
			return nil, errRoleNotSelected()
		}
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, errNotFound("sample not found")
		}
		if err := e.authorizeSampleRead(p, sample); err != nil {
			return nil, err
		}
		view := &SampleLifecycleView{
			SampleID:                 sample.SampleID,
			Status:                   sample.Status,
			Sealed:                   sample.Sealed,
			CompletedLegIDs:          stringsOrEmpty(sample.CompletedLegIDs),
			ActiveReplacementPlanIDs: e.activeReplacementPlanIDs(sample),
			Timeline:                 e.timeline(sample.SampleID),
			ActiveJourneyID:          sample.ActiveJourneyID,
			CurrentHolderID:          sample.CurrentHolderID,
			ReceivedLaboratoryID:     sample.ReceivedLaboratoryID,
			LatestLocation:           sample.LatestLocation,
			LocationStale:            e.locationStale(sample.LocationRecordedAt),
		}
		if sample.LocationRecordedAt != nil {
			view.LocationRecordedAt = formatTime(*sample.LocationRecordedAt)
		}
		if sample.Exception != nil {
			view.Exception = map[string]any{
				"reason":     sample.Exception.Reason,
				"kind":       sample.Exception.Kind,
				"detail":     sample.Exception.Detail,
				"occurredAt": formatTime(sample.Exception.OccurredAt),
			}
			if sample.Exception.RaisedByID != "" {
				view.Exception["raisedById"] = sample.Exception.RaisedByID
			}
		}
		if h := e.pendingHandoff(sample.SampleID); h != nil {
			view.PendingHandoffID = h.HandoffID
			view.PendingHandoff = map[string]any{
				"handoffId":         h.HandoffID,
				"senderId":          h.SenderID,
				"receiverId":        h.ReceiverID,
				"senderConfirmed":   h.SenderConfirmed,
				"receiverConfirmed": h.ReceiverConfirmed,
				"initiatedAt":       formatTime(h.InitiatedAt),
			}
		}
		return view, nil
	})
}

// activeReplacementPlanIDs lists the live replacement journeys of a sample.
func (e *Engine) activeReplacementPlanIDs(sample *domain.Sample) []string {
	var out []string
	for _, journey := range e.journeys {
		if journey.ReplacesJourneyID == "" || !journey.Unfinished() {
			continue
		}
		if containsString(journey.SampleIDs, sample.SampleID) {
			out = append(out, journey.JourneyID)
		}
	}
	sortStrings(out)
	return stringsOrEmpty(out)
}

// JourneyStopView mirrors the contract stop shape.
type JourneyStopView struct {
	StopID       string            `json:"stopId"`
	LocationID   string            `json:"locationId"`
	StopType     string            `json:"stopType"`
	Sequence     int               `json:"sequence"`
	EstimatedAt  string            `json:"estimatedAt"`
	DwellMinutes int               `json:"dwellMinutes"`
	Coordinate   domain.Coordinate `json:"coordinate"`
	CompletedAt  string            `json:"completedAt,omitempty"`
}

// JourneyLegView mirrors the contract leg shape.
type JourneyLegView struct {
	AssignmentID   string `json:"assignmentId"`
	Sequence       int    `json:"sequence"`
	Status         string `json:"status"`
	FromLocationID string `json:"fromLocationId,omitempty"`
	ToLocationID   string `json:"toLocationId,omitempty"`
	WorkerID       string `json:"workerId,omitempty"`
	SampleID       string `json:"sampleId,omitempty"`
}

// JourneyPlanView is the dispatcher-level journey projection.
type JourneyPlanView struct {
	JourneyID                string            `json:"journeyId"`
	ParentJourneyID          string            `json:"parentJourneyId,omitempty"`
	PlanVersion              int               `json:"planVersion"`
	RouteMode                string            `json:"routeMode"`
	Status                   string            `json:"status"`
	EstimatedDeliveryAt      string            `json:"estimatedDeliveryAt,omitempty"`
	TotalCostUnits           float64           `json:"totalCostUnits"`
	CapacityUsed             int               `json:"capacityUsed"`
	CapacityAvailable        int               `json:"capacityAvailable"`
	SampleIDs                []string          `json:"sampleIds"`
	OrderedStops             []JourneyStopView `json:"orderedStops"`
	Legs                     []JourneyLegView  `json:"legs"`
	AssignedWorkerIDs        []string          `json:"assignedWorkerIds"`
	CollectionAssignmentID   string            `json:"collectionAssignmentId,omitempty"`
	CollectionAssignmentIDs  []string          `json:"collectionAssignmentIds"`
	NodeAssignmentIDs        []string          `json:"nodeAssignmentIds"`
	LaboratoryAssignmentIDs  []string          `json:"laboratoryAssignmentIds"`
	FirstTransportAssignID   string            `json:"firstTransportAssignmentId,omitempty"`
	MiddleTransportAssignID  string            `json:"middleTransportAssignmentId,omitempty"`
	FinalTransportAssignID   string            `json:"finalTransportAssignmentId,omitempty"`
	Valid                    bool              `json:"valid"`
	ReplanStatus             string            `json:"replanStatus,omitempty"`
	SplitJourney             *JourneyPlanView  `json:"splitJourney,omitempty"`
	ReplacementJourney       *JourneyPlanView  `json:"replacementJourney,omitempty"`
}

// journeyPlanView projects a journey. When workerID is set the legs are filtered to that
// worker's own assignments.
func (e *Engine) journeyPlanView(journey *domain.Journey, workerID *string) *JourneyPlanView {
	view := &JourneyPlanView{
		JourneyID:               journey.JourneyID,
		ParentJourneyID:         journey.ParentJourneyID,
		PlanVersion:             journey.PlanVersion,
		RouteMode:               string(journey.RouteMode),
		Status:                  journey.Status,
		TotalCostUnits:          journey.TotalCostUnits,
		SampleIDs:               stringsOrEmpty(journey.SampleIDs),
		OrderedStops:            []JourneyStopView{},
		Legs:                    []JourneyLegView{},
		AssignedWorkerIDs:       []string{},
		CollectionAssignmentIDs: []string{},
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
		Valid:                   journey.Valid,
	}
	if journey.RouteMode == "" {
		view.RouteMode = string(domain.RouteDirect)
	}
	if journey.EstimatedDeliveryAt != nil {
		view.EstimatedDeliveryAt = formatTime(*journey.EstimatedDeliveryAt)
	}
	for _, s := range journey.Stops {
		stop := JourneyStopView{
			StopID:       s.StopID,
			LocationID:   s.LocationID,
			StopType:     string(s.StopType),
			Sequence:     s.Sequence,
			EstimatedAt:  formatTime(s.EstimatedAt),
			DwellMinutes: s.DwellMinutes,
			Coordinate:   s.Coordinate,
		}
		if s.CompletedAt != nil {
			stop.CompletedAt = formatTime(*s.CompletedAt)
		}
		view.OrderedStops = append(view.OrderedStops, stop)
	}

	var transports []*domain.Assignment
	for _, id := range journey.AssignmentIDs {
		a := e.assignments[id]
		if a == nil {
			continue
		}
		if workerID != nil && a.WorkerID != *workerID && a.OfferedToID != *workerID {
			continue
		}
		switch a.Kind {
		case domain.AssignmentCollection:
			view.CollectionAssignmentIDs = append(view.CollectionAssignmentIDs, a.AssignmentID)
			if view.CollectionAssignmentID == "" {
				view.CollectionAssignmentID = a.AssignmentID
			}
		case domain.AssignmentNode:
			view.NodeAssignmentIDs = append(view.NodeAssignmentIDs, a.AssignmentID)
		case domain.AssignmentLaboratory:
			view.LaboratoryAssignmentIDs = append(view.LaboratoryAssignmentIDs, a.AssignmentID)
		case domain.AssignmentTransport:
			transports = append(transports, a)
		}
		if a.Kind == domain.AssignmentCollection || a.Kind == domain.AssignmentTransport {
			view.Legs = append(view.Legs, JourneyLegView{
				AssignmentID:   a.AssignmentID,
				Sequence:       a.Sequence,
				Status:         a.Status,
				FromLocationID: a.FromLocationID,
				ToLocationID:   a.ToLocationID,
				WorkerID:       a.WorkerID,
				SampleID:       a.SampleID,
			})
		}
		if a.WorkerID != "" {
			view.AssignedWorkerIDs = appendUnique(view.AssignedWorkerIDs, a.WorkerID)
		}
	}
	sort.SliceStable(view.Legs, func(i, j int) bool { return view.Legs[i].Sequence < view.Legs[j].Sequence })
	sort.SliceStable(transports, func(i, j int) bool { return transports[i].Sequence < transports[j].Sequence })
	if len(transports) > 0 {
		view.FirstTransportAssignID = transports[0].AssignmentID
		view.FinalTransportAssignID = transports[len(transports)-1].AssignmentID
		if len(transports) > 2 {
			view.MiddleTransportAssignID = transports[1].AssignmentID
		}
	}
	view.CapacityUsed = len(journey.SampleIDs)
	view.CapacityAvailable = e.journeyCapacityAvailable(journey)
	return view
}

// journeyCapacityAvailable is the tightest remaining capacity along the journey.
func (e *Engine) journeyCapacityAvailable(journey *domain.Journey) int {
	available := -1
	cooled := e.journeyRequiresCooled(journey)
	consider := func(c domain.Capacity) {
		v := c.AvailableUnits()
		if cooled {
			v = c.CooledAvailableUnits()
		}
		if available < 0 || v < available {
			available = v
		}
	}
	for _, s := range journey.Stops {
		if loc := e.locations[s.LocationID]; loc != nil {
			consider(loc.Capacity)
		}
	}
	for _, id := range journey.AssignmentIDs {
		a := e.assignments[id]
		if a == nil || a.ConnectionID == "" {
			continue
		}
		if conn := e.connections[a.ConnectionID]; conn != nil {
			consider(conn.Capacity)
		}
	}
	if available < 0 {
		return 0
	}
	return available
}

// RequesterJourneyView hides operational detail a requester does not need.
// planVersion is deliberately absent: it is the dispatcher plan-edit concurrency
// token, and omitting it keeps this projection distinguishable from JourneyPlan
// in the contract's oneOf for read-journey-plan.
type RequesterJourneyView struct {
	JourneyID           string            `json:"journeyId"`
	ParentJourneyID     string            `json:"parentJourneyId,omitempty"`
	RouteMode           string            `json:"routeMode"`
	Status              string            `json:"status"`
	EstimatedDeliveryAt string            `json:"estimatedDeliveryAt,omitempty"`
	TotalCostUnits      float64           `json:"totalCostUnits"`
	SampleIDs           []string          `json:"sampleIds"`
	OrderedStops        []JourneyStopView `json:"orderedStops"`
	Legs                []map[string]any  `json:"legs"`
}

// WorkerJourneyView exposes only the legs assigned to the calling worker.
type WorkerJourneyView struct {
	JourneyID               string            `json:"journeyId"`
	ParentJourneyID         string            `json:"parentJourneyId,omitempty"`
	PlanVersion             int               `json:"planVersion"`
	RouteMode               string            `json:"routeMode"`
	Status                  string            `json:"status"`
	EstimatedDeliveryAt     string            `json:"estimatedDeliveryAt,omitempty"`
	Scope                   string            `json:"scope"`
	AssignmentIDs           []string          `json:"assignmentIds"`
	SampleIDs               []string          `json:"sampleIds"`
	Legs                    []JourneyLegView  `json:"legs"`
	OrderedStops            []JourneyStopView `json:"orderedStops"`
	CollectionAssignmentIDs []string          `json:"collectionAssignmentIds"`
	NodeAssignmentIDs       []string          `json:"nodeAssignmentIds"`
	LaboratoryAssignmentIDs []string          `json:"laboratoryAssignmentIds"`
	AssignedWorkerIDs       []string          `json:"assignedWorkerIds"`
}

// ReadJourneyPlan returns a journey scoped to what the selected role may see.
func (e *Engine) ReadJourneyPlan(p *Principal, journeyID string) (any, error) {
	return e.read(func() (any, error) {
		if p.ActiveRole == "" {
			return nil, errRoleNotSelected()
		}
		journey := e.journeys[journeyID]
		if journey == nil {
			return nil, errNotFound("journey not found")
		}
		switch p.ActiveRole {
		case domain.RoleAdministrator, domain.RoleDispatcher:
			view := e.journeyPlanView(journey, nil)
			if journey.ReplacementID != "" {
				if replacement := e.journeys[journey.ReplacementID]; replacement != nil {
					view.ReplacementJourney = e.journeyPlanView(replacement, nil)
				}
			}
			return view, nil
		case domain.RoleRequester:
			owns := false
			for _, id := range journey.SampleIDs {
				if sample := e.samples[id]; sample != nil && sample.RequesterID == p.User.UserID {
					owns = true
					break
				}
			}
			if !owns {
				return nil, errForbidden("this journey does not belong to you")
			}
			full := e.journeyPlanView(journey, nil)
			legs := make([]map[string]any, 0, len(full.Legs))
			for _, leg := range full.Legs {
				legs = append(legs, map[string]any{
					"assignmentId":   leg.AssignmentID,
					"sequence":       leg.Sequence,
					"status":         leg.Status,
					"fromLocationId": leg.FromLocationID,
					"toLocationId":   leg.ToLocationID,
				})
			}
			return &RequesterJourneyView{
				JourneyID:           full.JourneyID,
				ParentJourneyID:     full.ParentJourneyID,
				PlanVersion:         full.PlanVersion,
				RouteMode:           full.RouteMode,
				Status:              full.Status,
				EstimatedDeliveryAt: full.EstimatedDeliveryAt,
				TotalCostUnits:      full.TotalCostUnits,
				SampleIDs:           full.SampleIDs,
				OrderedStops:        full.OrderedStops,
				Legs:                legs,
			}, nil
		}

		// Workers see only the legs they are responsible for.
		mine := e.journeyPlanView(journey, &p.User.UserID)
		assignmentIDs := []string{}
		stopIDs := map[string]bool{}
		sampleIDs := []string{}
		for _, id := range journey.AssignmentIDs {
			a := e.assignments[id]
			if a == nil || (a.WorkerID != p.User.UserID && a.OfferedToID != p.User.UserID) {
				continue
			}
			assignmentIDs = append(assignmentIDs, a.AssignmentID)
			if a.PickupStopID != "" {
				stopIDs[a.PickupStopID] = true
			}
			if a.DropoffStopID != "" {
				stopIDs[a.DropoffStopID] = true
			}
			for _, sampleID := range a.Samples() {
				sampleIDs = appendUnique(sampleIDs, sampleID)
			}
		}
		if len(assignmentIDs) == 0 {
			return nil, errForbidden("you have no assigned work on this journey")
		}
		stops := make([]JourneyStopView, 0, len(stopIDs))
		for _, s := range mine.OrderedStops {
			if stopIDs[s.StopID] {
				stops = append(stops, s)
			}
		}
		return &WorkerJourneyView{
			JourneyID:               journey.JourneyID,
			ParentJourneyID:         journey.ParentJourneyID,
			PlanVersion:             journey.PlanVersion,
			RouteMode:               mine.RouteMode,
			Status:                  journey.Status,
			EstimatedDeliveryAt:     mine.EstimatedDeliveryAt,
			Scope:                   "assigned_legs",
			AssignmentIDs:           assignmentIDs,
			SampleIDs:               stringsOrEmpty(sampleIDs),
			Legs:                    mine.Legs,
			OrderedStops:            stops,
			CollectionAssignmentIDs: mine.CollectionAssignmentIDs,
			NodeAssignmentIDs:       mine.NodeAssignmentIDs,
			LaboratoryAssignmentIDs: mine.LaboratoryAssignmentIDs,
			AssignedWorkerIDs:       []string{p.User.UserID},
		}, nil
	})
}

// RoleWorkView groups work into pending, in-progress and completed buckets.
type RoleWorkView struct {
	Pending    []any `json:"pending"`
	InProgress []any `json:"inProgress"`
	Completed  []any `json:"completed"`
}

// ListRoleWork returns the caller's current and past work for the selected role.
func (e *Engine) ListRoleWork(p *Principal, requestedRole domain.Role, statusFilter string) (any, error) {
	return e.read(func() (any, error) {
		if p.ActiveRole == "" {
			return nil, errRoleNotSelected()
		}
		role := p.ActiveRole
		if requestedRole != "" {
			if !domain.ValidRole(requestedRole) {
				return nil, errBadRequest("invalid_role", "unknown role")
			}
			// Work views must follow the role the session is acting under.
			if requestedRole != p.ActiveRole {
				return nil, errForbidden("the requested role is not the selected active role")
			}
			role = requestedRole
		}

		out := &RoleWorkView{Pending: []any{}, InProgress: []any{}, Completed: []any{}}
		switch role {
		case domain.RoleRequester:
			e.collectRequesterWork(p, out)
		case domain.RoleDispatcher, domain.RoleAdministrator:
			e.collectOperationsWork(out)
		default:
			e.collectAssignmentWork(p, role, out)
		}
		filterRoleWork(out, statusFilter)
		return out, nil
	})
}

// SampleWorkItemView is a requester-facing work row.
type SampleWorkItemView struct {
	Kind                 string          `json:"kind"`
	SampleID             string          `json:"sampleId"`
	RequestID            string          `json:"requestId"`
	Status               string          `json:"status"`
	Serviceability       string          `json:"serviceability,omitempty"`
	RequestedAt          string          `json:"requestedAt,omitempty"`
	DeliveryDeadline     string          `json:"deliveryDeadline,omitempty"`
	EarliestCollectionAt string          `json:"earliestCollectionAt,omitempty"`
	LatestCollectionAt   string          `json:"latestCollectionAt,omitempty"`
	JourneyID            string          `json:"journeyId,omitempty"`
	ActiveJourneyID      string          `json:"activeJourneyId,omitempty"`
	LaboratoryID         string          `json:"laboratoryId,omitempty"`
	CurrentHolderID      string          `json:"currentHolderId,omitempty"`
	RequesterID          string          `json:"requesterId,omitempty"`
	History              []TimelineEntry `json:"history"`
	LocationRecordedAt   string          `json:"locationRecordedAt,omitempty"`
	LocationStale        bool            `json:"locationStale"`
}

func (e *Engine) sampleWorkItem(sample *domain.Sample) *SampleWorkItemView {
	item := &SampleWorkItemView{
		Kind:                 "sample",
		SampleID:             sample.SampleID,
		RequestID:            sample.RequestID,
		Status:               sample.Status,
		Serviceability:       sample.Serviceability,
		RequestedAt:          formatTime(sample.RequestedAt),
		DeliveryDeadline:     formatTime(sample.DeliveryDeadline),
		EarliestCollectionAt: formatTime(sample.EarliestCollectionAt),
		LatestCollectionAt:   formatTime(sample.LatestCollectionAt),
		JourneyID:            sample.ActiveJourneyID,
		ActiveJourneyID:      sample.ActiveJourneyID,
		LaboratoryID:         sample.TargetLaboratoryID,
		CurrentHolderID:      sample.CurrentHolderID,
		RequesterID:          sample.RequesterID,
		History:              e.timeline(sample.SampleID),
		LocationStale:        e.locationStale(sample.LocationRecordedAt),
	}
	if sample.LocationRecordedAt != nil {
		item.LocationRecordedAt = formatTime(*sample.LocationRecordedAt)
	}
	return item
}

func (e *Engine) collectRequesterWork(p *Principal, out *RoleWorkView) {
	var samples []*domain.Sample
	for _, sample := range e.samples {
		if sample.RequesterID == p.User.UserID {
			samples = append(samples, sample)
		}
	}
	sort.Slice(samples, func(i, j int) bool { return samples[i].CreatedAt.Before(samples[j].CreatedAt) })
	for _, sample := range samples {
		item := e.sampleWorkItem(sample)
		switch {
		case sample.Terminal() || sample.Status == domain.SampleStatusException:
			out.Completed = append(out.Completed, item)
		case sample.Status == domain.SampleStatusRequested:
			out.Pending = append(out.Pending, item)
		default:
			out.InProgress = append(out.InProgress, item)
		}
	}
}

// JourneyWorkItemView is a dispatcher-facing work row.
type JourneyWorkItemView struct {
	Kind                string          `json:"kind"`
	JourneyID           string          `json:"journeyId"`
	Status              string          `json:"status"`
	RouteMode           string          `json:"routeMode"`
	PlanVersion         int             `json:"planVersion"`
	SampleIDs           []string        `json:"sampleIds"`
	EstimatedDeliveryAt string          `json:"estimatedDeliveryAt"`
	AssignmentCount     int             `json:"assignmentCount"`
	History             []TimelineEntry `json:"history"`
}

func (e *Engine) collectOperationsWork(out *RoleWorkView) {
	var journeys []*domain.Journey
	for _, journey := range e.journeys {
		journeys = append(journeys, journey)
	}
	sort.Slice(journeys, func(i, j int) bool { return journeys[i].CreatedAt.Before(journeys[j].CreatedAt) })
	for _, journey := range journeys {
		item := &JourneyWorkItemView{
			Kind:            "journey",
			JourneyID:       journey.JourneyID,
			Status:          journey.Status,
			RouteMode:       string(journey.RouteMode),
			PlanVersion:     journey.PlanVersion,
			SampleIDs:       stringsOrEmpty(journey.SampleIDs),
			AssignmentCount: len(journey.AssignmentIDs),
			History:         e.timeline(journey.JourneyID),
		}
		if journey.EstimatedDeliveryAt != nil {
			item.EstimatedDeliveryAt = formatTime(*journey.EstimatedDeliveryAt)
		}
		if item.RouteMode == "" {
			item.RouteMode = string(domain.RouteDirect)
		}
		switch journey.Status {
		case domain.JourneyStatusPlanned:
			out.Pending = append(out.Pending, item)
		case domain.JourneyStatusActive:
			out.InProgress = append(out.InProgress, item)
		default:
			out.Completed = append(out.Completed, item)
		}
	}
}

// AssignmentWorkItemView is a worker-facing work row.
type AssignmentWorkItemView struct {
	Kind                   string           `json:"kind"`
	AssignmentID           string           `json:"assignmentId"`
	SampleID               string           `json:"sampleId"`
	Status                 string           `json:"status"`
	JourneyID              string           `json:"journeyId,omitempty"`
	FromLocationID         string           `json:"fromLocationId,omitempty"`
	ToLocationID           string           `json:"toLocationId,omitempty"`
	Sequence               int              `json:"sequence"`
	OfferExpiresAt         string           `json:"offerExpiresAt,omitempty"`
	DestinationCapacity    *CapacityView    `json:"destinationCapacity,omitempty"`
	NodeID                 string           `json:"nodeId,omitempty"`
	IncomingFromLocationID string           `json:"incomingFromLocationId,omitempty"`
	OutgoingToLocationID   string           `json:"outgoingToLocationId,omitempty"`
	LaboratoryID           string           `json:"laboratoryId,omitempty"`
	ExpectedSampleTypeID   string           `json:"expectedSampleTypeId,omitempty"`
	History                []TimelineEntry  `json:"history"`
}

// CapacityView exposes configured, reserved and available units for both pools.
type CapacityView struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func capacityView(c domain.Capacity) *CapacityView {
	return &CapacityView{
		CapacityUnits:        c.CapacityUnits,
		ReservedUnits:        c.ReservedUnits,
		AvailableUnits:       c.AvailableUnits(),
		CooledCapacityUnits:  c.CooledCapacityUnits,
		CooledReservedUnits:  c.CooledReservedUnits,
		CooledAvailableUnits: c.CooledAvailableUnits(),
	}
}

func (e *Engine) collectAssignmentWork(p *Principal, role domain.Role, out *RoleWorkView) {
	var list []*domain.Assignment
	for _, a := range e.assignments {
		if a.RequiredRole != role {
			continue
		}
		// A worker sees offers addressed to them and the work they accepted.
		if a.WorkerID != p.User.UserID && a.OfferedToID != p.User.UserID {
			continue
		}
		list = append(list, a)
	}
	sort.Slice(list, func(i, j int) bool {
		if list[i].CreatedAt.Equal(list[j].CreatedAt) {
			return list[i].Sequence < list[j].Sequence
		}
		return list[i].CreatedAt.Before(list[j].CreatedAt)
	})

	for _, a := range list {
		item := &AssignmentWorkItemView{
			Kind:                   a.Kind,
			AssignmentID:           a.AssignmentID,
			SampleID:               a.SampleID,
			Status:                 a.Status,
			JourneyID:              a.JourneyID,
			FromLocationID:         a.FromLocationID,
			ToLocationID:           a.ToLocationID,
			Sequence:               a.Sequence,
			NodeID:                 a.NodeID,
			LaboratoryID:           a.LaboratoryID,
			IncomingFromLocationID: a.FromLocationID,
			OutgoingToLocationID:   a.ToLocationID,
			History:                e.timeline(a.AssignmentID),
		}
		if a.OfferExpiresAt != nil {
			item.OfferExpiresAt = formatTime(*a.OfferExpiresAt)
		}
		if sample := e.samples[a.SampleID]; sample != nil {
			item.ExpectedSampleTypeID = sample.SampleTypeID
		}
		// Node and laboratory workers need the capacity of their own site.
		switch a.Kind {
		case domain.AssignmentNode:
			if loc := e.locations[a.NodeID]; loc != nil {
				item.DestinationCapacity = capacityView(loc.Capacity)
			}
		case domain.AssignmentLaboratory:
			if loc := e.locations[a.LaboratoryID]; loc != nil {
				item.DestinationCapacity = capacityView(loc.Capacity)
			}
		default:
			if loc := e.locations[a.ToLocationID]; loc != nil {
				item.DestinationCapacity = capacityView(loc.Capacity)
			}
		}

		switch {
		case a.Status == domain.AssignStatusPending || a.Status == domain.AssignStatusOffered:
			out.Pending = append(out.Pending, item)
		case a.Terminal():
			out.Completed = append(out.Completed, item)
		default:
			out.InProgress = append(out.InProgress, item)
		}
	}
}

// filterRoleWork narrows the buckets when the caller asked for one status group.
func filterRoleWork(out *RoleWorkView, status string) {
	switch strings.ToLower(strings.TrimSpace(status)) {
	case "", "all":
		return
	case "pending", "offered":
		out.InProgress, out.Completed = []any{}, []any{}
	case "inprogress", "in_progress", "active", "current":
		out.Pending, out.Completed = []any{}, []any{}
	case "completed", "past", "done":
		out.Pending, out.InProgress = []any{}, []any{}
	}
}

