func validProgressTransition(from, to string) bool {
	fromRank, okFrom := progressOrder[from]
	toRank, okTo := progressOrder[to]
	if !okFrom || !okTo {
		return false
	}
	// Re-reporting the phase already reached is a no-op, not backward movement:
	// a custody handoff can advance the leg before the worker's own ping arrives.
	return toRank >= fromRank
}

