// the only work bounded by the worker's personal capacityUnits cap. Node and laboratory
// postings are bounded by their site's capacity pools instead.
func (e *Engine) carryAssignmentCount(workerID string) int {
	n := 0
	for _, a := range e.assignments {
		if a.WorkerID != workerID || a.Terminal() {
			continue
		}
		switch a.Kind {
		case domain.AssignmentNode, domain.AssignmentLaboratory:
		default:
			n++
		}
	}
	return n
}

